window.WEEKDOT_I18N = {"en":{"nav.features":"Features","nav.devices":"Devices","nav.faq":"FAQ","nav.support":"Support","nav.privacy":"Privacy","meta.description":"Weekdot is a fast, beautiful calendar for iPhone, iPad, Apple Watch and Mac with day, week, month and year views.","hero.title":"Your week at a glance.","hero.sub":"Weekdot is a fast, beautiful calendar for iPhone, iPad, Apple Watch and Mac. Day, week, month and year views, with colours, emoji and templates — on top of the calendars you already use.","hero.cta":"Coming soon to the App Store","hero.note":"Works with iCloud, Google, Outlook, Exchange and every calendar in the Calendar app.","features.title":"Everything you plan, in one view","f1.t":"Week view with 7 days","f1.d":"See your whole week at once. Choose 1 to 7 days, start the week on any day and pinch to zoom the hours.","f2.t":"Day, month and year","f2.d":"Zoom out to a month with event names or a year with your busy days, and tap to jump right in.","f3.t":"Drag, copy & paste","f3.d":"Move events by dragging, change their length, copy them to another day or duplicate them in one tap.","f4.t":"Colours & emoji","f4.d":"Give events their own colour and emoji, or let rules do it automatically based on the title.","f5.t":"Templates","f5.d":"Save events you plan often and add them in one tap. Weekdot also suggests details from earlier events.","f6.t":"All your calendars","f6.d":"Show, hide and group calendars into sets, create new ones, subscribe to holidays or any .ics link.","f7.t":"Synced with iCloud","f7.d":"Your settings, templates, sets, rules, colours and emoji are the same on every device.","f8.t":"Widgets & Apple Watch","f8.d":"Today, Up Next and Week widgets, plus a watch app for your day and week at a glance.","f9.t":"In your language","f9.d":"Weekdot speaks more than 30 languages and follows the language of your device.","f10.t":"Weather","f10.d":"Optionally see the forecast above your days.","devices.title":"On all your Apple devices","devices.sub":"One app for iPhone, iPad, Mac and Apple Watch.","faq.title":"Questions","q1":"Does Weekdot replace my calendar accounts?","a1":"No. Weekdot shows and edits the calendars from the Calendar app, so everything keeps syncing through iCloud, Google, Outlook or Exchange.","q2":"Where is my data stored?","a2":"Your events stay in your own calendar accounts. Weekdot's own settings sync through your private iCloud. Weekdot has no servers that store your data.","q3":"Which languages are supported?","a3":"More than 30, including English, Dutch, German, French, Spanish, Italian, Portuguese, Chinese, Japanese, Korean and Arabic.","q4":"Can I add holidays?","a4":"Yes. Subscribe to public holidays for many countries with one tap, or paste any .ics link.","privacy.title":"Privacy","privacy.p1":"Weekdot is built to keep your data yours.","privacy.p2":"Calendar data: Weekdot reads and writes events only in the calendar accounts on your device (the Calendar app). Your events are never sent to us.","privacy.p3":"iCloud: Weekdot's own settings, templates, calendar sets, rules, colours and emoji are stored in your private iCloud so they sync between your devices. We cannot access them.","privacy.p4":"Weather (optional): when you turn on weather, your approximate location is sent to Open-Meteo to get a forecast. Weekdot does not store it.","privacy.p5":"No accounts, no tracking, no ads and no analytics.","privacy.p6":"Questions? Get in touch through the support page.","privacy.updated":"Last updated: 24 October 2026","support.title":"Help & Support","s1.q":"Weekdot shows no events","s1.a":"Allow full calendar access: Settings › Privacy & Security › Calendars › Weekdot › Full Access.","s2.q":"How do I add a Google or Outlook calendar?","s2.a":"Add the account in Settings › Apps › Calendar › Calendar Accounts (Mac: Calendar app › Add Account). Weekdot shows it automatically.","s3.q":"How do I change the language?","s3.a":"Weekdot follows the language of your device. On iPhone and iPad you can choose a language for Weekdot only in Settings › Apps › Weekdot › Language.","s4.q":"Why doesn't the app icon show today's date?","s4.a":"Only Apple's own Calendar app can change its icon by itself. Add the Weekdot ‘Today’ widget to your Home Screen for a live date. On the Mac, the Dock icon shows today's date while Weekdot is open.","s5.q":"Do my colours and templates sync?","s5.a":"Yes, through iCloud. Make sure you are signed in to iCloud with the same Apple Account on all your devices.","footer.rights":"All rights reserved.","lang.label":"Language","mock.Meeting":"Meeting","mock.Lunch":"Lunch","mock.Gym":"Gym","mock.Dentist":"Dentist","mock.Birthday":"Birthday","mock.Flight":"Flight","mock.Holiday":"Holiday","mock.Day":"Day","mock.Week":"Week","mock.Month":"Month","mock.Year":"Year","mock.List":"List","mock.Today":"Today","mock.Calendars":"Calendars","mock.Color":"Color","mock.Birthdays":"Birthdays","mock.Doctor":"Doctor"},"ar":{"nav.features":"الميزات","nav.devices":"الأجهزة","nav.faq":"الأسئلة الشائعة","nav.support":"الدعم","nav.privacy":"الخصوصية","meta.description":"Weekdot تقويم سريع وجميل لـ iPhone وiPad وApple Watch وMac مع عروض اليوم والأسبوع والشهر والسنة.","hero.title":"أسبوعك في لمحة.","hero.sub":"Weekdot تقويم سريع وجميل لـ iPhone وiPad وApple Watch وMac. عروض اليوم والأسبوع والشهر والسنة، مع الألوان والإيموجي والقوالب، فوق التقويمات التي تستخدمها بالفعل.","hero.cta":"قريبًا على App Store","hero.note":"يعمل مع iCloud وGoogle وOutlook وExchange وكل تقويم في تطبيق التقويم.","features.title":"كل ما تخطط له في عرض واحد","f1.t":"عرض الأسبوع بـ 7 أيام","f1.d":"شاهد أسبوعك كاملًا دفعة واحدة. اختر من 1 إلى 7 أيام، وابدأ الأسبوع بأي يوم، واقرص لتكبير الساعات.","f2.t":"اليوم والشهر والسنة","f2.d":"صغّر العرض إلى شهر بأسماء الأحداث أو سنة بأيامك المزدحمة، واضغط للانتقال مباشرةً.","f3.t":"السحب والنسخ واللصق","f3.d":"انقل الأحداث بالسحب، وغيّر مدتها، وانسخها إلى يوم آخر أو كرّرها بضغطة واحدة.","f4.t":"الألوان والإيموجي","f4.d":"امنح الأحداث لونها وإيموجي خاصين بها، أو دع القواعد تفعل ذلك تلقائيًا بناءً على العنوان.","f5.t":"القوالب","f5.d":"احفظ الأحداث التي تخطط لها كثيرًا وأضفها بضغطة واحدة. يقترح Weekdot أيضًا تفاصيل من الأحداث السابقة.","f6.t":"كل تقويماتك","f6.d":"اعرض التقويمات وأخفها وجمّعها في مجموعات، وأنشئ تقويمات جديدة، واشترك في العطلات أو أي رابط .ics.","f7.t":"متزامن مع iCloud","f7.d":"إعداداتك وقوالبك ومجموعاتك وقواعدك وألوانك والإيموجي هي نفسها على كل جهاز.","f8.t":"الأدوات وApple Watch","f8.d":"أدوات اليوم والتالي والأسبوع، إلى جانب تطبيق للساعة يعرض يومك وأسبوعك في لمحة.","f9.t":"بلغتك","f9.d":"يتحدث Weekdot أكثر من 30 لغة ويتبع لغة جهازك.","f10.t":"الطقس","f10.d":"شاهد التوقعات فوق أيامك إن أردت.","devices.title":"على جميع أجهزة Apple لديك","devices.sub":"تطبيق واحد لـ iPhone وiPad وMac وApple Watch.","faq.title":"أسئلة","q1":"هل يحل Weekdot محل حسابات التقويم لديّ؟","a1":"لا. يعرض Weekdot التقويمات من تطبيق التقويم ويعدّلها، لذا تستمر المزامنة عبر iCloud أو Google أو Outlook أو Exchange.","q2":"أين تُخزَّن بياناتي؟","a2":"تبقى أحداثك في حسابات التقويم الخاصة بك. تتم مزامنة إعدادات Weekdot الخاصة عبر iCloud الخاص بك. ليس لدى Weekdot خوادم تخزّن بياناتك.","q3":"ما اللغات المدعومة؟","a3":"أكثر من 30 لغة، منها الإنجليزية والهولندية والألمانية والفرنسية والإسبانية والإيطالية والبرتغالية والصينية واليابانية والكورية والعربية.","q4":"هل يمكنني إضافة العطلات؟","a4":"نعم. اشترك في العطلات الرسمية لعدد كبير من البلدان بضغطة واحدة، أو الصق أي رابط .ics.","privacy.title":"الخصوصية","privacy.p1":"صُمّم Weekdot لتبقى بياناتك ملكك.","privacy.p2":"بيانات التقويم: يقرأ Weekdot الأحداث ويكتبها فقط في حسابات التقويم على جهازك (تطبيق التقويم). لا تُرسَل أحداثك إلينا أبدًا.","privacy.p3":"iCloud: تُخزَّن إعدادات Weekdot الخاصة والقوالب ومجموعات التقويمات والقواعد والألوان والإيموجي في iCloud الخاص بك لتتم مزامنتها بين أجهزتك. لا يمكننا الوصول إليها.","privacy.p4":"الطقس (اختياري): عند تشغيل الطقس، يُرسَل موقعك التقريبي إلى Open-Meteo للحصول على التوقعات. لا يخزّنه Weekdot.","privacy.p5":"بلا حسابات، بلا تتبع، بلا إعلانات وبلا تحليلات.","privacy.p6":"لديك أسئلة؟ تواصل معنا عبر صفحة الدعم.","privacy.updated":"آخر تحديث: 24 أكتوبر 2026","support.title":"المساعدة والدعم","s1.q":"لا يعرض Weekdot أي أحداث","s1.a":"اسمح بالوصول الكامل إلى التقويم: الإعدادات › الخصوصية والأمن › التقويمات › Weekdot › وصول كامل.","s2.q":"كيف أضيف تقويم Google أو Outlook؟","s2.a":"أضف الحساب في الإعدادات › التطبيقات › التقويم › حسابات التقويم (Mac: تطبيق التقويم › إضافة حساب). سيعرضه Weekdot تلقائيًا.","s3.q":"كيف أغيّر اللغة؟","s3.a":"يتبع Weekdot لغة جهازك. على iPhone وiPad يمكنك اختيار لغة لـ Weekdot فقط في الإعدادات › التطبيقات › Weekdot › اللغة.","s4.q":"لماذا لا تعرض أيقونة التطبيق تاريخ اليوم؟","s4.a":"تطبيق التقويم من Apple وحده يمكنه تغيير أيقونته بنفسه. أضف أداة ‘اليوم’ من Weekdot إلى الشاشة الرئيسية لرؤية التاريخ مباشرةً. على Mac، تعرض أيقونة Dock تاريخ اليوم أثناء فتح Weekdot.","s5.q":"هل تتم مزامنة ألواني وقوالبي؟","s5.a":"نعم، عبر iCloud. تأكد من تسجيل الدخول إلى iCloud بحساب Apple نفسه على جميع أجهزتك.","footer.rights":"جميع الحقوق محفوظة.","lang.label":"اللغة","mock.Meeting":"اجتماع","mock.Lunch":"غداء","mock.Gym":"نادٍ رياضي","mock.Dentist":"طبيب أسنان","mock.Birthday":"عيد ميلاد","mock.Flight":"رحلة","mock.Holiday":"عطلة","mock.Day":"يوم","mock.Week":"أسبوع","mock.Month":"شهر","mock.Year":"سنة","mock.List":"قائمة","mock.Today":"اليوم","mock.Calendars":"التقويمات","mock.Color":"اللون","mock.Birthdays":"أعياد الميلاد","mock.Doctor":"طبيب"},"ca":{"nav.features":"Funcions","nav.devices":"Dispositius","nav.faq":"PMF","nav.support":"Suport","nav.privacy":"Privacitat","meta.description":"El Weekdot és un calendari ràpid i bonic per a l’iPhone, l’iPad, l’Apple Watch i el Mac amb vistes de dia, setmana, mes i any.","hero.title":"La teva setmana d’un cop d’ull.","hero.sub":"El Weekdot és un calendari ràpid i bonic per a l’iPhone, l’iPad, l’Apple Watch i el Mac. Vistes de dia, setmana, mes i any, amb colors, emojis i plantilles, damunt dels calendaris que ja utilitzes.","hero.cta":"Aviat a l’App Store","hero.note":"Funciona amb iCloud, Google, Outlook, Exchange i tots els calendaris de l’app Calendari.","features.title":"Tot el que planifiques, en una sola vista","f1.t":"Vista de setmana de 7 dies","f1.d":"Mira tota la setmana d’un cop. Tria d’1 a 7 dies, comença la setmana el dia que vulguis i pinça per ampliar les hores.","f2.t":"Dia, mes i any","f2.d":"Allunya’t fins a un mes amb els noms dels esdeveniments o un any amb els dies ocupats, i toca per anar-hi directament.","f3.t":"Arrossega, copia i enganxa","f3.d":"Mou els esdeveniments arrossegant-los, canvia’n la durada, copia’ls a un altre dia o duplica’ls amb un toc.","f4.t":"Colors i emojis","f4.d":"Dona als esdeveniments el seu propi color i emoji, o deixa que les regles ho facin automàticament segons el títol.","f5.t":"Plantilles","f5.d":"Desa els esdeveniments que planifiques sovint i afegeix-los amb un toc. El Weekdot també suggereix detalls d’esdeveniments anteriors.","f6.t":"Tots els teus calendaris","f6.d":"Mostra, amaga i agrupa calendaris en conjunts, crea’n de nous i subscriu-te a festius o a qualsevol enllaç .ics.","f7.t":"Sincronitzat amb iCloud","f7.d":"La configuració, les plantilles, els conjunts, les regles, els colors i els emojis són iguals a tots els dispositius.","f8.t":"Widgets i Apple Watch","f8.d":"Widgets d’Avui, A continuació i Setmana, a més d’una app per al rellotge per veure el dia i la setmana d’un cop d’ull.","f9.t":"En el teu idioma","f9.d":"El Weekdot parla més de 30 idiomes i segueix l’idioma del dispositiu.","f10.t":"Temps","f10.d":"Si vols, mira la previsió damunt dels teus dies.","devices.title":"A tots els teus dispositius Apple","devices.sub":"Una sola app per a l’iPhone, l’iPad, el Mac i l’Apple Watch.","faq.title":"Preguntes","q1":"El Weekdot substitueix els meus comptes de calendari?","a1":"No. El Weekdot mostra i edita els calendaris de l’app Calendari, de manera que tot continua sincronitzant-se amb iCloud, Google, Outlook o Exchange.","q2":"On es desen les meves dades?","a2":"Els teus esdeveniments es queden als teus comptes de calendari. La configuració del Weekdot se sincronitza amb el teu iCloud privat. El Weekdot no té servidors que desin les teves dades.","q3":"Quins idiomes s’admeten?","a3":"Més de 30, entre els quals l’anglès, el neerlandès, l’alemany, el francès, el castellà, l’italià, el portuguès, el xinès, el japonès, el coreà i l’àrab.","q4":"Puc afegir festius?","a4":"Sí. Subscriu-te als festius oficials de molts països amb un toc, o enganxa qualsevol enllaç .ics.","privacy.title":"Privacitat","privacy.p1":"El Weekdot està pensat perquè les teves dades siguin teves.","privacy.p2":"Dades del calendari: el Weekdot llegeix i escriu esdeveniments només als comptes de calendari del dispositiu (l’app Calendari). Els teus esdeveniments mai no se’ns envien.","privacy.p3":"iCloud: la configuració, les plantilles, els conjunts de calendaris, les regles, els colors i els emojis del Weekdot es desen al teu iCloud privat perquè se sincronitzin entre els teus dispositius. Nosaltres no hi tenim accés.","privacy.p4":"Temps (opcional): quan actives el temps, la teva ubicació aproximada s’envia a Open-Meteo per obtenir una previsió. El Weekdot no la desa.","privacy.p5":"Sense comptes, sense seguiment, sense anuncis i sense analítiques.","privacy.p6":"Tens preguntes? Posa’t en contacte amb nosaltres a la pàgina de suport.","privacy.updated":"Última actualització: 24 d’octubre de 2026","support.title":"Ajuda i suport","s1.q":"El Weekdot no mostra cap esdeveniment","s1.a":"Permet l’accés complet al calendari: Configuració › Privacitat i seguretat › Calendaris › Weekdot › Accés complet.","s2.q":"Com afegeixo un calendari de Google o Outlook?","s2.a":"Afegeix el compte a Configuració › Apps › Calendari › Comptes de calendari (Mac: app Calendari › Afegeix un compte). El Weekdot el mostra automàticament.","s3.q":"Com canvio l’idioma?","s3.a":"El Weekdot segueix l’idioma del dispositiu. A l’iPhone i l’iPad pots triar un idioma només per al Weekdot a Configuració › Apps › Weekdot › Idioma.","s4.q":"Per què la icona de l’app no mostra la data d’avui?","s4.a":"Només l’app Calendari d’Apple pot canviar la seva icona per si mateixa. Afegeix el widget ‘Avui’ del Weekdot a la pantalla d’inici per veure la data en directe. Al Mac, la icona del Dock mostra la data d’avui mentre el Weekdot està obert.","s5.q":"Els meus colors i plantilles se sincronitzen?","s5.a":"Sí, amb iCloud. Assegura’t que has iniciat sessió a iCloud amb el mateix compte d’Apple a tots els teus dispositius.","footer.rights":"Tots els drets reservats.","lang.label":"Idioma","mock.Meeting":"Reunió","mock.Lunch":"Dinar","mock.Gym":"Gimnàs","mock.Dentist":"Dentista","mock.Birthday":"Aniversari","mock.Flight":"Vol","mock.Holiday":"Vacances","mock.Day":"Dia","mock.Week":"Setmana","mock.Month":"Mes","mock.Year":"Any","mock.List":"Llista","mock.Today":"Avui","mock.Calendars":"Calendaris","mock.Color":"Color","mock.Birthdays":"Aniversaris","mock.Doctor":"Metge"},"cs":{"nav.features":"Funkce","nav.devices":"Zařízení","nav.faq":"Časté dotazy","nav.support":"Podpora","nav.privacy":"Soukromí","meta.description":"Weekdot je rychlý a krásný kalendář pro iPhone, iPad, Apple Watch a Mac se zobrazením dne, týdne, měsíce a roku.","hero.title":"Váš týden na první pohled.","hero.sub":"Weekdot je rychlý a krásný kalendář pro iPhone, iPad, Apple Watch a Mac. Zobrazení dne, týdne, měsíce a roku s barvami, emoji a šablonami – nad kalendáři, které už používáte.","hero.cta":"Brzy v App Store","hero.note":"Funguje s iCloudem, Googlem, Outlookem, Exchange a všemi kalendáři v aplikaci Kalendář.","features.title":"Vše, co plánujete, v jednom zobrazení","f1.t":"Zobrazení týdne se 7 dny","f1.d":"Uvidíte celý týden najednou. Zvolte 1 až 7 dní, začněte týden libovolným dnem a roztažením prstů zvětšete hodiny.","f2.t":"Den, měsíc a rok","f2.d":"Oddalte se na měsíc s názvy událostí nebo na rok s rušnými dny a klepnutím do nich hned skočte.","f3.t":"Přetahování, kopírování a vkládání","f3.d":"Přesouvejte události přetažením, měňte jejich délku, kopírujte je na jiný den nebo je jedním klepnutím duplikujte.","f4.t":"Barvy a emoji","f4.d":"Dejte událostem vlastní barvu a emoji, nebo to nechte automaticky udělat pravidla podle názvu.","f5.t":"Šablony","f5.d":"Uložte si události, které plánujete často, a přidávejte je jedním klepnutím. Weekdot také navrhuje údaje z dřívějších událostí.","f6.t":"Všechny vaše kalendáře","f6.d":"Zobrazujte, skrývejte a seskupujte kalendáře do sad, vytvářejte nové, odebírejte svátky nebo jakýkoli odkaz .ics.","f7.t":"Synchronizováno přes iCloud","f7.d":"Vaše nastavení, šablony, sady, pravidla, barvy a emoji jsou stejné na každém zařízení.","f8.t":"Widgety a Apple Watch","f8.d":"Widgety Dnes, Následuje a Týden a k tomu aplikace pro hodinky s přehledem dne a týdne.","f9.t":"Ve vašem jazyce","f9.d":"Weekdot mluví více než 30 jazyky a používá jazyk vašeho zařízení.","f10.t":"Počasí","f10.d":"Volitelně uvidíte předpověď nad svými dny.","devices.title":"Na všech vašich zařízeních Apple","devices.sub":"Jedna aplikace pro iPhone, iPad, Mac a Apple Watch.","faq.title":"Otázky","q1":"Nahrazuje Weekdot mé kalendářové účty?","a1":"Ne. Weekdot zobrazuje a upravuje kalendáře z aplikace Kalendář, takže se vše dál synchronizuje přes iCloud, Google, Outlook nebo Exchange.","q2":"Kde jsou uložena moje data?","a2":"Vaše události zůstávají ve vašich vlastních kalendářových účtech. Vlastní nastavení Weekdot se synchronizují přes váš soukromý iCloud. Weekdot nemá žádné servery, které by ukládaly vaše data.","q3":"Které jazyky jsou podporovány?","a3":"Více než 30, mimo jiné angličtina, nizozemština, němčina, francouzština, španělština, italština, portugalština, čínština, japonština, korejština a arabština.","q4":"Mohu přidat svátky?","a4":"Ano. Jedním klepnutím odebírejte státní svátky mnoha zemí, nebo vložte jakýkoli odkaz .ics.","privacy.title":"Soukromí","privacy.p1":"Weekdot je navržen tak, aby vaše data zůstala vaše.","privacy.p2":"Data kalendáře: Weekdot čte a zapisuje události pouze v kalendářových účtech ve vašem zařízení (aplikace Kalendář). Vaše události nám nikdy nejsou odesílány.","privacy.p3":"iCloud: Vlastní nastavení, šablony, sady kalendářů, pravidla, barvy a emoji aplikace Weekdot se ukládají ve vašem soukromém iCloudu, aby se synchronizovaly mezi vašimi zařízeními. Nemáme k nim přístup.","privacy.p4":"Počasí (volitelné): když zapnete počasí, vaše přibližná poloha se odešle do Open-Meteo kvůli předpovědi. Weekdot ji neukládá.","privacy.p5":"Žádné účty, žádné sledování, žádné reklamy a žádná analytika.","privacy.p6":"Máte dotazy? Kontaktujte nás přes stránku podpory.","privacy.updated":"Poslední aktualizace: 24. října 2026","support.title":"Nápověda a podpora","s1.q":"Weekdot nezobrazuje žádné události","s1.a":"Povolte plný přístup ke kalendářům: Nastavení › Soukromí a zabezpečení › Kalendáře › Weekdot › Plný přístup.","s2.q":"Jak přidám kalendář Google nebo Outlook?","s2.a":"Přidejte účet v Nastavení › Aplikace › Kalendář › Účty kalendáře (Mac: aplikace Kalendář › Přidat účet). Weekdot ho zobrazí automaticky.","s3.q":"Jak změním jazyk?","s3.a":"Weekdot používá jazyk vašeho zařízení. Na iPhonu a iPadu můžete zvolit jazyk jen pro Weekdot v Nastavení › Aplikace › Weekdot › Jazyk.","s4.q":"Proč ikona aplikace neukazuje dnešní datum?","s4.a":"Svou ikonu umí sama měnit jen vlastní aplikace Kalendář od Applu. Přidejte si na plochu widget Weekdot ‚Dnes‘ s aktuálním datem. Na Macu ukazuje ikona v Docku dnešní datum, když je Weekdot otevřený.","s5.q":"Synchronizují se moje barvy a šablony?","s5.a":"Ano, přes iCloud. Ujistěte se, že jste na všech zařízeních přihlášeni k iCloudu stejným Apple účtem.","footer.rights":"Všechna práva vyhrazena.","lang.label":"Jazyk","mock.Meeting":"Schůzka","mock.Lunch":"Oběd","mock.Gym":"Posilovna","mock.Dentist":"Zubař","mock.Birthday":"Narozeniny","mock.Flight":"Let","mock.Holiday":"Dovolená","mock.Day":"Den","mock.Week":"Týden","mock.Month":"Měsíc","mock.Year":"Rok","mock.List":"Seznam","mock.Today":"Dnes","mock.Calendars":"Kalendáře","mock.Color":"Barva","mock.Birthdays":"Narozeniny","mock.Doctor":"Lékař"},"da":{"nav.features":"Funktioner","nav.devices":"Enheder","nav.faq":"FAQ","nav.support":"Support","nav.privacy":"Anonymitet","meta.description":"Weekdot er en hurtig og smuk kalender til iPhone, iPad, Apple Watch og Mac med dags-, uge-, måneds- og årsoversigt.","hero.title":"Din uge på ét blik.","hero.sub":"Weekdot er en hurtig og smuk kalender til iPhone, iPad, Apple Watch og Mac. Dags-, uge-, måneds- og årsoversigt med farver, emoji og skabeloner – oven på de kalendere, du allerede bruger.","hero.cta":"Kommer snart i App Store","hero.note":"Fungerer med iCloud, Google, Outlook, Exchange og alle kalendere i appen Kalender.","features.title":"Alt, hvad du planlægger, i én oversigt","f1.t":"Ugeoversigt med 7 dage","f1.d":"Se hele din uge på én gang. Vælg 1 til 7 dage, start ugen på en vilkårlig dag, og knib for at zoome i timerne.","f2.t":"Dag, måned og år","f2.d":"Zoom ud til en måned med begivenhedernes navne eller et år med dine travle dage, og tryk for at hoppe direkte ind.","f3.t":"Træk, kopier og indsæt","f3.d":"Flyt begivenheder ved at trække, ændr deres længde, kopier dem til en anden dag, eller dubler dem med ét tryk.","f4.t":"Farver og emoji","f4.d":"Giv begivenheder deres egen farve og emoji, eller lad regler gøre det automatisk ud fra titlen.","f5.t":"Skabeloner","f5.d":"Gem begivenheder, du ofte planlægger, og tilføj dem med ét tryk. Weekdot foreslår også detaljer fra tidligere begivenheder.","f6.t":"Alle dine kalendere","f6.d":"Vis, skjul og saml kalendere i sæt, opret nye, og abonner på helligdage eller et hvilket som helst .ics-link.","f7.t":"Synkroniseret med iCloud","f7.d":"Dine indstillinger, skabeloner, sæt, regler, farver og emoji er de samme på alle enheder.","f8.t":"Widgets og Apple Watch","f8.d":"Widgets til I dag, Næste og Uge samt en urapp med din dag og uge på ét blik.","f9.t":"På dit sprog","f9.d":"Weekdot taler mere end 30 sprog og følger sproget på din enhed.","f10.t":"Vejr","f10.d":"Se eventuelt vejrudsigten over dine dage.","devices.title":"På alle dine Apple-enheder","devices.sub":"Én app til iPhone, iPad, Mac og Apple Watch.","faq.title":"Spørgsmål","q1":"Erstatter Weekdot mine kalenderkonti?","a1":"Nej. Weekdot viser og redigerer kalenderne fra appen Kalender, så alt fortsat synkroniseres via iCloud, Google, Outlook eller Exchange.","q2":"Hvor opbevares mine data?","a2":"Dine begivenheder bliver på dine egne kalenderkonti. Weekdots egne indstillinger synkroniseres via din private iCloud. Weekdot har ingen servere, der opbevarer dine data.","q3":"Hvilke sprog understøttes?","a3":"Mere end 30, bl.a. engelsk, hollandsk, tysk, fransk, spansk, italiensk, portugisisk, kinesisk, japansk, koreansk og arabisk.","q4":"Kan jeg tilføje helligdage?","a4":"Ja. Abonner på helligdage for mange lande med ét tryk, eller indsæt et hvilket som helst .ics-link.","privacy.title":"Anonymitet","privacy.p1":"Weekdot er bygget til, at dine data forbliver dine.","privacy.p2":"Kalenderdata: Weekdot læser og skriver kun begivenheder på kalenderkontiene på din enhed (appen Kalender). Dine begivenheder sendes aldrig til os.","privacy.p3":"iCloud: Weekdots egne indstillinger, skabeloner, kalendersæt, regler, farver og emoji opbevares i din private iCloud, så de synkroniseres mellem dine enheder. Vi har ikke adgang til dem.","privacy.p4":"Vejr (valgfrit): Når du slår vejr til, sendes din omtrentlige placering til Open-Meteo for at hente en vejrudsigt. Weekdot gemmer den ikke.","privacy.p5":"Ingen konti, ingen sporing, ingen reklamer og ingen analyse.","privacy.p6":"Spørgsmål? Kontakt os via supportsiden.","privacy.updated":"Senest opdateret: 24. oktober 2026","support.title":"Hjælp og support","s1.q":"Weekdot viser ingen begivenheder","s1.a":"Giv fuld adgang til kalendere: Indstillinger › Anonymitet og sikkerhed › Kalendere › Weekdot › Fuld adgang.","s2.q":"Hvordan tilføjer jeg en Google- eller Outlook-kalender?","s2.a":"Tilføj kontoen i Indstillinger › Apps › Kalender › Kalenderkonti (Mac: appen Kalender › Tilføj konto). Weekdot viser den automatisk.","s3.q":"Hvordan skifter jeg sprog?","s3.a":"Weekdot følger sproget på din enhed. På iPhone og iPad kan du vælge et sprog kun til Weekdot i Indstillinger › Apps › Weekdot › Sprog.","s4.q":"Hvorfor viser appsymbolet ikke dagens dato?","s4.a":"Kun Apples egen Kalender-app kan selv ændre sit symbol. Føj Weekdot-widgetten ‘I dag’ til din hjemmeskærm for at se datoen live. På Mac viser symbolet i Dock dagens dato, mens Weekdot er åben.","s5.q":"Synkroniseres mine farver og skabeloner?","s5.a":"Ja, via iCloud. Sørg for, at du er logget ind på iCloud med den samme Apple-konto på alle dine enheder.","footer.rights":"Alle rettigheder forbeholdes.","lang.label":"Sprog","mock.Meeting":"Møde","mock.Lunch":"Frokost","mock.Gym":"Fitness","mock.Dentist":"Tandlæge","mock.Birthday":"Fødselsdag","mock.Flight":"Fly","mock.Holiday":"Ferie","mock.Day":"Dag","mock.Week":"Uge","mock.Month":"Måned","mock.Year":"År","mock.List":"Liste","mock.Today":"I dag","mock.Calendars":"Kalendere","mock.Color":"Farve","mock.Birthdays":"Fødselsdage","mock.Doctor":"Læge"},"de":{"nav.features":"Funktionen","nav.devices":"Geräte","nav.faq":"FAQ","nav.support":"Support","nav.privacy":"Datenschutz","meta.description":"Weekdot ist ein schneller, schöner Kalender für iPhone, iPad, Apple Watch und Mac mit Tages-, Wochen-, Monats- und Jahresansicht.","hero.title":"Deine Woche auf einen Blick.","hero.sub":"Weekdot ist ein schneller, schöner Kalender für iPhone, iPad, Apple Watch und Mac. Tages-, Wochen-, Monats- und Jahresansicht, mit Farben, Emoji und Vorlagen – auf Basis der Kalender, die du bereits verwendest.","hero.cta":"Bald im App Store","hero.note":"Funktioniert mit iCloud, Google, Outlook, Exchange und jedem Kalender in der App „Kalender“.","features.title":"Alles, was du planst, in einer Ansicht","f1.t":"Wochenansicht mit 7 Tagen","f1.d":"Sieh deine ganze Woche auf einmal. Wähle 1 bis 7 Tage, beginne die Woche an einem beliebigen Tag und zoome die Stunden mit zwei Fingern.","f2.t":"Tag, Monat und Jahr","f2.d":"Zoome heraus auf einen Monat mit Ereignisnamen oder ein Jahr mit deinen vollen Tagen und tippe, um direkt dorthin zu springen.","f3.t":"Ziehen, Kopieren & Einsetzen","f3.d":"Verschiebe Ereignisse durch Ziehen, ändere ihre Dauer, kopiere sie auf einen anderen Tag oder dupliziere sie mit einem Tippen.","f4.t":"Farben & Emoji","f4.d":"Gib Ereignissen eine eigene Farbe und ein Emoji oder lass Regeln das automatisch anhand des Titels erledigen.","f5.t":"Vorlagen","f5.d":"Sichere Ereignisse, die du oft planst, und füge sie mit einem Tippen hinzu. Weekdot schlägt auch Details aus früheren Ereignissen vor.","f6.t":"Alle deine Kalender","f6.d":"Kalender ein- und ausblenden und in Sets gruppieren, neue erstellen, Feiertage oder beliebige .ics-Links abonnieren.","f7.t":"Mit iCloud synchronisiert","f7.d":"Deine Einstellungen, Vorlagen, Sets, Regeln, Farben und Emoji sind auf jedem Gerät gleich.","f8.t":"Widgets & Apple Watch","f8.d":"Widgets für Heute, Als Nächstes und Woche sowie eine Watch-App für deinen Tag und deine Woche auf einen Blick.","f9.t":"In deiner Sprache","f9.d":"Weekdot spricht mehr als 30 Sprachen und verwendet die Sprache deines Geräts.","f10.t":"Wetter","f10.d":"Sieh auf Wunsch die Vorhersage über deinen Tagen.","devices.title":"Auf all deinen Apple-Geräten","devices.sub":"Eine App für iPhone, iPad, Mac und Apple Watch.","faq.title":"Fragen","q1":"Ersetzt Weekdot meine Kalender-Accounts?","a1":"Nein. Weekdot zeigt und bearbeitet die Kalender aus der App „Kalender“, sodass alles weiterhin über iCloud, Google, Outlook oder Exchange synchronisiert wird.","q2":"Wo werden meine Daten gespeichert?","a2":"Deine Ereignisse bleiben in deinen eigenen Kalender-Accounts. Die eigenen Einstellungen von Weekdot werden über deine private iCloud synchronisiert. Weekdot hat keine Server, die deine Daten speichern.","q3":"Welche Sprachen werden unterstützt?","a3":"Mehr als 30, darunter Englisch, Niederländisch, Deutsch, Französisch, Spanisch, Italienisch, Portugiesisch, Chinesisch, Japanisch, Koreanisch und Arabisch.","q4":"Kann ich Feiertage hinzufügen?","a4":"Ja. Abonniere mit einem Tippen die gesetzlichen Feiertage vieler Länder oder füge einen beliebigen .ics-Link ein.","privacy.title":"Datenschutz","privacy.p1":"Weekdot ist so gebaut, dass deine Daten dir gehören.","privacy.p2":"Kalenderdaten: Weekdot liest und schreibt Ereignisse nur in den Kalender-Accounts auf deinem Gerät (der App „Kalender“). Deine Ereignisse werden niemals an uns gesendet.","privacy.p3":"iCloud: Die eigenen Einstellungen, Vorlagen, Kalendersets, Regeln, Farben und Emoji von Weekdot werden in deiner privaten iCloud gespeichert, damit sie zwischen deinen Geräten synchronisiert werden. Wir haben keinen Zugriff darauf.","privacy.p4":"Wetter (optional): Wenn du das Wetter aktivierst, wird dein ungefährer Standort an Open-Meteo gesendet, um eine Vorhersage abzurufen. Weekdot speichert ihn nicht.","privacy.p5":"Keine Accounts, kein Tracking, keine Werbung und keine Analysen.","privacy.p6":"Fragen? Kontaktiere uns über die Supportseite.","privacy.updated":"Zuletzt aktualisiert: 24. Oktober 2026","support.title":"Hilfe & Support","s1.q":"Weekdot zeigt keine Ereignisse","s1.a":"Erlaube vollen Kalenderzugriff: Einstellungen › Datenschutz & Sicherheit › Kalender › Weekdot › Voller Zugriff.","s2.q":"Wie füge ich einen Google- oder Outlook-Kalender hinzu?","s2.a":"Füge den Account unter Einstellungen › Apps › Kalender › Kalenderaccounts hinzu (Mac: App „Kalender“ › Account hinzufügen). Weekdot zeigt ihn automatisch an.","s3.q":"Wie ändere ich die Sprache?","s3.a":"Weekdot verwendet die Sprache deines Geräts. Auf dem iPhone und iPad kannst du unter Einstellungen › Apps › Weekdot › Sprache eine Sprache nur für Weekdot wählen.","s4.q":"Warum zeigt das App-Symbol nicht das heutige Datum?","s4.a":"Nur Apples eigene App „Kalender“ kann ihr Symbol selbst ändern. Füge das Weekdot-Widget „Heute“ zu deinem Home-Bildschirm hinzu, um ein aktuelles Datum zu sehen. Auf dem Mac zeigt das Dock-Symbol das heutige Datum, solange Weekdot geöffnet ist.","s5.q":"Werden meine Farben und Vorlagen synchronisiert?","s5.a":"Ja, über iCloud. Stelle sicher, dass du auf all deinen Geräten mit demselben Apple Account bei iCloud angemeldet bist.","footer.rights":"Alle Rechte vorbehalten.","lang.label":"Sprache","mock.Meeting":"Besprechung","mock.Lunch":"Mittagessen","mock.Gym":"Fitnessstudio","mock.Dentist":"Zahnarzt","mock.Birthday":"Geburtstag","mock.Flight":"Flug","mock.Holiday":"Urlaub","mock.Day":"Tag","mock.Week":"Woche","mock.Month":"Monat","mock.Year":"Jahr","mock.List":"Liste","mock.Today":"Heute","mock.Calendars":"Kalender","mock.Color":"Farbe","mock.Birthdays":"Geburtstage","mock.Doctor":"Arzt"},"el":{"nav.features":"Δυνατότητες","nav.devices":"Συσκευές","nav.faq":"Συχνές ερωτήσεις","nav.support":"Υποστήριξη","nav.privacy":"Απόρρητο","meta.description":"Το Weekdot είναι ένα γρήγορο, όμορφο ημερολόγιο για iPhone, iPad, Apple Watch και Mac με προβολές ημέρας, εβδομάδας, μήνα και έτους.","hero.title":"Η εβδομάδα σας με μια ματιά.","hero.sub":"Το Weekdot είναι ένα γρήγορο, όμορφο ημερολόγιο για iPhone, iPad, Apple Watch και Mac. Προβολές ημέρας, εβδομάδας, μήνα και έτους, με χρώματα, emoji και πρότυπα – πάνω στα ημερολόγια που ήδη χρησιμοποιείτε.","hero.cta":"Σύντομα στο App Store","hero.note":"Λειτουργεί με iCloud, Google, Outlook, Exchange και κάθε ημερολόγιο στην εφαρμογή Ημερολόγιο.","features.title":"Όλα όσα σχεδιάζετε, σε μία προβολή","f1.t":"Προβολή εβδομάδας με 7 ημέρες","f1.d":"Δείτε όλη την εβδομάδα σας μονομιάς. Επιλέξτε 1 έως 7 ημέρες, ξεκινήστε την εβδομάδα όποια μέρα θέλετε και τσιμπήστε για μεγέθυνση των ωρών.","f2.t":"Ημέρα, μήνας και έτος","f2.d":"Σμικρύνετε σε έναν μήνα με τα ονόματα των συμβάντων ή σε ένα έτος με τις φορτωμένες μέρες σας και αγγίξτε για να μεταβείτε αμέσως.","f3.t":"Μεταφορά, αντιγραφή και επικόλληση","f3.d":"Μετακινήστε συμβάντα σύροντάς τα, αλλάξτε τη διάρκειά τους, αντιγράψτε τα σε άλλη ημέρα ή δημιουργήστε διπλότυπο με ένα άγγιγμα.","f4.t":"Χρώματα και emoji","f4.d":"Δώστε στα συμβάντα δικό τους χρώμα και emoji ή αφήστε τους κανόνες να το κάνουν αυτόματα βάσει του τίτλου.","f5.t":"Πρότυπα","f5.d":"Αποθηκεύστε συμβάντα που προγραμματίζετε συχνά και προσθέστε τα με ένα άγγιγμα. Το Weekdot προτείνει επίσης λεπτομέρειες από παλαιότερα συμβάντα.","f6.t":"Όλα τα ημερολόγιά σας","f6.d":"Εμφανίστε, αποκρύψτε και ομαδοποιήστε ημερολόγια σε σύνολα, δημιουργήστε νέα, εγγραφείτε σε αργίες ή σε οποιονδήποτε σύνδεσμο .ics.","f7.t":"Συγχρονισμένο με iCloud","f7.d":"Οι ρυθμίσεις, τα πρότυπα, τα σύνολα, οι κανόνες, τα χρώματα και τα emoji σας είναι ίδια σε κάθε συσκευή.","f8.t":"Widget και Apple Watch","f8.d":"Widget Σήμερα, Επόμενα και Εβδομάδα, καθώς και εφαρμογή ρολογιού για την ημέρα και την εβδομάδα σας με μια ματιά.","f9.t":"Στη γλώσσα σας","f9.d":"Το Weekdot μιλά περισσότερες από 30 γλώσσες και ακολουθεί τη γλώσσα της συσκευής σας.","f10.t":"Καιρός","f10.d":"Προαιρετικά, δείτε την πρόγνωση πάνω από τις ημέρες σας.","devices.title":"Σε όλες τις συσκευές Apple σας","devices.sub":"Μία εφαρμογή για iPhone, iPad, Mac και Apple Watch.","faq.title":"Ερωτήσεις","q1":"Αντικαθιστά το Weekdot τους λογαριασμούς ημερολογίου μου;","a1":"Όχι. Το Weekdot εμφανίζει και επεξεργάζεται τα ημερολόγια της εφαρμογής Ημερολόγιο, οπότε όλα συνεχίζουν να συγχρονίζονται μέσω iCloud, Google, Outlook ή Exchange.","q2":"Πού αποθηκεύονται τα δεδομένα μου;","a2":"Τα συμβάντα σας παραμένουν στους δικούς σας λογαριασμούς ημερολογίου. Οι ρυθμίσεις του Weekdot συγχρονίζονται μέσω του ιδιωτικού σας iCloud. Το Weekdot δεν έχει διακομιστές που αποθηκεύουν τα δεδομένα σας.","q3":"Ποιες γλώσσες υποστηρίζονται;","a3":"Περισσότερες από 30, όπως Αγγλικά, Ολλανδικά, Γερμανικά, Γαλλικά, Ισπανικά, Ιταλικά, Πορτογαλικά, Κινεζικά, Ιαπωνικά, Κορεατικά και Αραβικά.","q4":"Μπορώ να προσθέσω αργίες;","a4":"Ναι. Εγγραφείτε στις επίσημες αργίες πολλών χωρών με ένα άγγιγμα ή επικολλήστε οποιονδήποτε σύνδεσμο .ics.","privacy.title":"Απόρρητο","privacy.p1":"Το Weekdot έχει σχεδιαστεί ώστε τα δεδομένα σας να παραμένουν δικά σας.","privacy.p2":"Δεδομένα ημερολογίου: το Weekdot διαβάζει και γράφει συμβάντα μόνο στους λογαριασμούς ημερολογίου της συσκευής σας (εφαρμογή Ημερολόγιο). Τα συμβάντα σας δεν αποστέλλονται ποτέ σε εμάς.","privacy.p3":"iCloud: οι ρυθμίσεις, τα πρότυπα, τα σύνολα ημερολογίων, οι κανόνες, τα χρώματα και τα emoji του Weekdot αποθηκεύονται στο ιδιωτικό σας iCloud, ώστε να συγχρονίζονται μεταξύ των συσκευών σας. Εμείς δεν έχουμε πρόσβαση σε αυτά.","privacy.p4":"Καιρός (προαιρετικό): όταν ενεργοποιείτε τον καιρό, η κατά προσέγγιση τοποθεσία σας αποστέλλεται στο Open-Meteo για τη λήψη πρόγνωσης. Το Weekdot δεν την αποθηκεύει.","privacy.p5":"Χωρίς λογαριασμούς, χωρίς παρακολούθηση, χωρίς διαφημίσεις και χωρίς αναλυτικά στοιχεία.","privacy.p6":"Ερωτήσεις; Επικοινωνήστε μαζί μας μέσω της σελίδας υποστήριξης.","privacy.updated":"Τελευταία ενημέρωση: 24 Οκτωβρίου 2026","support.title":"Βοήθεια και υποστήριξη","s1.q":"Το Weekdot δεν εμφανίζει συμβάντα","s1.a":"Επιτρέψτε πλήρη πρόσβαση στο ημερολόγιο: Ρυθμίσεις › Απόρρητο και ασφάλεια › Ημερολόγια › Weekdot › Πλήρης πρόσβαση.","s2.q":"Πώς προσθέτω ημερολόγιο Google ή Outlook;","s2.a":"Προσθέστε τον λογαριασμό στις Ρυθμίσεις › Εφαρμογές › Ημερολόγιο › Λογαριασμοί ημερολογίου (Mac: εφαρμογή Ημερολόγιο › Προσθήκη λογαριασμού). Το Weekdot τον εμφανίζει αυτόματα.","s3.q":"Πώς αλλάζω τη γλώσσα;","s3.a":"Το Weekdot ακολουθεί τη γλώσσα της συσκευής σας. Σε iPhone και iPad μπορείτε να επιλέξετε γλώσσα μόνο για το Weekdot στις Ρυθμίσεις › Εφαρμογές › Weekdot › Γλώσσα.","s4.q":"Γιατί το εικονίδιο της εφαρμογής δεν δείχνει τη σημερινή ημερομηνία;","s4.a":"Μόνο η εφαρμογή Ημερολόγιο της Apple μπορεί να αλλάζει μόνη της το εικονίδιό της. Προσθέστε το widget «Σήμερα» του Weekdot στην οθόνη Αφετηρίας για ζωντανή ημερομηνία. Στο Mac, το εικονίδιο στο Dock δείχνει τη σημερινή ημερομηνία όσο το Weekdot είναι ανοιχτό.","s5.q":"Συγχρονίζονται τα χρώματα και τα πρότυπά μου;","s5.a":"Ναι, μέσω iCloud. Βεβαιωθείτε ότι έχετε συνδεθεί στο iCloud με τον ίδιο λογαριασμό Apple σε όλες τις συσκευές σας.","footer.rights":"Με την επιφύλαξη παντός δικαιώματος.","lang.label":"Γλώσσα","mock.Meeting":"Σύσκεψη","mock.Lunch":"Μεσημεριανό","mock.Gym":"Γυμναστήριο","mock.Dentist":"Οδοντίατρος","mock.Birthday":"Γενέθλια","mock.Flight":"Πτήση","mock.Holiday":"Διακοπές","mock.Day":"Ημέρα","mock.Week":"Εβδομάδα","mock.Month":"Μήνας","mock.Year":"Έτος","mock.List":"Λίστα","mock.Today":"Σήμερα","mock.Calendars":"Ημερολόγια","mock.Color":"Χρώμα","mock.Birthdays":"Γενέθλια","mock.Doctor":"Γιατρός"},"es":{"nav.features":"Funciones","nav.devices":"Dispositivos","nav.faq":"Preguntas frecuentes","nav.support":"Soporte","nav.privacy":"Privacidad","meta.description":"Weekdot es un calendario rápido y bonito para iPhone, iPad, Apple Watch y Mac con vistas de día, semana, mes y año.","hero.title":"Tu semana de un vistazo.","hero.sub":"Weekdot es un calendario rápido y bonito para iPhone, iPad, Apple Watch y Mac. Vistas de día, semana, mes y año, con colores, emoji y plantillas, sobre los calendarios que ya usas.","hero.cta":"Próximamente en el App Store","hero.note":"Funciona con iCloud, Google, Outlook, Exchange y cualquier calendario de la app Calendario.","features.title":"Todo lo que planificas, en una sola vista","f1.t":"Vista Semana con 7 días","f1.d":"Ve toda tu semana de una vez. Elige de 1 a 7 días, empieza la semana el día que quieras y pellizca para ampliar las horas.","f2.t":"Día, mes y año","f2.d":"Aleja la vista a un mes con los nombres de los eventos o a un año con tus días ocupados, y toca para ir directamente.","f3.t":"Arrastrar, copiar y pegar","f3.d":"Mueve eventos arrastrándolos, cambia su duración, cópialos a otro día o duplícalos con un toque.","f4.t":"Colores y emoji","f4.d":"Dale a cada evento su propio color y emoji, o deja que las reglas lo hagan automáticamente según el título.","f5.t":"Plantillas","f5.d":"Guarda los eventos que planificas a menudo y añádelos con un toque. Weekdot también sugiere detalles a partir de eventos anteriores.","f6.t":"Todos tus calendarios","f6.d":"Muestra, oculta y agrupa calendarios, crea otros nuevos y suscríbete a festivos o a cualquier enlace .ics.","f7.t":"Sincronizado con iCloud","f7.d":"Tus ajustes, plantillas, grupos, reglas, colores y emoji son iguales en todos tus dispositivos.","f8.t":"Widgets y Apple Watch","f8.d":"Widgets de Hoy, A continuación y Semana, además de una app para el reloj con tu día y tu semana de un vistazo.","f9.t":"En tu idioma","f9.d":"Weekdot habla más de 30 idiomas y usa el idioma de tu dispositivo.","f10.t":"Tiempo","f10.d":"Si quieres, consulta la previsión sobre tus días.","devices.title":"En todos tus dispositivos Apple","devices.sub":"Una sola app para iPhone, iPad, Mac y Apple Watch.","faq.title":"Preguntas","q1":"¿Weekdot sustituye a mis cuentas de calendario?","a1":"No. Weekdot muestra y edita los calendarios de la app Calendario, así que todo se sigue sincronizando mediante iCloud, Google, Outlook o Exchange.","q2":"¿Dónde se guardan mis datos?","a2":"Tus eventos permanecen en tus propias cuentas de calendario. Los ajustes propios de Weekdot se sincronizan mediante tu iCloud privado. Weekdot no tiene servidores que almacenen tus datos.","q3":"¿Qué idiomas son compatibles?","a3":"Más de 30, entre ellos inglés, neerlandés, alemán, francés, español, italiano, portugués, chino, japonés, coreano y árabe.","q4":"¿Puedo añadir festivos?","a4":"Sí. Suscríbete a los festivos de muchos países con un toque, o pega cualquier enlace .ics.","privacy.title":"Privacidad","privacy.p1":"Weekdot está pensado para que tus datos sigan siendo tuyos.","privacy.p2":"Datos del calendario: Weekdot lee y escribe eventos solo en las cuentas de calendario de tu dispositivo (la app Calendario). Tus eventos nunca se nos envían.","privacy.p3":"iCloud: los ajustes, plantillas, grupos de calendarios, reglas, colores y emoji propios de Weekdot se guardan en tu iCloud privado para sincronizarse entre tus dispositivos. No tenemos acceso a ellos.","privacy.p4":"Tiempo (opcional): si activas el tiempo, tu ubicación aproximada se envía a Open-Meteo para obtener una previsión. Weekdot no la guarda.","privacy.p5":"Sin cuentas, sin rastreo, sin anuncios y sin analíticas.","privacy.p6":"¿Tienes preguntas? Ponte en contacto a través de la página de soporte.","privacy.updated":"Última actualización: 24 de octubre de 2026","support.title":"Ayuda y soporte","s1.q":"Weekdot no muestra ningún evento","s1.a":"Permite el acceso total a los calendarios: Ajustes › Privacidad y seguridad › Calendarios › Weekdot › Acceso total.","s2.q":"¿Cómo añado un calendario de Google u Outlook?","s2.a":"Añade la cuenta en Ajustes › Apps › Calendario › Cuentas de calendario (Mac: app Calendario › Añadir cuenta). Weekdot la muestra automáticamente.","s3.q":"¿Cómo cambio el idioma?","s3.a":"Weekdot usa el idioma de tu dispositivo. En el iPhone y el iPad puedes elegir un idioma solo para Weekdot en Ajustes › Apps › Weekdot › Idioma.","s4.q":"¿Por qué el icono de la app no muestra la fecha de hoy?","s4.a":"Solo la app Calendario de Apple puede cambiar su propio icono. Añade el widget “Hoy” de Weekdot a tu pantalla de inicio para ver la fecha actual. En el Mac, el icono del Dock muestra la fecha de hoy mientras Weekdot está abierto.","s5.q":"¿Se sincronizan mis colores y plantillas?","s5.a":"Sí, mediante iCloud. Asegúrate de haber iniciado sesión en iCloud con la misma cuenta de Apple en todos tus dispositivos.","footer.rights":"Todos los derechos reservados.","lang.label":"Idioma","mock.Meeting":"Reunión","mock.Lunch":"Comida","mock.Gym":"Gimnasio","mock.Dentist":"Dentista","mock.Birthday":"Cumpleaños","mock.Flight":"Vuelo","mock.Holiday":"Vacaciones","mock.Day":"Día","mock.Week":"Semana","mock.Month":"Mes","mock.Year":"Año","mock.List":"Lista","mock.Today":"Hoy","mock.Calendars":"Calendarios","mock.Color":"Color","mock.Birthdays":"Cumpleaños","mock.Doctor":"Médico"},"fi":{"nav.features":"Ominaisuudet","nav.devices":"Laitteet","nav.faq":"UKK","nav.support":"Tuki","nav.privacy":"Tietosuoja","meta.description":"Weekdot on nopea ja kaunis kalenteri iPhonelle, iPadille, Apple Watchille ja Macille päivä-, viikko-, kuukausi- ja vuosinäkymillä.","hero.title":"Viikkosi yhdellä silmäyksellä.","hero.sub":"Weekdot on nopea ja kaunis kalenteri iPhonelle, iPadille, Apple Watchille ja Macille. Päivä-, viikko-, kuukausi- ja vuosinäkymät väreillä, emojeilla ja pohjilla – jo käyttämiesi kalentereiden päällä.","hero.cta":"Tulossa pian App Storeen","hero.note":"Toimii iCloudin, Googlen, Outlookin, Exchangen ja kaikkien Kalenteri-apin kalentereiden kanssa.","features.title":"Kaikki suunnitelmasi yhdessä näkymässä","f1.t":"Viikkonäkymä 7 päivällä","f1.d":"Näe koko viikkosi kerralla. Valitse 1–7 päivää, aloita viikko mistä päivästä tahansa ja zoomaa tunteja nipistämällä.","f2.t":"Päivä, kuukausi ja vuosi","f2.d":"Loitonna kuukauteen tapahtumien nimillä tai vuoteen kiireisillä päivilläsi, ja hyppää suoraan sisään napauttamalla.","f3.t":"Vedä, kopioi ja sijoita","f3.d":"Siirrä tapahtumia vetämällä, muuta niiden kestoa, kopioi ne toiseen päivään tai monista ne yhdellä napautuksella.","f4.t":"Värit ja emojit","f4.d":"Anna tapahtumille oma väri ja emoji tai anna sääntöjen tehdä se automaattisesti nimen perusteella.","f5.t":"Pohjat","f5.d":"Tallenna usein suunnittelemasi tapahtumat ja lisää ne yhdellä napautuksella. Weekdot ehdottaa myös tietoja aiemmista tapahtumista.","f6.t":"Kaikki kalenterisi","f6.d":"Näytä, kätke ja ryhmitä kalentereita joukoiksi, luo uusia, tilaa pyhäpäiviä tai mikä tahansa .ics-linkki.","f7.t":"Synkronoitu iCloudin kanssa","f7.d":"Asetuksesi, pohjasi, joukkosi, sääntösi, värisi ja emojisi ovat samat kaikilla laitteilla.","f8.t":"Widgetit ja Apple Watch","f8.d":"Tänään-, Seuraavaksi- ja Viikko-widgetit sekä kelloappi, joka näyttää päiväsi ja viikkosi yhdellä silmäyksellä.","f9.t":"Omalla kielelläsi","f9.d":"Weekdot puhuu yli 30 kieltä ja noudattaa laitteesi kieltä.","f10.t":"Sää","f10.d":"Näe halutessasi sääennuste päiviesi yläpuolella.","devices.title":"Kaikilla Apple-laitteillasi","devices.sub":"Yksi appi iPhonelle, iPadille, Macille ja Apple Watchille.","faq.title":"Kysymykset","q1":"Korvaako Weekdot kalenteritilini?","a1":"Ei. Weekdot näyttää ja muokkaa Kalenteri-apin kalentereita, joten kaikki synkronoituu edelleen iCloudin, Googlen, Outlookin tai Exchangen kautta.","q2":"Missä tietoni säilytetään?","a2":"Tapahtumasi pysyvät omilla kalenteritileilläsi. Weekdotin omat asetukset synkronoidaan yksityisen iCloudisi kautta. Weekdotillä ei ole palvelimia, jotka tallentaisivat tietojasi.","q3":"Mitä kieliä tuetaan?","a3":"Yli 30, muun muassa englanti, hollanti, saksa, ranska, espanja, italia, portugali, kiina, japani, korea ja arabia.","q4":"Voinko lisätä pyhäpäiviä?","a4":"Kyllä. Tilaa monien maiden yleiset vapaapäivät yhdellä napautuksella tai sijoita mikä tahansa .ics-linkki.","privacy.title":"Tietosuoja","privacy.p1":"Weekdot on tehty niin, että tietosi pysyvät sinun.","privacy.p2":"Kalenteritiedot: Weekdot lukee ja kirjoittaa tapahtumia vain laitteesi kalenteritileille (Kalenteri-appi). Tapahtumiasi ei koskaan lähetetä meille.","privacy.p3":"iCloud: Weekdotin omat asetukset, pohjat, kalenterijoukot, säännöt, värit ja emojit tallennetaan yksityiseen iCloudiisi, jotta ne synkronoituvat laitteidesi välillä. Meillä ei ole pääsyä niihin.","privacy.p4":"Sää (valinnainen): kun laitat sään päälle, likimääräinen sijaintisi lähetetään Open-Meteolle ennusteen hakemista varten. Weekdot ei tallenna sitä.","privacy.p5":"Ei tilejä, ei seurantaa, ei mainoksia eikä analytiikkaa.","privacy.p6":"Kysyttävää? Ota yhteyttä tukisivun kautta.","privacy.updated":"Päivitetty viimeksi: 24. lokakuuta 2026","support.title":"Ohje ja tuki","s1.q":"Weekdot ei näytä tapahtumia","s1.a":"Salli täysi pääsy kalentereihin: Asetukset › Tietosuoja ja suojaus › Kalenterit › Weekdot › Täysi pääsy.","s2.q":"Miten lisään Google- tai Outlook-kalenterin?","s2.a":"Lisää tili kohdassa Asetukset › Apit › Kalenteri › Kalenteritilit (Mac: Kalenteri-appi › Lisää tili). Weekdot näyttää sen automaattisesti.","s3.q":"Miten vaihdan kieltä?","s3.a":"Weekdot noudattaa laitteesi kieltä. iPhonella ja iPadilla voit valita kielen pelkästään Weekdotille kohdassa Asetukset › Apit › Weekdot › Kieli.","s4.q":"Miksi apin symboli ei näytä tämän päivän päivämäärää?","s4.a":"Vain Applen oma Kalenteri-appi voi muuttaa symboliaan itse. Lisää Weekdotin ’Tänään’-widget Koti-valikkoon, niin näet päivämäärän aina ajan tasalla. Macilla Dockin symboli näyttää tämän päivän päivämäärän, kun Weekdot on auki.","s5.q":"Synkronoituvatko värini ja pohjani?","s5.a":"Kyllä, iCloudin kautta. Varmista, että olet kirjautunut iCloudiin samalla Apple-tilillä kaikilla laitteillasi.","footer.rights":"Kaikki oikeudet pidätetään.","lang.label":"Kieli","mock.Meeting":"Kokous","mock.Lunch":"Lounas","mock.Gym":"Kuntosali","mock.Dentist":"Hammaslääkäri","mock.Birthday":"Syntymäpäivä","mock.Flight":"Lento","mock.Holiday":"Loma","mock.Day":"Päivä","mock.Week":"Viikko","mock.Month":"Kuukausi","mock.Year":"Vuosi","mock.List":"Luettelo","mock.Today":"Tänään","mock.Calendars":"Kalenterit","mock.Color":"Väri","mock.Birthdays":"Syntymäpäivät","mock.Doctor":"Lääkäri"},"fr":{"nav.features":"Fonctionnalités","nav.devices":"Appareils","nav.faq":"FAQ","nav.support":"Assistance","nav.privacy":"Confidentialité","meta.description":"Weekdot est un calendrier rapide et élégant pour iPhone, iPad, Apple Watch et Mac, avec des vues Jour, Semaine, Mois et Année.","hero.title":"Votre semaine en un coup d’œil.","hero.sub":"Weekdot est un calendrier rapide et élégant pour iPhone, iPad, Apple Watch et Mac. Vues Jour, Semaine, Mois et Année, avec couleurs, emoji et modèles — en plus des calendriers que vous utilisez déjà.","hero.cta":"Bientôt sur l’App Store","hero.note":"Fonctionne avec iCloud, Google, Outlook, Exchange et tous les calendriers de l’app Calendrier.","features.title":"Tout ce que vous prévoyez, dans une seule vue","f1.t":"Vue Semaine sur 7 jours","f1.d":"Voyez toute votre semaine d’un coup. Choisissez de 1 à 7 jours, commencez la semaine le jour de votre choix et pincez pour zoomer sur les heures.","f2.t":"Jour, mois et année","f2.d":"Dézoomez sur un mois avec le nom des événements ou sur une année avec vos jours chargés, et touchez pour y accéder directement.","f3.t":"Glisser, copier et coller","f3.d":"Déplacez les événements en les faisant glisser, modifiez leur durée, copiez-les sur un autre jour ou dupliquez-les d’un simple toucher.","f4.t":"Couleurs et emoji","f4.d":"Donnez aux événements leur propre couleur et emoji, ou laissez des règles s’en charger automatiquement selon le titre.","f5.t":"Modèles","f5.d":"Enregistrez les événements que vous planifiez souvent et ajoutez-les d’un simple toucher. Weekdot suggère aussi des détails à partir d’événements passés.","f6.t":"Tous vos calendriers","f6.d":"Affichez, masquez et regroupez vos calendriers en ensembles, créez-en de nouveaux, abonnez-vous aux jours fériés ou à n’importe quel lien .ics.","f7.t":"Synchronisé avec iCloud","f7.d":"Vos réglages, modèles, ensembles, règles, couleurs et emoji sont identiques sur tous vos appareils.","f8.t":"Widgets et Apple Watch","f8.d":"Widgets Aujourd’hui, À venir et Semaine, plus une app pour montre pour voir votre journée et votre semaine en un coup d’œil.","f9.t":"Dans votre langue","f9.d":"Weekdot parle plus de 30 langues et suit la langue de votre appareil.","f10.t":"Météo","f10.d":"Affichez si vous le souhaitez les prévisions au-dessus de vos journées.","devices.title":"Sur tous vos appareils Apple","devices.sub":"Une seule app pour iPhone, iPad, Mac et Apple Watch.","faq.title":"Questions","q1":"Weekdot remplace-t-il mes comptes de calendrier ?","a1":"Non. Weekdot affiche et modifie les calendriers de l’app Calendrier : tout continue donc de se synchroniser via iCloud, Google, Outlook ou Exchange.","q2":"Où mes données sont-elles stockées ?","a2":"Vos événements restent dans vos propres comptes de calendrier. Les réglages propres à Weekdot sont synchronisés via votre iCloud privé. Weekdot n’a aucun serveur qui stocke vos données.","q3":"Quelles langues sont prises en charge ?","a3":"Plus de 30, dont l’anglais, le néerlandais, l’allemand, le français, l’espagnol, l’italien, le portugais, le chinois, le japonais, le coréen et l’arabe.","q4":"Puis-je ajouter des jours fériés ?","a4":"Oui. Abonnez-vous aux jours fériés de nombreux pays d’un simple toucher, ou collez n’importe quel lien .ics.","privacy.title":"Confidentialité","privacy.p1":"Weekdot est conçu pour que vos données restent les vôtres.","privacy.p2":"Données de calendrier : Weekdot lit et écrit les événements uniquement dans les comptes de calendrier de votre appareil (l’app Calendrier). Vos événements ne nous sont jamais envoyés.","privacy.p3":"iCloud : les réglages, modèles, ensembles de calendriers, règles, couleurs et emoji propres à Weekdot sont stockés dans votre iCloud privé afin d’être synchronisés entre vos appareils. Nous n’y avons pas accès.","privacy.p4":"Météo (facultatif) : lorsque vous activez la météo, votre position approximative est envoyée à Open-Meteo pour obtenir des prévisions. Weekdot ne la conserve pas.","privacy.p5":"Pas de compte, pas de suivi, pas de publicité et pas d’analyse.","privacy.p6":"Des questions ? Contactez-nous via la page d’assistance.","privacy.updated":"Dernière mise à jour : 24 octobre 2026","support.title":"Aide et assistance","s1.q":"Weekdot n’affiche aucun événement","s1.a":"Autorisez l’accès complet aux calendriers : Réglages › Confidentialité et sécurité › Calendriers › Weekdot › Accès complet.","s2.q":"Comment ajouter un calendrier Google ou Outlook ?","s2.a":"Ajoutez le compte dans Réglages › Apps › Calendrier › Comptes de calendrier (Mac : app Calendrier › Ajouter un compte). Weekdot l’affiche automatiquement.","s3.q":"Comment changer la langue ?","s3.a":"Weekdot suit la langue de votre appareil. Sur iPhone et iPad, vous pouvez choisir une langue pour Weekdot uniquement dans Réglages › Apps › Weekdot › Langue.","s4.q":"Pourquoi l’icône de l’app n’affiche-t-elle pas la date du jour ?","s4.a":"Seule l’app Calendrier d’Apple peut modifier elle-même son icône. Ajoutez le widget Weekdot « Aujourd’hui » à votre écran d’accueil pour une date toujours à jour. Sur Mac, l’icône du Dock affiche la date du jour tant que Weekdot est ouvert.","s5.q":"Mes couleurs et modèles sont-ils synchronisés ?","s5.a":"Oui, via iCloud. Assurez-vous d’être connecté à iCloud avec le même compte Apple sur tous vos appareils.","footer.rights":"Tous droits réservés.","lang.label":"Langue","mock.Meeting":"Réunion","mock.Lunch":"Déjeuner","mock.Gym":"Sport","mock.Dentist":"Dentiste","mock.Birthday":"Anniversaire","mock.Flight":"Vol","mock.Holiday":"Vacances","mock.Day":"Jour","mock.Week":"Semaine","mock.Month":"Mois","mock.Year":"Année","mock.List":"Liste","mock.Today":"Aujourd’hui","mock.Calendars":"Calendriers","mock.Color":"Couleur","mock.Birthdays":"Anniversaires","mock.Doctor":"Médecin"},"he":{"nav.features":"תכונות","nav.devices":"מכשירים","nav.faq":"שאלות נפוצות","nav.support":"תמיכה","nav.privacy":"פרטיות","meta.description":"Weekdot הוא לוח שנה מהיר ויפה ל‑iPhone,‏ iPad,‏ Apple Watch ו‑Mac עם תצוגות יום, שבוע, חודש ושנה.","hero.title":"השבוע שלך במבט אחד.","hero.sub":"Weekdot הוא לוח שנה מהיר ויפה ל‑iPhone,‏ iPad,‏ Apple Watch ו‑Mac. תצוגות יום, שבוע, חודש ושנה, עם צבעים, אמוג׳י ותבניות – על גבי לוחות השנה שכבר משמשים אותך.","hero.cta":"בקרוב ב‑App Store","hero.note":"עובד עם iCloud,‏ Google,‏ Outlook,‏ Exchange וכל לוח שנה באפליקציה ״לוח שנה״.","features.title":"כל מה שתכננת, בתצוגה אחת","f1.t":"תצוגת שבוע עם 7 ימים","f1.d":"רואים את כל השבוע בבת אחת. בוחרים בין 1 ל‑7 ימים, מתחילים את השבוע בכל יום וצובטים כדי להגדיל את השעות.","f2.t":"יום, חודש ושנה","f2.d":"מתרחקים לחודש עם שמות האירועים או לשנה עם הימים העמוסים, ומקישים כדי לקפוץ פנימה.","f3.t":"גרירה, העתקה והדבקה","f3.d":"מזיזים אירועים בגרירה, משנים את משכם, מעתיקים אותם ליום אחר או משכפלים בהקשה אחת.","f4.t":"צבעים ואמוג׳י","f4.d":"נותנים לאירועים צבע ואמוג׳י משלהם, או נותנים לכללים לעשות זאת אוטומטית לפי הכותרת.","f5.t":"תבניות","f5.d":"שומרים אירועים שמתכננים לעיתים קרובות ומוסיפים אותם בהקשה אחת. Weekdot גם מציע פרטים מאירועים קודמים.","f6.t":"כל לוחות השנה שלך","f6.d":"מציגים, מסתירים ומקבצים לוחות שנה לקבוצות, יוצרים חדשים ונרשמים לחגים או לכל קישור .ics.","f7.t":"מסונכרן עם iCloud","f7.d":"ההגדרות, התבניות, הקבוצות, הכללים, הצבעים והאמוג׳י שלך זהים בכל מכשיר.","f8.t":"וידג׳טים ו‑Apple Watch","f8.d":"וידג׳טים של היום, הבא בתור ושבוע, וגם אפליקציה לשעון ליום ולשבוע שלך במבט אחד.","f9.t":"בשפה שלך","f9.d":"Weekdot מדבר יותר מ‑30 שפות ומשתמש בשפת המכשיר שלך.","f10.t":"מזג אוויר","f10.d":"אפשר לראות את התחזית מעל הימים שלך.","devices.title":"בכל מכשירי Apple שלך","devices.sub":"אפליקציה אחת ל‑iPhone,‏ iPad,‏ Mac ו‑Apple Watch.","faq.title":"שאלות","q1":"האם Weekdot מחליף את חשבונות לוח השנה שלי?","a1":"לא. Weekdot מציג ועורך את לוחות השנה מהאפליקציה ״לוח שנה״, כך שהכול ממשיך להסתנכרן דרך iCloud,‏ Google,‏ Outlook או Exchange.","q2":"היכן הנתונים שלי מאוחסנים?","a2":"האירועים שלך נשארים בחשבונות לוח השנה שלך. ההגדרות של Weekdot מסונכרנות דרך ה‑iCloud הפרטי שלך. ל‑Weekdot אין שרתים שמאחסנים את הנתונים שלך.","q3":"באילו שפות יש תמיכה?","a3":"יותר מ‑30, כולל אנגלית, הולנדית, גרמנית, צרפתית, ספרדית, איטלקית, פורטוגזית, סינית, יפנית, קוריאנית וערבית.","q4":"האם אפשר להוסיף חגים?","a4":"כן. אפשר להירשם לחגים רשמיים של מדינות רבות בהקשה אחת, או להדביק כל קישור .ics.","privacy.title":"פרטיות","privacy.p1":"Weekdot נבנה כדי שהנתונים שלך יישארו שלך.","privacy.p2":"נתוני לוח שנה: Weekdot קורא וכותב אירועים רק בחשבונות לוח השנה שבמכשיר שלך (האפליקציה ״לוח שנה״). האירועים שלך אף פעם לא נשלחים אלינו.","privacy.p3":"iCloud: ההגדרות, התבניות, קבוצות לוחות השנה, הכללים, הצבעים והאמוג׳י של Weekdot מאוחסנים ב‑iCloud הפרטי שלך כדי שיסתנכרנו בין המכשירים שלך. אין לנו גישה אליהם.","privacy.p4":"מזג אוויר (אופציונלי): כשמפעילים את מזג האוויר, המיקום המשוער שלך נשלח ל‑Open-Meteo כדי לקבל תחזית. Weekdot לא שומר אותו.","privacy.p5":"ללא חשבונות, ללא מעקב, ללא פרסומות וללא ניתוח נתונים.","privacy.p6":"יש שאלות? אפשר לפנות אלינו דרך דף התמיכה.","privacy.updated":"עדכון אחרון: 24 באוקטובר 2026","support.title":"עזרה ותמיכה","s1.q":"Weekdot לא מציג אירועים","s1.a":"יש לאפשר גישה מלאה ללוח השנה: הגדרות › פרטיות ואבטחה › לוחות שנה › Weekdot › גישה מלאה.","s2.q":"איך מוסיפים לוח שנה של Google או Outlook?","s2.a":"מוסיפים את החשבון ב״הגדרות״ › אפליקציות › לוח שנה › חשבונות לוח שנה (Mac: האפליקציה ״לוח שנה״ › הוסף חשבון). Weekdot מציג אותו אוטומטית.","s3.q":"איך משנים את השפה?","s3.a":"Weekdot משתמש בשפת המכשיר שלך. ב‑iPhone וב‑iPad אפשר לבחור שפה עבור Weekdot בלבד ב״הגדרות״ › אפליקציות › Weekdot › שפה.","s4.q":"למה צלמית האפליקציה לא מציגה את התאריך של היום?","s4.a":"רק האפליקציה ״לוח שנה״ של Apple יכולה לשנות את הצלמית שלה בעצמה. הוסף/י את הווידג׳ט ‘היום’ של Weekdot למסך הבית כדי לראות תאריך עדכני. ב‑Mac, הצלמית ב‑Dock מציגה את התאריך של היום כש‑Weekdot פתוח.","s5.q":"האם הצבעים והתבניות שלי מסונכרנים?","s5.a":"כן, דרך iCloud. יש לוודא שהתחברת ל‑iCloud עם אותו חשבון Apple בכל המכשירים שלך.","footer.rights":"כל הזכויות שמורות.","lang.label":"שפה","mock.Meeting":"פגישה","mock.Lunch":"ארוחת צהריים","mock.Gym":"חדר כושר","mock.Dentist":"רופא שיניים","mock.Birthday":"יום הולדת","mock.Flight":"טיסה","mock.Holiday":"חופשה","mock.Day":"יום","mock.Week":"שבוע","mock.Month":"חודש","mock.Year":"שנה","mock.List":"רשימה","mock.Today":"היום","mock.Calendars":"לוחות שנה","mock.Color":"צבע","mock.Birthdays":"ימי הולדת","mock.Doctor":"רופא"},"hi":{"nav.features":"विशेषताएँ","nav.devices":"डिवाइस","nav.faq":"सामान्य प्रश्न","nav.support":"सपोर्ट","nav.privacy":"गोपनीयता","meta.description":"Weekdot iPhone, iPad, Apple Watch और Mac के लिए एक तेज़, सुंदर कैलेंडर है, जिसमें दिन, सप्ताह, महीना और वर्ष दृश्य हैं।","hero.title":"एक नज़र में आपका सप्ताह।","hero.sub":"Weekdot iPhone, iPad, Apple Watch और Mac के लिए एक तेज़, सुंदर कैलेंडर है। दिन, सप्ताह, महीना और वर्ष दृश्य, रंगों, इमोजी और टेम्पलेट के साथ — उन कैलेंडर पर जिनका आप पहले से उपयोग करते हैं।","hero.cta":"जल्द ही App Store पर","hero.note":"iCloud, Google, Outlook, Exchange और कैलेंडर ऐप के हर कैलेंडर के साथ काम करता है।","features.title":"आपकी हर योजना, एक ही दृश्य में","f1.t":"7 दिनों वाला सप्ताह दृश्य","f1.d":"अपना पूरा सप्ताह एक साथ देखें। 1 से 7 दिन चुनें, सप्ताह किसी भी दिन से शुरू करें और घंटों को ज़ूम करने के लिए पिंच करें।","f2.t":"दिन, महीना और वर्ष","f2.d":"इवेंट के नामों के साथ महीने या अपने व्यस्त दिनों के साथ वर्ष तक ज़ूम आउट करें, और सीधे जाने के लिए टैप करें।","f3.t":"ड्रैग, कॉपी और पेस्ट","f3.d":"ड्रैग करके इवेंट को ले जाएँ, उनकी अवधि बदलें, उन्हें दूसरे दिन कॉपी करें या एक टैप में डुप्लिकेट करें।","f4.t":"रंग और इमोजी","f4.d":"इवेंट को अपना रंग और इमोजी दें, या नियमों को शीर्षक के आधार पर इसे अपने आप करने दें।","f5.t":"टेम्पलेट","f5.d":"जिन इवेंट की आप अक्सर योजना बनाते हैं उन्हें सहेजें और एक टैप में जोड़ें। Weekdot पिछले इवेंट से विवरण भी सुझाता है।","f6.t":"आपके सभी कैलेंडर","f6.d":"कैलेंडर दिखाएँ, छिपाएँ और सेट में समूहित करें, नए कैलेंडर बनाएँ, अवकाशों या किसी भी .ics लिंक को सब्सक्राइब करें।","f7.t":"iCloud से सिंक","f7.d":"आपकी सेटिंग्ज़, टेम्पलेट, सेट, नियम, रंग और इमोजी हर डिवाइस पर एक जैसे रहते हैं।","f8.t":"विजेट और Apple Watch","f8.d":"आज, आगे और सप्ताह विजेट, साथ ही एक नज़र में आपके दिन और सप्ताह के लिए वॉच ऐप।","f9.t":"आपकी भाषा में","f9.d":"Weekdot 30 से अधिक भाषाएँ बोलता है और आपके डिवाइस की भाषा का पालन करता है।","f10.t":"मौसम","f10.d":"वैकल्पिक रूप से अपने दिनों के ऊपर पूर्वानुमान देखें।","devices.title":"आपके सभी Apple डिवाइस पर","devices.sub":"iPhone, iPad, Mac और Apple Watch के लिए एक ऐप।","faq.title":"प्रश्न","q1":"क्या Weekdot मेरे कैलेंडर अकाउंट की जगह लेता है?","a1":"नहीं। Weekdot कैलेंडर ऐप के कैलेंडर दिखाता और संपादित करता है, इसलिए सब कुछ iCloud, Google, Outlook या Exchange से सिंक होता रहता है।","q2":"मेरा डेटा कहाँ संग्रहित होता है?","a2":"आपके इवेंट आपके अपने कैलेंडर अकाउंट में रहते हैं। Weekdot की अपनी सेटिंग्ज़ आपके निजी iCloud से सिंक होती हैं। Weekdot के पास आपका डेटा संग्रहित करने वाला कोई सर्वर नहीं है।","q3":"कौन-सी भाषाएँ समर्थित हैं?","a3":"30 से अधिक, जिनमें अंग्रेज़ी, डच, जर्मन, फ़्रेंच, स्पैनिश, इतालवी, पुर्तगाली, चीनी, जापानी, कोरियाई और अरबी शामिल हैं।","q4":"क्या मैं अवकाश जोड़ सकता हूँ?","a4":"हाँ। एक टैप में कई देशों के सार्वजनिक अवकाश सब्सक्राइब करें, या कोई भी .ics लिंक पेस्ट करें।","privacy.title":"गोपनीयता","privacy.p1":"Weekdot इस तरह बनाया गया है कि आपका डेटा आपका ही रहे।","privacy.p2":"कैलेंडर डेटा: Weekdot केवल आपके डिवाइस के कैलेंडर अकाउंट (कैलेंडर ऐप) में इवेंट पढ़ता और लिखता है। आपके इवेंट कभी हमें नहीं भेजे जाते।","privacy.p3":"iCloud: Weekdot की अपनी सेटिंग्ज़, टेम्पलेट, कैलेंडर सेट, नियम, रंग और इमोजी आपके निजी iCloud में संग्रहित होते हैं ताकि वे आपके डिवाइस के बीच सिंक हों। हम उन्हें ऐक्सेस नहीं कर सकते।","privacy.p4":"मौसम (वैकल्पिक): जब आप मौसम चालू करते हैं, तो पूर्वानुमान पाने के लिए आपका अनुमानित स्थान Open-Meteo को भेजा जाता है। Weekdot इसे संग्रहित नहीं करता।","privacy.p5":"कोई अकाउंट नहीं, कोई ट्रैकिंग नहीं, कोई विज्ञापन नहीं और कोई एनालिटिक्स नहीं।","privacy.p6":"प्रश्न हैं? सपोर्ट पेज के माध्यम से संपर्क करें।","privacy.updated":"अंतिम अपडेट: 24 अक्टूबर 2026","support.title":"सहायता और सपोर्ट","s1.q":"Weekdot कोई इवेंट नहीं दिखाता","s1.a":"पूर्ण कैलेंडर ऐक्सेस की अनुमति दें: सेटिंग्ज़ › गोपनीयता और सुरक्षा › कैलेंडर › Weekdot › पूर्ण ऐक्सेस।","s2.q":"मैं Google या Outlook कैलेंडर कैसे जोड़ूँ?","s2.a":"सेटिंग्ज़ › ऐप्स › कैलेंडर › कैलेंडर अकाउंट में अकाउंट जोड़ें (Mac: कैलेंडर ऐप › अकाउंट जोड़ें)। Weekdot उसे अपने आप दिखाता है।","s3.q":"मैं भाषा कैसे बदलूँ?","s3.a":"Weekdot आपके डिवाइस की भाषा का पालन करता है। iPhone और iPad पर आप सेटिंग्ज़ › ऐप्स › Weekdot › भाषा में केवल Weekdot के लिए भाषा चुन सकते हैं।","s4.q":"ऐप आइकॉन आज की तारीख क्यों नहीं दिखाता?","s4.a":"केवल Apple का अपना कैलेंडर ऐप ही अपना आइकॉन खुद बदल सकता है। लाइव तारीख के लिए अपनी होम स्क्रीन पर Weekdot ‘आज’ विजेट जोड़ें। Mac पर, Weekdot खुला रहने पर Dock आइकॉन आज की तारीख दिखाता है।","s5.q":"क्या मेरे रंग और टेम्पलेट सिंक होते हैं?","s5.a":"हाँ, iCloud के माध्यम से। सुनिश्चित करें कि आप अपने सभी डिवाइस पर एक ही Apple अकाउंट से iCloud में साइन इन हैं।","footer.rights":"सर्वाधिकार सुरक्षित।","lang.label":"भाषा","mock.Meeting":"मीटिंग","mock.Lunch":"लंच","mock.Gym":"जिम","mock.Dentist":"दंतचिकित्सक","mock.Birthday":"जन्मदिन","mock.Flight":"उड़ान","mock.Holiday":"छुट्टी","mock.Day":"दिन","mock.Week":"सप्ताह","mock.Month":"महीना","mock.Year":"वर्ष","mock.List":"सूची","mock.Today":"आज","mock.Calendars":"कैलेंडर","mock.Color":"रंग","mock.Birthdays":"जन्मदिन","mock.Doctor":"डॉक्टर"},"hr":{"nav.features":"Značajke","nav.devices":"Uređaji","nav.faq":"Česta pitanja","nav.support":"Podrška","nav.privacy":"Privatnost","meta.description":"Weekdot je brz i lijep kalendar za iPhone, iPad, Apple Watch i Mac s prikazima dana, tjedna, mjeseca i godine.","hero.title":"Vaš tjedan na prvi pogled.","hero.sub":"Weekdot je brz i lijep kalendar za iPhone, iPad, Apple Watch i Mac. Prikazi dana, tjedna, mjeseca i godine s bojama, emojijima i predlošcima – povrh kalendara koje već koristite.","hero.cta":"Uskoro u App Storeu","hero.note":"Radi s iCloudom, Googleom, Outlookom, Exchangeom i svim kalendarima u aplikaciji Kalendar.","features.title":"Sve što planirate, u jednom prikazu","f1.t":"Prikaz tjedna sa 7 dana","f1.d":"Vidite cijeli tjedan odjednom. Odaberite od 1 do 7 dana, započnite tjedan bilo kojim danom i razmaknite prste za povećanje sati.","f2.t":"Dan, mjesec i godina","f2.d":"Umanjite na mjesec s nazivima događaja ili na godinu sa zauzetim danima i dodirnite za izravan skok.","f3.t":"Povlačenje, kopiranje i lijepljenje","f3.d":"Premještajte događaje povlačenjem, mijenjajte im trajanje, kopirajte ih na drugi dan ili ih duplicirajte jednim dodirom.","f4.t":"Boje i emojiji","f4.d":"Dajte događajima vlastitu boju i emoji ili neka to pravila učine automatski na temelju naziva.","f5.t":"Predlošci","f5.d":"Spremite događaje koje često planirate i dodajte ih jednim dodirom. Weekdot također predlaže pojedinosti iz ranijih događaja.","f6.t":"Svi vaši kalendari","f6.d":"Prikazujte, skrivajte i grupirajte kalendare u skupove, stvarajte nove, pretplatite se na blagdane ili bilo koju .ics poveznicu.","f7.t":"Sinkronizirano s iCloudom","f7.d":"Vaše postavke, predlošci, skupovi, pravila, boje i emojiji isti su na svakom uređaju.","f8.t":"Widgeti i Apple Watch","f8.d":"Widgeti Danas, Sljedeće i Tjedan te aplikacija za sat s pregledom dana i tjedna.","f9.t":"Na vašem jeziku","f9.d":"Weekdot govori više od 30 jezika i prati jezik vašeg uređaja.","f10.t":"Vrijeme","f10.d":"Po želji vidite prognozu iznad svojih dana.","devices.title":"Na svim vašim Apple uređajima","devices.sub":"Jedna aplikacija za iPhone, iPad, Mac i Apple Watch.","faq.title":"Pitanja","q1":"Zamjenjuje li Weekdot moje račune kalendara?","a1":"Ne. Weekdot prikazuje i uređuje kalendare iz aplikacije Kalendar, pa se sve i dalje sinkronizira putem iClouda, Googlea, Outlooka ili Exchangea.","q2":"Gdje se spremaju moji podaci?","a2":"Vaši događaji ostaju u vašim vlastitim računima kalendara. Vlastite postavke Weekdota sinkroniziraju se putem vašeg privatnog iClouda. Weekdot nema poslužitelje koji spremaju vaše podatke.","q3":"Koji su jezici podržani?","a3":"Više od 30, uključujući engleski, nizozemski, njemački, francuski, španjolski, talijanski, portugalski, kineski, japanski, korejski i arapski.","q4":"Mogu li dodati blagdane?","a4":"Da. Jednim dodirom pretplatite se na državne praznike mnogih zemalja ili zalijepite bilo koju .ics poveznicu.","privacy.title":"Privatnost","privacy.p1":"Weekdot je izrađen tako da vaši podaci ostanu vaši.","privacy.p2":"Podaci kalendara: Weekdot čita i zapisuje događaje samo u računima kalendara na vašem uređaju (aplikacija Kalendar). Vaši događaji nikad nam se ne šalju.","privacy.p3":"iCloud: vlastite postavke, predlošci, skupovi kalendara, pravila, boje i emojiji aplikacije Weekdot spremaju se u vaš privatni iCloud kako bi se sinkronizirali između vaših uređaja. Mi im ne možemo pristupiti.","privacy.p4":"Vrijeme (neobavezno): kada uključite vrijeme, vaša približna lokacija šalje se servisu Open-Meteo radi prognoze. Weekdot je ne sprema.","privacy.p5":"Bez računa, bez praćenja, bez oglasa i bez analitike.","privacy.p6":"Imate pitanja? Javite nam se putem stranice za podršku.","privacy.updated":"Zadnje ažuriranje: 24. listopada 2026.","support.title":"Pomoć i podrška","s1.q":"Weekdot ne prikazuje događaje","s1.a":"Dopustite potpuni pristup kalendaru: Postavke › Privatnost i sigurnost › Kalendari › Weekdot › Potpuni pristup.","s2.q":"Kako dodati Google ili Outlook kalendar?","s2.a":"Dodajte račun u Postavke › Aplikacije › Kalendar › Računi kalendara (Mac: aplikacija Kalendar › Dodaj račun). Weekdot ga prikazuje automatski.","s3.q":"Kako promijeniti jezik?","s3.a":"Weekdot prati jezik vašeg uređaja. Na iPhoneu i iPadu možete odabrati jezik samo za Weekdot u Postavke › Aplikacije › Weekdot › Jezik.","s4.q":"Zašto ikona aplikacije ne prikazuje današnji datum?","s4.a":"Samo Appleova aplikacija Kalendar može sama mijenjati svoju ikonu. Dodajte Weekdot widget ‘Danas’ na početni zaslon za aktualni datum. Na Macu ikona u Docku prikazuje današnji datum dok je Weekdot otvoren.","s5.q":"Sinkroniziraju li se moje boje i predlošci?","s5.a":"Da, putem iClouda. Provjerite jeste li na svim uređajima prijavljeni na iCloud istim Apple računom.","footer.rights":"Sva prava pridržana.","lang.label":"Jezik","mock.Meeting":"Sastanak","mock.Lunch":"Ručak","mock.Gym":"Teretana","mock.Dentist":"Zubar","mock.Birthday":"Rođendan","mock.Flight":"Let","mock.Holiday":"Godišnji","mock.Day":"Dan","mock.Week":"Tjedan","mock.Month":"Mjesec","mock.Year":"Godina","mock.List":"Popis","mock.Today":"Danas","mock.Calendars":"Kalendari","mock.Color":"Boja","mock.Birthdays":"Rođendani","mock.Doctor":"Liječnik"},"hu":{"nav.features":"Funkciók","nav.devices":"Eszközök","nav.faq":"GYIK","nav.support":"Támogatás","nav.privacy":"Adatvédelem","meta.description":"A Weekdot egy gyors, gyönyörű naptár iPhone-ra, iPadre, Apple Watchra és Macre napi, heti, havi és éves nézettel.","hero.title":"A hete egy pillantással.","hero.sub":"A Weekdot egy gyors, gyönyörű naptár iPhone-ra, iPadre, Apple Watchra és Macre. Napi, heti, havi és éves nézet színekkel, emojikkal és sablonokkal – a már használt naptárai alapján.","hero.cta":"Hamarosan az App Store-ban","hero.note":"Működik az iClouddal, a Google-lel, az Outlookkal, az Exchange-dzsel és a Naptár app minden naptárával.","features.title":"Minden, amit tervez, egy nézetben","f1.t":"Heti nézet 7 nappal","f1.d":"Lássa egyszerre az egész hetét. Válasszon 1–7 napot, kezdje a hetet bármelyik napon, és csippentéssel nagyítsa az órákat.","f2.t":"Nap, hónap és év","f2.d":"Kicsinyítsen havi nézetre az események nevével vagy éves nézetre a zsúfolt napokkal, és koppintással ugorjon be.","f3.t":"Húzás, másolás és beillesztés","f3.d":"Mozgassa az eseményeket húzással, módosítsa a hosszukat, másolja őket egy másik napra, vagy duplikálja egy koppintással.","f4.t":"Színek és emojik","f4.d":"Adjon az eseményeknek saját színt és emojit, vagy bízza a szabályokra, hogy a cím alapján automatikusan megtegyék.","f5.t":"Sablonok","f5.d":"Mentse el a gyakran tervezett eseményeket, és adja hozzá őket egy koppintással. A Weekdot a korábbi eseményekből is javasol részleteket.","f6.t":"Minden naptára","f6.d":"Jelenítse meg, rejtse el és csoportosítsa a naptárakat, hozzon létre újakat, iratkozzon fel ünnepekre vagy bármilyen .ics linkre.","f7.t":"Szinkronizálva az iClouddal","f7.d":"A beállításai, sablonjai, csoportjai, szabályai, színei és emojijai minden eszközön ugyanazok.","f8.t":"Widgetek és Apple Watch","f8.d":"Ma, Következő és Hét widgetek, valamint egy óraapp, amellyel egy pillantással látja a napját és a hetét.","f9.t":"Az Ön nyelvén","f9.d":"A Weekdot több mint 30 nyelven beszél, és az eszköze nyelvét használja.","f10.t":"Időjárás","f10.d":"Igény szerint láthatja az előrejelzést a napjai felett.","devices.title":"Minden Apple-eszközén","devices.sub":"Egy app iPhone-ra, iPadre, Macre és Apple Watchra.","faq.title":"Kérdések","q1":"Helyettesíti a Weekdot a naptárfiókjaimat?","a1":"Nem. A Weekdot a Naptár app naptárait jeleníti meg és szerkeszti, így minden továbbra is az iCloudon, a Google-ön, az Outlookon vagy az Exchange-en keresztül szinkronizálódik.","q2":"Hol tárolódnak az adataim?","a2":"Az eseményei a saját naptárfiókjaiban maradnak. A Weekdot saját beállításai a privát iCloudján keresztül szinkronizálódnak. A Weekdotnek nincsenek szerverei, amelyek az adatait tárolnák.","q3":"Milyen nyelveket támogat?","a3":"Több mint 30-at, köztük angolt, hollandot, németet, franciát, spanyolt, olaszt, portugált, kínait, japánt, koreait és arabot.","q4":"Hozzáadhatok ünnepeket?","a4":"Igen. Egy koppintással feliratkozhat sok ország munkaszüneti napjaira, vagy beilleszthet bármilyen .ics linket.","privacy.title":"Adatvédelem","privacy.p1":"A Weekdot úgy készült, hogy az adatai az Öné maradjanak.","privacy.p2":"Naptáradatok: a Weekdot csak az eszközén lévő naptárfiókokban (Naptár app) olvas és ír eseményeket. Az eseményeit soha nem küldjük el magunknak.","privacy.p3":"iCloud: a Weekdot saját beállításai, sablonjai, naptárcsoportjai, szabályai, színei és emojijai a privát iCloudjában tárolódnak, hogy szinkronizálódjanak az eszközei között. Mi nem férünk hozzájuk.","privacy.p4":"Időjárás (opcionális): ha bekapcsolja az időjárást, a hozzávetőleges helyzete elküldésre kerül az Open-Meteónak az előrejelzéshez. A Weekdot nem tárolja.","privacy.p5":"Nincsenek fiókok, nincs követés, nincsenek hirdetések és nincs analitika.","privacy.p6":"Kérdése van? Vegye fel velünk a kapcsolatot a támogatási oldalon.","privacy.updated":"Utolsó frissítés: 2026. október 24.","support.title":"Súgó és támogatás","s1.q":"A Weekdot nem jelenít meg eseményeket","s1.a":"Engedélyezze a teljes naptárhozzáférést: Beállítások › Adatvédelem és biztonság › Naptárak › Weekdot › Teljes hozzáférés.","s2.q":"Hogyan adhatok hozzá Google- vagy Outlook-naptárat?","s2.a":"Adja hozzá a fiókot a Beállítások › Appok › Naptár › Naptárfiókok menüben (Mac: Naptár app › Fiók hozzáadása). A Weekdot automatikusan megjeleníti.","s3.q":"Hogyan módosíthatom a nyelvet?","s3.a":"A Weekdot az eszköze nyelvét használja. iPhone-on és iPaden a Beállítások › Appok › Weekdot › Nyelv menüben választhat nyelvet csak a Weekdot számára.","s4.q":"Miért nem mutatja az app ikonja a mai dátumot?","s4.a":"Csak az Apple saját Naptár appja tudja magától módosítani az ikonját. Adja hozzá a Weekdot ‚Ma’ widgetet a Főképernyőhöz az aktuális dátumhoz. Macen a Dockban lévő ikon mutatja a mai dátumot, amíg a Weekdot nyitva van.","s5.q":"Szinkronizálódnak a színeim és sablonjaim?","s5.a":"Igen, az iCloudon keresztül. Győződjön meg róla, hogy minden eszközén ugyanazzal az Apple-fiókkal van bejelentkezve az iCloudba.","footer.rights":"Minden jog fenntartva.","lang.label":"Nyelv","mock.Meeting":"Megbeszélés","mock.Lunch":"Ebéd","mock.Gym":"Edzés","mock.Dentist":"Fogorvos","mock.Birthday":"Születésnap","mock.Flight":"Repülés","mock.Holiday":"Szabadság","mock.Day":"Nap","mock.Week":"Hét","mock.Month":"Hónap","mock.Year":"Év","mock.List":"Lista","mock.Today":"Ma","mock.Calendars":"Naptárak","mock.Color":"Szín","mock.Birthdays":"Születésnapok","mock.Doctor":"Orvos"},"id":{"nav.features":"Fitur","nav.devices":"Perangkat","nav.faq":"FAQ","nav.support":"Dukungan","nav.privacy":"Privasi","meta.description":"Weekdot adalah kalender yang cepat dan indah untuk iPhone, iPad, Apple Watch, dan Mac dengan tampilan hari, minggu, bulan, dan tahun.","hero.title":"Minggu Anda dalam sekejap.","hero.sub":"Weekdot adalah kalender yang cepat dan indah untuk iPhone, iPad, Apple Watch, dan Mac. Tampilan hari, minggu, bulan, dan tahun, dengan warna, emoji, dan templat — di atas kalender yang sudah Anda gunakan.","hero.cta":"Segera hadir di App Store","hero.note":"Bekerja dengan iCloud, Google, Outlook, Exchange, dan setiap kalender di app Kalender.","features.title":"Semua rencana Anda, dalam satu tampilan","f1.t":"Tampilan minggu dengan 7 hari","f1.d":"Lihat seluruh minggu Anda sekaligus. Pilih 1 hingga 7 hari, mulai minggu di hari apa pun, dan cubit untuk memperbesar jam.","f2.t":"Hari, bulan, dan tahun","f2.d":"Perkecil ke bulan dengan nama acara atau ke tahun dengan hari-hari sibuk Anda, lalu ketuk untuk langsung masuk.","f3.t":"Seret, salin & tempel","f3.d":"Pindahkan acara dengan menyeret, ubah durasinya, salin ke hari lain, atau duplikatkan dengan satu ketukan.","f4.t":"Warna & emoji","f4.d":"Beri acara warna dan emoji sendiri, atau biarkan aturan melakukannya secara otomatis berdasarkan judul.","f5.t":"Templat","f5.d":"Simpan acara yang sering Anda rencanakan dan tambahkan dengan satu ketukan. Weekdot juga menyarankan detail dari acara sebelumnya.","f6.t":"Semua kalender Anda","f6.d":"Tampilkan, sembunyikan, dan kelompokkan kalender ke dalam set, buat yang baru, berlangganan hari libur atau tautan .ics apa pun.","f7.t":"Diselaraskan dengan iCloud","f7.d":"Pengaturan, templat, set, aturan, warna, dan emoji Anda sama di setiap perangkat.","f8.t":"Widget & Apple Watch","f8.d":"Widget Hari Ini, Berikutnya, dan Minggu, ditambah app jam untuk melihat hari dan minggu Anda sekilas.","f9.t":"Dalam bahasa Anda","f9.d":"Weekdot tersedia dalam lebih dari 30 bahasa dan mengikuti bahasa perangkat Anda.","f10.t":"Cuaca","f10.d":"Opsional, lihat prakiraan di atas hari Anda.","devices.title":"Di semua perangkat Apple Anda","devices.sub":"Satu app untuk iPhone, iPad, Mac, dan Apple Watch.","faq.title":"Pertanyaan","q1":"Apakah Weekdot menggantikan akun kalender saya?","a1":"Tidak. Weekdot menampilkan dan mengedit kalender dari app Kalender, sehingga semuanya tetap diselaraskan melalui iCloud, Google, Outlook, atau Exchange.","q2":"Di mana data saya disimpan?","a2":"Acara Anda tetap berada di akun kalender Anda sendiri. Pengaturan Weekdot sendiri diselaraskan melalui iCloud pribadi Anda. Weekdot tidak memiliki server yang menyimpan data Anda.","q3":"Bahasa apa saja yang didukung?","a3":"Lebih dari 30, termasuk Inggris, Belanda, Jerman, Prancis, Spanyol, Italia, Portugis, Tionghoa, Jepang, Korea, dan Arab.","q4":"Bisakah saya menambahkan hari libur?","a4":"Ya. Berlangganan hari libur nasional untuk banyak negara dengan satu ketukan, atau tempel tautan .ics apa pun.","privacy.title":"Privasi","privacy.p1":"Weekdot dibuat agar data Anda tetap milik Anda.","privacy.p2":"Data kalender: Weekdot hanya membaca dan menulis acara di akun kalender di perangkat Anda (app Kalender). Acara Anda tidak pernah dikirim kepada kami.","privacy.p3":"iCloud: Pengaturan, templat, set kalender, aturan, warna, dan emoji Weekdot sendiri disimpan di iCloud pribadi Anda agar diselaraskan antarperangkat Anda. Kami tidak dapat mengaksesnya.","privacy.p4":"Cuaca (opsional): saat Anda menyalakan cuaca, perkiraan lokasi Anda dikirim ke Open-Meteo untuk mendapatkan prakiraan. Weekdot tidak menyimpannya.","privacy.p5":"Tanpa akun, tanpa pelacakan, tanpa iklan, dan tanpa analitik.","privacy.p6":"Ada pertanyaan? Hubungi kami melalui halaman dukungan.","privacy.updated":"Terakhir diperbarui: 24 Oktober 2026","support.title":"Bantuan & Dukungan","s1.q":"Weekdot tidak menampilkan acara","s1.a":"Izinkan akses kalender penuh: Pengaturan › Privasi & Keamanan › Kalender › Weekdot › Akses Penuh.","s2.q":"Bagaimana cara menambahkan kalender Google atau Outlook?","s2.a":"Tambahkan akun di Pengaturan › App › Kalender › Akun Kalender (Mac: app Kalender › Tambah Akun). Weekdot menampilkannya secara otomatis.","s3.q":"Bagaimana cara mengubah bahasa?","s3.a":"Weekdot mengikuti bahasa perangkat Anda. Di iPhone dan iPad, Anda dapat memilih bahasa khusus untuk Weekdot di Pengaturan › App › Weekdot › Bahasa.","s4.q":"Mengapa ikon app tidak menampilkan tanggal hari ini?","s4.a":"Hanya app Kalender milik Apple yang dapat mengubah ikonnya sendiri. Tambahkan widget ‘Hari Ini’ Weekdot ke Layar Utama Anda untuk tanggal langsung. Di Mac, ikon Dock menampilkan tanggal hari ini saat Weekdot terbuka.","s5.q":"Apakah warna dan templat saya diselaraskan?","s5.a":"Ya, melalui iCloud. Pastikan Anda masuk ke iCloud dengan Akun Apple yang sama di semua perangkat Anda.","footer.rights":"Hak cipta dilindungi undang-undang.","lang.label":"Bahasa","mock.Meeting":"Rapat","mock.Lunch":"Makan Siang","mock.Gym":"Gym","mock.Dentist":"Dokter Gigi","mock.Birthday":"Ulang Tahun","mock.Flight":"Penerbangan","mock.Holiday":"Liburan","mock.Day":"Hari","mock.Week":"Minggu","mock.Month":"Bulan","mock.Year":"Tahun","mock.List":"Daftar","mock.Today":"Hari Ini","mock.Calendars":"Kalender","mock.Color":"Warna","mock.Birthdays":"Ulang Tahun","mock.Doctor":"Dokter"},"it":{"nav.features":"Funzionalità","nav.devices":"Dispositivi","nav.faq":"FAQ","nav.support":"Supporto","nav.privacy":"Privacy","meta.description":"Weekdot è un calendario veloce ed elegante per iPhone, iPad, Apple Watch e Mac con viste giorno, settimana, mese e anno.","hero.title":"La tua settimana a colpo d’occhio.","hero.sub":"Weekdot è un calendario veloce ed elegante per iPhone, iPad, Apple Watch e Mac. Viste giorno, settimana, mese e anno, con colori, emoji e modelli, sopra i calendari che usi già.","hero.cta":"Presto su App Store","hero.note":"Funziona con iCloud, Google, Outlook, Exchange e ogni calendario dell’app Calendario.","features.title":"Tutto ciò che pianifichi, in un’unica vista","f1.t":"Vista Settimana con 7 giorni","f1.d":"Vedi tutta la settimana in una volta. Scegli da 1 a 7 giorni, inizia la settimana in qualsiasi giorno e pizzica per ingrandire le ore.","f2.t":"Giorno, mese e anno","f2.d":"Rimpicciolisci a un mese con i nomi degli eventi o a un anno con i tuoi giorni impegnati, e tocca per andarci subito.","f3.t":"Trascina, copia e incolla","f3.d":"Sposta gli eventi trascinandoli, modificane la durata, copiali in un altro giorno o duplicali con un tocco.","f4.t":"Colori ed emoji","f4.d":"Dai agli eventi un colore e un’emoji propri, oppure lascia che le regole lo facciano automaticamente in base al titolo.","f5.t":"Modelli","f5.d":"Salva gli eventi che pianifichi spesso e aggiungili con un tocco. Weekdot suggerisce anche dettagli dagli eventi precedenti.","f6.t":"Tutti i tuoi calendari","f6.d":"Mostra, nascondi e raggruppa i calendari in set, creane di nuovi, iscriviti alle festività o a qualsiasi link .ics.","f7.t":"Sincronizzato con iCloud","f7.d":"Impostazioni, modelli, set, regole, colori ed emoji sono uguali su ogni dispositivo.","f8.t":"Widget e Apple Watch","f8.d":"Widget Oggi, Prossimi e Settimana, più un’app per l’orologio con la tua giornata e la tua settimana a colpo d’occhio.","f9.t":"Nella tua lingua","f9.d":"Weekdot parla più di 30 lingue e segue la lingua del tuo dispositivo.","f10.t":"Meteo","f10.d":"Se vuoi, vedi le previsioni sopra i tuoi giorni.","devices.title":"Su tutti i tuoi dispositivi Apple","devices.sub":"Un’unica app per iPhone, iPad, Mac e Apple Watch.","faq.title":"Domande","q1":"Weekdot sostituisce i miei account di calendario?","a1":"No. Weekdot mostra e modifica i calendari dell’app Calendario, quindi tutto continua a sincronizzarsi tramite iCloud, Google, Outlook o Exchange.","q2":"Dove vengono archiviati i miei dati?","a2":"I tuoi eventi restano nei tuoi account di calendario. Le impostazioni di Weekdot si sincronizzano tramite il tuo iCloud privato. Weekdot non ha server che archiviano i tuoi dati.","q3":"Quali lingue sono supportate?","a3":"Più di 30, tra cui inglese, olandese, tedesco, francese, spagnolo, italiano, portoghese, cinese, giapponese, coreano e arabo.","q4":"Posso aggiungere le festività?","a4":"Sì. Iscriviti con un tocco alle festività nazionali di molti paesi, oppure incolla qualsiasi link .ics.","privacy.title":"Privacy","privacy.p1":"Weekdot è pensato perché i tuoi dati restino tuoi.","privacy.p2":"Dati del calendario: Weekdot legge e scrive eventi solo negli account di calendario del tuo dispositivo (l’app Calendario). I tuoi eventi non ci vengono mai inviati.","privacy.p3":"iCloud: le impostazioni, i modelli, i set di calendari, le regole, i colori e le emoji di Weekdot sono archiviati nel tuo iCloud privato, così si sincronizzano tra i tuoi dispositivi. Noi non possiamo accedervi.","privacy.p4":"Meteo (facoltativo): quando attivi il meteo, la tua posizione approssimativa viene inviata a Open-Meteo per ottenere le previsioni. Weekdot non la conserva.","privacy.p5":"Nessun account, nessun tracciamento, nessuna pubblicità e nessuna analisi.","privacy.p6":"Domande? Contattaci tramite la pagina di supporto.","privacy.updated":"Ultimo aggiornamento: 24 ottobre 2026","support.title":"Aiuto e supporto","s1.q":"Weekdot non mostra eventi","s1.a":"Consenti l’accesso completo al calendario: Impostazioni › Privacy e sicurezza › Calendari › Weekdot › Accesso completo.","s2.q":"Come aggiungo un calendario Google o Outlook?","s2.a":"Aggiungi l’account in Impostazioni › App › Calendario › Account calendario (Mac: app Calendario › Aggiungi account). Weekdot lo mostra automaticamente.","s3.q":"Come cambio la lingua?","s3.a":"Weekdot segue la lingua del tuo dispositivo. Su iPhone e iPad puoi scegliere una lingua solo per Weekdot in Impostazioni › App › Weekdot › Lingua.","s4.q":"Perché l’icona dell’app non mostra la data di oggi?","s4.a":"Solo l’app Calendario di Apple può cambiare da sola la propria icona. Aggiungi il widget “Oggi” di Weekdot alla schermata Home per una data sempre aggiornata. Sul Mac, l’icona nel Dock mostra la data di oggi mentre Weekdot è aperto.","s5.q":"I miei colori e modelli si sincronizzano?","s5.a":"Sì, tramite iCloud. Assicurati di aver effettuato l’accesso a iCloud con lo stesso Account Apple su tutti i tuoi dispositivi.","footer.rights":"Tutti i diritti riservati.","lang.label":"Lingua","mock.Meeting":"Riunione","mock.Lunch":"Pranzo","mock.Gym":"Palestra","mock.Dentist":"Dentista","mock.Birthday":"Compleanno","mock.Flight":"Volo","mock.Holiday":"Vacanza","mock.Day":"Giorno","mock.Week":"Settimana","mock.Month":"Mese","mock.Year":"Anno","mock.List":"Elenco","mock.Today":"Oggi","mock.Calendars":"Calendari","mock.Color":"Colore","mock.Birthdays":"Compleanni","mock.Doctor":"Medico"},"ja":{"nav.features":"機能","nav.devices":"デバイス","nav.faq":"よくある質問","nav.support":"サポート","nav.privacy":"プライバシー","meta.description":"Weekdotは、iPhone、iPad、Apple Watch、Mac向けの高速で美しいカレンダーです。日、週、月、年表示に対応しています。","hero.title":"1週間をひと目で。","hero.sub":"Weekdotは、iPhone、iPad、Apple Watch、Mac向けの高速で美しいカレンダーです。日、週、月、年表示に、色、絵文字、テンプレート。すでに使っているカレンダーの上で動作します。","hero.cta":"App Storeで近日公開","hero.note":"iCloud、Google、Outlook、Exchange、およびカレンダーAppのすべてのカレンダーに対応。","features.title":"予定のすべてを、ひとつの画面に","f1.t":"7日間の週表示","f1.d":"1週間全体をひと目で確認。1〜7日を選択し、週の開始曜日を自由に設定、ピンチで時間を拡大縮小できます。","f2.t":"日、月、年","f2.d":"イベント名付きの月表示や、予定のある日がわかる年表示に縮小し、タップするとすぐに移動できます。","f3.t":"ドラッグ、コピー＆ペースト","f3.d":"ドラッグでイベントを移動したり、長さを変更したり、別の日にコピーしたり、ワンタップで複製したりできます。","f4.t":"色と絵文字","f4.d":"イベントに独自の色と絵文字を設定したり、タイトルに基づいてルールで自動的に設定したりできます。","f5.t":"テンプレート","f5.d":"よく使うイベントを保存して、ワンタップで追加。Weekdotは以前のイベントから詳細の候補も表示します。","f6.t":"すべてのカレンダー","f6.d":"カレンダーの表示/非表示、セットへのグループ化、新規作成、祝日や任意の.icsリンクの照会ができます。","f7.t":"iCloudで同期","f7.d":"設定、テンプレート、セット、ルール、色、絵文字がすべてのデバイスで同じになります。","f8.t":"ウィジェットとApple Watch","f8.d":"「今日」「次の予定」「週」ウィジェットに加えて、1日と1週間をひと目で確認できるWatchアプリも。","f9.t":"あなたの言語で","f9.d":"Weekdotは30以上の言語に対応し、デバイスの言語に従います。","f10.t":"天気","f10.d":"必要に応じて、日付の上に天気予報を表示できます。","devices.title":"すべてのAppleデバイスで","devices.sub":"iPhone、iPad、Mac、Apple Watchのためのひとつのアプリ。","faq.title":"よくある質問","q1":"Weekdotはカレンダーアカウントの代わりになりますか？","a1":"いいえ。WeekdotはカレンダーAppのカレンダーを表示・編集するため、すべてがiCloud、Google、Outlook、Exchangeを通じて引き続き同期されます。","q2":"データはどこに保存されますか？","a2":"イベントはご自身のカレンダーアカウントに保存されます。Weekdot独自の設定はプライベートなiCloudで同期されます。Weekdotにはデータを保存するサーバはありません。","q3":"対応している言語は？","a3":"30以上の言語に対応しています。英語、オランダ語、ドイツ語、フランス語、スペイン語、イタリア語、ポルトガル語、中国語、日本語、韓国語、アラビア語など。","q4":"祝日を追加できますか？","a4":"はい。多くの国の祝日をワンタップで照会できるほか、任意の.icsリンクをペーストすることもできます。","privacy.title":"プライバシー","privacy.p1":"Weekdotは、あなたのデータをあなたのものとして守るように設計されています。","privacy.p2":"カレンダーデータ：Weekdotは、デバイス上のカレンダーアカウント（カレンダーApp）でのみイベントを読み書きします。イベントが私たちに送信されることはありません。","privacy.p3":"iCloud：Weekdot独自の設定、テンプレート、カレンダーセット、ルール、色、絵文字は、デバイス間で同期するためにプライベートなiCloudに保存されます。私たちがそれらにアクセスすることはできません。","privacy.p4":"天気（オプション）：天気をオンにすると、予報を取得するためにおおよその位置情報がOpen-Meteoに送信されます。Weekdotはこれを保存しません。","privacy.p5":"アカウント不要、トラッキング、広告、分析は一切ありません。","privacy.p6":"ご質問は、サポートページからお問い合わせください。","privacy.updated":"最終更新日：2026年10月24日","support.title":"ヘルプとサポート","s1.q":"Weekdotにイベントが表示されない","s1.a":"カレンダーへのフルアクセスを許可してください：設定 › プライバシーとセキュリティ › カレンダー › Weekdot › フルアクセス。","s2.q":"GoogleやOutlookのカレンダーを追加するには？","s2.a":"設定 › アプリ › カレンダー › カレンダーアカウントでアカウントを追加してください（Mac：カレンダーApp › アカウントを追加）。Weekdotに自動的に表示されます。","s3.q":"言語を変更するには？","s3.a":"Weekdotはデバイスの言語に従います。iPhoneとiPadでは、設定 › アプリ › Weekdot › 言語で、Weekdotだけの言語を選択できます。","s4.q":"アプリのアイコンに今日の日付が表示されないのはなぜですか？","s4.a":"アイコンを自動で変更できるのは、Apple純正のカレンダーAppだけです。リアルタイムの日付を表示するには、Weekdotの「今日」ウィジェットをホーム画面に追加してください。Macでは、Weekdotを開いている間、Dockアイコンに今日の日付が表示されます。","s5.q":"色やテンプレートは同期されますか？","s5.a":"はい、iCloudで同期されます。すべてのデバイスで同じApple AccountでiCloudにサインインしていることを確認してください。","footer.rights":"All rights reserved.","lang.label":"言語","mock.Meeting":"会議","mock.Lunch":"ランチ","mock.Gym":"ジム","mock.Dentist":"歯医者","mock.Birthday":"誕生日","mock.Flight":"フライト","mock.Holiday":"休暇","mock.Day":"日","mock.Week":"週","mock.Month":"月","mock.Year":"年","mock.List":"リスト","mock.Today":"今日","mock.Calendars":"カレンダー","mock.Color":"色","mock.Birthdays":"誕生日","mock.Doctor":"病院"},"ko":{"nav.features":"기능","nav.devices":"기기","nav.faq":"자주 묻는 질문","nav.support":"지원","nav.privacy":"개인정보 보호","meta.description":"Weekdot은 일, 주, 월 및 연 보기를 제공하는 iPhone, iPad, Apple Watch 및 Mac용의 빠르고 아름다운 캘린더입니다.","hero.title":"한 주를 한눈에.","hero.sub":"Weekdot은 iPhone, iPad, Apple Watch 및 Mac용의 빠르고 아름다운 캘린더입니다. 일, 주, 월 및 연 보기와 색상, 이모지, 템플릿을 이미 사용 중인 캘린더 위에서 이용할 수 있습니다.","hero.cta":"App Store 출시 예정","hero.note":"iCloud, Google, Outlook, Exchange 및 캘린더 앱의 모든 캘린더와 호환됩니다.","features.title":"계획한 모든 것을 하나의 화면에서","f1.t":"7일 주 보기","f1.d":"한 주 전체를 한 번에 확인하십시오. 1~7일을 선택하고, 원하는 요일에 주를 시작하고, 핀치하여 시간을 확대/축소할 수 있습니다.","f2.t":"일, 월 및 연","f2.d":"이벤트 이름이 표시된 월 또는 바쁜 날이 표시된 연으로 축소하고, 탭하여 바로 이동할 수 있습니다.","f3.t":"드래그, 복사 및 붙여넣기","f3.d":"드래그하여 이벤트를 이동하고, 길이를 변경하고, 다른 날로 복사하거나 한 번의 탭으로 복제할 수 있습니다.","f4.t":"색상 및 이모지","f4.d":"이벤트에 고유한 색상과 이모지를 지정하거나, 제목을 기반으로 규칙이 자동으로 적용하도록 하십시오.","f5.t":"템플릿","f5.d":"자주 계획하는 이벤트를 저장하고 한 번의 탭으로 추가하십시오. Weekdot은 이전 이벤트의 세부사항도 제안합니다.","f6.t":"모든 캘린더","f6.d":"캘린더를 표시, 가리기 및 세트로 그룹화하고, 새로 생성하고, 공휴일이나 모든 .ics 링크를 구독할 수 있습니다.","f7.t":"iCloud와 동기화","f7.d":"설정, 템플릿, 세트, 규칙, 색상 및 이모지가 모든 기기에서 동일합니다.","f8.t":"위젯 및 Apple Watch","f8.d":"오늘, 다음 일정 및 주 위젯과 함께, 하루와 한 주를 한눈에 볼 수 있는 Watch 앱을 제공합니다.","f9.t":"사용자의 언어로","f9.d":"Weekdot은 30개 이상의 언어를 지원하며 기기의 언어를 따릅니다.","f10.t":"날씨","f10.d":"선택적으로 날짜 위에 일기예보를 볼 수 있습니다.","devices.title":"모든 Apple 기기에서","devices.sub":"iPhone, iPad, Mac 및 Apple Watch를 위한 하나의 앱.","faq.title":"자주 묻는 질문","q1":"Weekdot이 캘린더 계정을 대체합니까?","a1":"아니요. Weekdot은 캘린더 앱의 캘린더를 표시하고 편집하므로 모든 항목이 iCloud, Google, Outlook 또는 Exchange를 통해 계속 동기화됩니다.","q2":"데이터는 어디에 저장됩니까?","a2":"이벤트는 사용자 자신의 캘린더 계정에 유지됩니다. Weekdot의 자체 설정은 개인 iCloud를 통해 동기화됩니다. Weekdot에는 데이터를 저장하는 서버가 없습니다.","q3":"지원되는 언어는 무엇입니까?","a3":"영어, 네덜란드어, 독일어, 프랑스어, 스페인어, 이탈리아어, 포르투갈어, 중국어, 일본어, 한국어, 아랍어를 포함한 30개 이상의 언어를 지원합니다.","q4":"공휴일을 추가할 수 있습니까?","a4":"예. 한 번의 탭으로 여러 국가의 공휴일을 구독하거나 모든 .ics 링크를 붙여넣을 수 있습니다.","privacy.title":"개인정보 보호","privacy.p1":"Weekdot은 사용자의 데이터를 사용자만의 것으로 유지하도록 설계되었습니다.","privacy.p2":"캘린더 데이터: Weekdot은 기기에 있는 캘린더 계정(캘린더 앱)에서만 이벤트를 읽고 씁니다. 사용자의 이벤트는 절대 당사로 전송되지 않습니다.","privacy.p3":"iCloud: Weekdot의 자체 설정, 템플릿, 캘린더 세트, 규칙, 색상 및 이모지는 기기 간에 동기화되도록 개인 iCloud에 저장됩니다. 당사는 이에 접근할 수 없습니다.","privacy.p4":"날씨(선택 사항): 날씨를 켜면 일기예보를 가져오기 위해 대략적인 위치가 Open-Meteo로 전송됩니다. Weekdot은 이를 저장하지 않습니다.","privacy.p5":"계정, 추적, 광고 및 분석이 없습니다.","privacy.p6":"궁금한 점이 있습니까? 지원 페이지를 통해 문의하십시오.","privacy.updated":"마지막 업데이트: 2026년 10월 24일","support.title":"도움말 및 지원","s1.q":"Weekdot에 이벤트가 표시되지 않음","s1.a":"캘린더 전체 접근을 허용하십시오: 설정 › 개인정보 보호 및 보안 › 캘린더 › Weekdot › 전체 접근.","s2.q":"Google 또는 Outlook 캘린더를 추가하려면 어떻게 합니까?","s2.a":"설정 › 앱 › 캘린더 › 캘린더 계정에서 계정을 추가하십시오(Mac: 캘린더 앱 › 계정 추가). Weekdot에 자동으로 표시됩니다.","s3.q":"언어를 변경하려면 어떻게 합니까?","s3.a":"Weekdot은 기기의 언어를 따릅니다. iPhone 및 iPad에서는 설정 › 앱 › Weekdot › 언어에서 Weekdot에만 적용할 언어를 선택할 수 있습니다.","s4.q":"앱 아이콘에 오늘 날짜가 표시되지 않는 이유는 무엇입니까?","s4.a":"아이콘을 스스로 변경할 수 있는 것은 Apple의 캘린더 앱뿐입니다. 실시간 날짜를 보려면 Weekdot의 ‘오늘’ 위젯을 홈 화면에 추가하십시오. Mac에서는 Weekdot이 열려 있는 동안 Dock 아이콘에 오늘 날짜가 표시됩니다.","s5.q":"색상과 템플릿이 동기화됩니까?","s5.a":"예, iCloud를 통해 동기화됩니다. 모든 기기에서 동일한 Apple 계정으로 iCloud에 로그인되어 있는지 확인하십시오.","footer.rights":"모든 권리 보유.","lang.label":"언어","mock.Meeting":"회의","mock.Lunch":"점심","mock.Gym":"헬스","mock.Dentist":"치과","mock.Birthday":"생일","mock.Flight":"비행","mock.Holiday":"휴가","mock.Day":"일","mock.Week":"주","mock.Month":"월","mock.Year":"연","mock.List":"목록","mock.Today":"오늘","mock.Calendars":"캘린더","mock.Color":"색상","mock.Birthdays":"생일","mock.Doctor":"병원"},"ms":{"nav.features":"Ciri","nav.devices":"Peranti","nav.faq":"Soalan Lazim","nav.support":"Sokongan","nav.privacy":"Privasi","meta.description":"Weekdot ialah kalendar yang pantas dan cantik untuk iPhone, iPad, Apple Watch dan Mac dengan paparan hari, minggu, bulan dan tahun.","hero.title":"Minggu anda sepintas lalu.","hero.sub":"Weekdot ialah kalendar yang pantas dan cantik untuk iPhone, iPad, Apple Watch dan Mac. Paparan hari, minggu, bulan dan tahun, dengan warna, emoji dan templat — di atas kalendar yang sudah anda gunakan.","hero.cta":"Akan datang ke App Store","hero.note":"Berfungsi dengan iCloud, Google, Outlook, Exchange dan setiap kalendar dalam app Kalendar.","features.title":"Semua yang anda rancang, dalam satu paparan","f1.t":"Paparan minggu dengan 7 hari","f1.d":"Lihat seluruh minggu anda sekali gus. Pilih 1 hingga 7 hari, mulakan minggu pada mana-mana hari dan cubit untuk mengezum jam.","f2.t":"Hari, bulan dan tahun","f2.d":"Zum keluar ke bulan dengan nama acara atau ke tahun dengan hari sibuk anda, dan ketik untuk terus masuk.","f3.t":"Seret, salin & tampal","f3.d":"Alihkan acara dengan menyeret, tukar tempohnya, salin ke hari lain atau duplikasikannya dengan satu ketikan.","f4.t":"Warna & emoji","f4.d":"Berikan acara warna dan emoji sendiri, atau biarkan peraturan melakukannya secara automatik berdasarkan tajuk.","f5.t":"Templat","f5.d":"Simpan acara yang kerap anda rancang dan tambahkannya dengan satu ketikan. Weekdot juga mencadangkan butiran daripada acara terdahulu.","f6.t":"Semua kalendar anda","f6.d":"Tunjukkan, sembunyikan dan kumpulkan kalendar ke dalam set, cipta yang baharu, langgan cuti atau sebarang pautan .ics.","f7.t":"Diselaraskan dengan iCloud","f7.d":"Seting, templat, set, peraturan, warna dan emoji anda sama pada setiap peranti.","f8.t":"Widget & Apple Watch","f8.d":"Widget Hari Ini, Seterusnya dan Minggu, serta app jam untuk melihat hari dan minggu anda sepintas lalu.","f9.t":"Dalam bahasa anda","f9.d":"Weekdot tersedia dalam lebih daripada 30 bahasa dan mengikut bahasa peranti anda.","f10.t":"Cuaca","f10.d":"Secara pilihan, lihat ramalan di atas hari anda.","devices.title":"Pada semua peranti Apple anda","devices.sub":"Satu app untuk iPhone, iPad, Mac dan Apple Watch.","faq.title":"Soalan","q1":"Adakah Weekdot menggantikan akaun kalendar saya?","a1":"Tidak. Weekdot menunjukkan dan mengedit kalendar daripada app Kalendar, jadi semuanya terus diselaraskan melalui iCloud, Google, Outlook atau Exchange.","q2":"Di manakah data saya disimpan?","a2":"Acara anda kekal dalam akaun kalendar anda sendiri. Seting Weekdot sendiri diselaraskan melalui iCloud peribadi anda. Weekdot tiada pelayan yang menyimpan data anda.","q3":"Bahasa apakah yang disokong?","a3":"Lebih daripada 30, termasuk Inggeris, Belanda, Jerman, Perancis, Sepanyol, Itali, Portugis, Cina, Jepun, Korea dan Arab.","q4":"Bolehkah saya menambah cuti?","a4":"Ya. Langgan cuti umum untuk banyak negara dengan satu ketikan, atau tampal sebarang pautan .ics.","privacy.title":"Privasi","privacy.p1":"Weekdot dibina supaya data anda kekal milik anda.","privacy.p2":"Data kalendar: Weekdot hanya membaca dan menulis acara dalam akaun kalendar pada peranti anda (app Kalendar). Acara anda tidak pernah dihantar kepada kami.","privacy.p3":"iCloud: Seting, templat, set kalendar, peraturan, warna dan emoji Weekdot sendiri disimpan dalam iCloud peribadi anda supaya ia diselaraskan antara peranti anda. Kami tidak boleh mengaksesnya.","privacy.p4":"Cuaca (pilihan): apabila anda menghidupkan cuaca, anggaran lokasi anda dihantar ke Open-Meteo untuk mendapatkan ramalan. Weekdot tidak menyimpannya.","privacy.p5":"Tiada akaun, tiada penjejakan, tiada iklan dan tiada analitik.","privacy.p6":"Ada soalan? Hubungi kami melalui halaman sokongan.","privacy.updated":"Kemas kini terakhir: 24 Oktober 2026","support.title":"Bantuan & Sokongan","s1.q":"Weekdot tidak menunjukkan sebarang acara","s1.a":"Benarkan akses kalendar penuh: Seting › Privasi & Keselamatan › Kalendar › Weekdot › Akses Penuh.","s2.q":"Bagaimanakah cara menambah kalendar Google atau Outlook?","s2.a":"Tambah akaun dalam Seting › App › Kalendar › Akaun Kalendar (Mac: app Kalendar › Tambah Akaun). Weekdot menunjukkannya secara automatik.","s3.q":"Bagaimanakah cara menukar bahasa?","s3.a":"Weekdot mengikut bahasa peranti anda. Pada iPhone dan iPad, anda boleh memilih bahasa untuk Weekdot sahaja dalam Seting › App › Weekdot › Bahasa.","s4.q":"Mengapakah ikon app tidak menunjukkan tarikh hari ini?","s4.a":"Hanya app Kalendar Apple sendiri yang boleh menukar ikonnya dengan sendiri. Tambah widget ‘Hari Ini’ Weekdot ke Skrin Utama anda untuk tarikh langsung. Pada Mac, ikon Dock menunjukkan tarikh hari ini semasa Weekdot dibuka.","s5.q":"Adakah warna dan templat saya diselaraskan?","s5.a":"Ya, melalui iCloud. Pastikan anda didaftar masuk ke iCloud dengan Akaun Apple yang sama pada semua peranti anda.","footer.rights":"Hak cipta terpelihara.","lang.label":"Bahasa","mock.Meeting":"Mesyuarat","mock.Lunch":"Makan Tengah Hari","mock.Gym":"Gim","mock.Dentist":"Doktor Gigi","mock.Birthday":"Hari Jadi","mock.Flight":"Penerbangan","mock.Holiday":"Cuti","mock.Day":"Hari","mock.Week":"Minggu","mock.Month":"Bulan","mock.Year":"Tahun","mock.List":"Senarai","mock.Today":"Hari Ini","mock.Calendars":"Kalendar","mock.Color":"Warna","mock.Birthdays":"Hari Lahir","mock.Doctor":"Doktor"},"nb":{"nav.features":"Funksjoner","nav.devices":"Enheter","nav.faq":"Vanlige spørsmål","nav.support":"Kundestøtte","nav.privacy":"Personvern","meta.description":"Weekdot er en rask og vakker kalender for iPhone, iPad, Apple Watch og Mac med dags-, uke-, måneds- og årsvisning.","hero.title":"Uken din på et øyeblikk.","hero.sub":"Weekdot er en rask og vakker kalender for iPhone, iPad, Apple Watch og Mac. Dags-, uke-, måneds- og årsvisning med farger, emoji og maler – oppå kalenderne du allerede bruker.","hero.cta":"Kommer snart til App Store","hero.note":"Fungerer med iCloud, Google, Outlook, Exchange og alle kalendere i Kalender-appen.","features.title":"Alt du planlegger, i én visning","f1.t":"Ukevisning med 7 dager","f1.d":"Se hele uken på én gang. Velg 1 til 7 dager, start uken på hvilken som helst dag, og knip for å zoome timene.","f2.t":"Dag, måned og år","f2.d":"Zoom ut til en måned med navn på hendelser eller et år med de travle dagene dine, og trykk for å hoppe rett inn.","f3.t":"Dra, kopier og lim inn","f3.d":"Flytt hendelser ved å dra, endre lengden, kopier dem til en annen dag eller dupliser dem med ett trykk.","f4.t":"Farger og emoji","f4.d":"Gi hendelser sin egen farge og emoji, eller la regler gjøre det automatisk basert på tittelen.","f5.t":"Maler","f5.d":"Lagre hendelser du ofte planlegger, og legg dem til med ett trykk. Weekdot foreslår også detaljer fra tidligere hendelser.","f6.t":"Alle kalenderne dine","f6.d":"Vis, skjul og grupper kalendere i sett, opprett nye, abonner på helligdager eller en hvilken som helst .ics-lenke.","f7.t":"Synkronisert med iCloud","f7.d":"Innstillingene, malene, settene, reglene, fargene og emojiene dine er de samme på alle enheter.","f8.t":"Widgeter og Apple Watch","f8.d":"Widgetene I dag, Neste og Uke, pluss en klokkeapp for dagen og uken din på et øyeblikk.","f9.t":"På ditt språk","f9.d":"Weekdot snakker mer enn 30 språk og følger språket på enheten din.","f10.t":"Vær","f10.d":"Se værmeldingen over dagene dine hvis du vil.","devices.title":"På alle Apple-enhetene dine","devices.sub":"Én app for iPhone, iPad, Mac og Apple Watch.","faq.title":"Spørsmål","q1":"Erstatter Weekdot kalenderkontoene mine?","a1":"Nei. Weekdot viser og redigerer kalenderne fra Kalender-appen, så alt fortsetter å synkroniseres via iCloud, Google, Outlook eller Exchange.","q2":"Hvor lagres dataene mine?","a2":"Hendelsene dine blir værende i dine egne kalenderkontoer. Weekdots egne innstillinger synkroniseres via din private iCloud. Weekdot har ingen servere som lagrer dataene dine.","q3":"Hvilke språk støttes?","a3":"Mer enn 30, blant annet engelsk, nederlandsk, tysk, fransk, spansk, italiensk, portugisisk, kinesisk, japansk, koreansk og arabisk.","q4":"Kan jeg legge til helligdager?","a4":"Ja. Abonner på helligdager for mange land med ett trykk, eller lim inn en hvilken som helst .ics-lenke.","privacy.title":"Personvern","privacy.p1":"Weekdot er laget for at dataene dine skal forbli dine.","privacy.p2":"Kalenderdata: Weekdot leser og skriver hendelser kun i kalenderkontoene på enheten din (Kalender-appen). Hendelsene dine sendes aldri til oss.","privacy.p3":"iCloud: Weekdots egne innstillinger, maler, kalendersett, regler, farger og emoji lagres i din private iCloud slik at de synkroniseres mellom enhetene dine. Vi har ikke tilgang til dem.","privacy.p4":"Vær (valgfritt): Når du slår på vær, sendes din omtrentlige posisjon til Open-Meteo for å hente en værmelding. Weekdot lagrer den ikke.","privacy.p5":"Ingen kontoer, ingen sporing, ingen reklame og ingen analyse.","privacy.p6":"Spørsmål? Ta kontakt via kundestøttesiden.","privacy.updated":"Sist oppdatert: 24. oktober 2026","support.title":"Hjelp og kundestøtte","s1.q":"Weekdot viser ingen hendelser","s1.a":"Gi full kalendertilgang: Innstillinger › Personvern og sikkerhet › Kalendere › Weekdot › Full tilgang.","s2.q":"Hvordan legger jeg til en Google- eller Outlook-kalender?","s2.a":"Legg til kontoen i Innstillinger › Apper › Kalender › Kalenderkontoer (Mac: Kalender-appen › Legg til konto). Weekdot viser den automatisk.","s3.q":"Hvordan endrer jeg språket?","s3.a":"Weekdot følger språket på enheten din. På iPhone og iPad kan du velge et språk bare for Weekdot i Innstillinger › Apper › Weekdot › Språk.","s4.q":"Hvorfor viser ikke appsymbolet dagens dato?","s4.a":"Bare Apples egen Kalender-app kan endre symbolet sitt selv. Legg til Weekdot-widgeten «I dag» på Hjem-skjermen for en oppdatert dato. På Mac viser symbolet i Dock dagens dato mens Weekdot er åpen.","s5.q":"Synkroniseres fargene og malene mine?","s5.a":"Ja, via iCloud. Sørg for at du er logget på iCloud med den samme Apple-kontoen på alle enhetene dine.","footer.rights":"Alle rettigheter forbeholdt.","lang.label":"Språk","mock.Meeting":"Møte","mock.Lunch":"Lunsj","mock.Gym":"Trening","mock.Dentist":"Tannlege","mock.Birthday":"Bursdag","mock.Flight":"Fly","mock.Holiday":"Ferie","mock.Day":"Dag","mock.Week":"Uke","mock.Month":"Måned","mock.Year":"År","mock.List":"Liste","mock.Today":"I dag","mock.Calendars":"Kalendere","mock.Color":"Farge","mock.Birthdays":"Bursdager","mock.Doctor":"Lege"},"nl":{"nav.features":"Functies","nav.devices":"Apparaten","nav.faq":"Veelgestelde vragen","nav.support":"Ondersteuning","nav.privacy":"Privacy","meta.description":"Weekdot is een snelle, mooie agenda voor iPhone, iPad, Apple Watch en Mac met dag-, week-, maand- en jaarweergave.","hero.title":"Je week in één oogopslag.","hero.sub":"Weekdot is een snelle, mooie agenda voor iPhone, iPad, Apple Watch en Mac. Dag-, week-, maand- en jaarweergave, met kleuren, emoji en sjablonen — bovenop de agenda's die je al gebruikt.","hero.cta":"Binnenkort in de App Store","hero.note":"Werkt met iCloud, Google, Outlook, Exchange en elke agenda in de Agenda-app.","features.title":"Alles wat je plant, in één overzicht","f1.t":"Weekweergave met 7 dagen","f1.d":"Zie je hele week in één keer. Kies 1 tot 7 dagen, laat de week op elke gewenste dag beginnen en knijp om in te zoomen op de uren.","f2.t":"Dag, maand en jaar","f2.d":"Zoom uit naar een maand met namen van activiteiten of een jaar met je drukke dagen, en tik om er meteen naartoe te gaan.","f3.t":"Slepen, kopiëren en plakken","f3.d":"Verplaats activiteiten door te slepen, wijzig hun duur, kopieer ze naar een andere dag of dupliceer ze met één tik.","f4.t":"Kleuren en emoji","f4.d":"Geef activiteiten een eigen kleur en emoji, of laat regels dat automatisch doen op basis van de titel.","f5.t":"Sjablonen","f5.d":"Bewaar activiteiten die je vaak plant en voeg ze met één tik toe. Weekdot stelt ook details voor op basis van eerdere activiteiten.","f6.t":"Al je agenda's","f6.d":"Toon, verberg en groepeer agenda's in sets, maak nieuwe aan, abonneer je op feestdagen of op elke .ics-link.","f7.t":"Gesynchroniseerd met iCloud","f7.d":"Je instellingen, sjablonen, sets, regels, kleuren en emoji zijn op elk apparaat hetzelfde.","f8.t":"Widgets en Apple Watch","f8.d":"Widgets voor Vandaag, Hierna en Week, plus een watch-app voor je dag en week in één oogopslag.","f9.t":"In jouw taal","f9.d":"Weekdot spreekt meer dan 30 talen en volgt de taal van je apparaat.","f10.t":"Weer","f10.d":"Zie desgewenst de weersverwachting boven je dagen.","devices.title":"Op al je Apple-apparaten","devices.sub":"Eén app voor iPhone, iPad, Mac en Apple Watch.","faq.title":"Vragen","q1":"Vervangt Weekdot mijn agenda-accounts?","a1":"Nee. Weekdot toont en wijzigt de agenda's uit de Agenda-app, dus alles blijft synchroniseren via iCloud, Google, Outlook of Exchange.","q2":"Waar worden mijn gegevens bewaard?","a2":"Je activiteiten blijven in je eigen agenda-accounts. De eigen instellingen van Weekdot synchroniseren via je privé-iCloud. Weekdot heeft geen servers die je gegevens opslaan.","q3":"Welke talen worden ondersteund?","a3":"Meer dan 30, waaronder Engels, Nederlands, Duits, Frans, Spaans, Italiaans, Portugees, Chinees, Japans, Koreaans en Arabisch.","q4":"Kan ik feestdagen toevoegen?","a4":"Ja. Abonneer je met één tik op feestdagen van veel landen, of plak een .ics-link.","privacy.title":"Privacy","privacy.p1":"Weekdot is gemaakt om jouw gegevens van jou te laten.","privacy.p2":"Agendagegevens: Weekdot leest en schrijft activiteiten alleen in de agenda-accounts op je apparaat (de Agenda-app). Je activiteiten worden nooit naar ons verstuurd.","privacy.p3":"iCloud: de eigen instellingen, sjablonen, agendasets, regels, kleuren en emoji van Weekdot worden in je privé-iCloud bewaard, zodat ze tussen je apparaten synchroniseren. Wij hebben er geen toegang toe.","privacy.p4":"Weer (optioneel): als je het weer aanzet, wordt je geschatte locatie naar Open-Meteo gestuurd om een weersverwachting op te halen. Weekdot bewaart deze niet.","privacy.p5":"Geen accounts, geen tracking, geen advertenties en geen analyses.","privacy.p6":"Vragen? Neem contact op via de ondersteuningspagina.","privacy.updated":"Laatst bijgewerkt: 24 oktober 2026","support.title":"Hulp en ondersteuning","s1.q":"Weekdot toont geen activiteiten","s1.a":"Geef volledige toegang tot je agenda's: Instellingen › Privacy en beveiliging › Agenda's › Weekdot › Volledige toegang.","s2.q":"Hoe voeg ik een Google- of Outlook-agenda toe?","s2.a":"Voeg het account toe in Instellingen › Apps › Agenda › Agenda-accounts (Mac: Agenda-app › Voeg account toe). Weekdot toont het automatisch.","s3.q":"Hoe wijzig ik de taal?","s3.a":"Weekdot volgt de taal van je apparaat. Op iPhone en iPad kun je alleen voor Weekdot een taal kiezen in Instellingen › Apps › Weekdot › Taal.","s4.q":"Waarom toont het appsymbool niet de datum van vandaag?","s4.a":"Alleen Apples eigen Agenda-app kan zelf zijn symbool wijzigen. Zet de Weekdot-widget ‘Vandaag’ op je beginscherm voor een actuele datum. Op de Mac toont het Dock-symbool de datum van vandaag zolang Weekdot open is.","s5.q":"Worden mijn kleuren en sjablonen gesynchroniseerd?","s5.a":"Ja, via iCloud. Zorg dat je op al je apparaten met dezelfde Apple Account bij iCloud bent ingelogd.","footer.rights":"Alle rechten voorbehouden.","lang.label":"Taal","mock.Meeting":"Vergadering","mock.Lunch":"Lunch","mock.Gym":"Sportschool","mock.Dentist":"Tandarts","mock.Birthday":"Verjaardag","mock.Flight":"Vlucht","mock.Holiday":"Vakantie","mock.Day":"Dag","mock.Week":"Week","mock.Month":"Maand","mock.Year":"Jaar","mock.List":"Lijst","mock.Today":"Vandaag","mock.Calendars":"Agenda's","mock.Color":"Kleur","mock.Birthdays":"Verjaardagen","mock.Doctor":"Huisarts"},"pl":{"nav.features":"Funkcje","nav.devices":"Urządzenia","nav.faq":"FAQ","nav.support":"Wsparcie","nav.privacy":"Prywatność","meta.description":"Weekdot to szybki i piękny kalendarz na iPhone’a, iPada, Apple Watch i Maca z widokami dnia, tygodnia, miesiąca i roku.","hero.title":"Twój tydzień w jednym rzucie oka.","hero.sub":"Weekdot to szybki i piękny kalendarz na iPhone’a, iPada, Apple Watch i Maca. Widoki dnia, tygodnia, miesiąca i roku z kolorami, emoji i szablonami — na bazie kalendarzy, których już używasz.","hero.cta":"Wkrótce w App Store","hero.note":"Działa z iCloud, Google, Outlook, Exchange i każdym kalendarzem w aplikacji Kalendarz.","features.title":"Wszystko, co planujesz, w jednym widoku","f1.t":"Widok tygodnia z 7 dniami","f1.d":"Zobacz cały tydzień naraz. Wybierz od 1 do 7 dni, zacznij tydzień od dowolnego dnia i zsuwaj palce, aby powiększać godziny.","f2.t":"Dzień, miesiąc i rok","f2.d":"Pomniejsz do miesiąca z nazwami wydarzeń lub roku z zajętymi dniami i stuknij, aby od razu przejść dalej.","f3.t":"Przeciągaj, kopiuj i wklejaj","f3.d":"Przenoś wydarzenia przeciąganiem, zmieniaj ich długość, kopiuj je na inny dzień lub duplikuj jednym stuknięciem.","f4.t":"Kolory i emoji","f4.d":"Nadaj wydarzeniom własny kolor i emoji albo pozwól regułom robić to automatycznie na podstawie tytułu.","f5.t":"Szablony","f5.d":"Zachowuj często planowane wydarzenia i dodawaj je jednym stuknięciem. Weekdot sugeruje też szczegóły z wcześniejszych wydarzeń.","f6.t":"Wszystkie Twoje kalendarze","f6.d":"Pokazuj, ukrywaj i grupuj kalendarze w zestawy, twórz nowe, subskrybuj święta lub dowolne łącze .ics.","f7.t":"Synchronizacja z iCloud","f7.d":"Twoje ustawienia, szablony, zestawy, reguły, kolory i emoji są takie same na każdym urządzeniu.","f8.t":"Widżety i Apple Watch","f8.d":"Widżety Dzisiaj, Następne i Tydzień oraz aplikacja na zegarek z Twoim dniem i tygodniem w jednym rzucie oka.","f9.t":"W Twoim języku","f9.d":"Weekdot mówi w ponad 30 językach i używa języka Twojego urządzenia.","f10.t":"Pogoda","f10.d":"Opcjonalnie wyświetlaj prognozę nad swoimi dniami.","devices.title":"Na wszystkich Twoich urządzeniach Apple","devices.sub":"Jedna aplikacja na iPhone’a, iPada, Maca i Apple Watch.","faq.title":"Pytania","q1":"Czy Weekdot zastępuje moje konta kalendarzy?","a1":"Nie. Weekdot pokazuje i edytuje kalendarze z aplikacji Kalendarz, więc wszystko nadal synchronizuje się przez iCloud, Google, Outlook lub Exchange.","q2":"Gdzie są przechowywane moje dane?","a2":"Twoje wydarzenia pozostają na Twoich własnych kontach kalendarzy. Własne ustawienia Weekdot są synchronizowane przez Twój prywatny iCloud. Weekdot nie ma serwerów przechowujących Twoje dane.","q3":"Jakie języki są obsługiwane?","a3":"Ponad 30, w tym angielski, niderlandzki, niemiecki, francuski, hiszpański, włoski, portugalski, chiński, japoński, koreański i arabski.","q4":"Czy mogę dodać święta?","a4":"Tak. Subskrybuj dni wolne od pracy w wielu krajach jednym stuknięciem lub wklej dowolne łącze .ics.","privacy.title":"Prywatność","privacy.p1":"Weekdot jest stworzony tak, aby Twoje dane pozostały Twoje.","privacy.p2":"Dane kalendarza: Weekdot odczytuje i zapisuje wydarzenia wyłącznie na kontach kalendarzy na Twoim urządzeniu (aplikacja Kalendarz). Twoje wydarzenia nigdy nie są do nas wysyłane.","privacy.p3":"iCloud: własne ustawienia, szablony, zestawy kalendarzy, reguły, kolory i emoji Weekdot są przechowywane w Twoim prywatnym iCloud, aby synchronizowały się między urządzeniami. Nie mamy do nich dostępu.","privacy.p4":"Pogoda (opcjonalnie): gdy włączysz pogodę, Twoja przybliżona lokalizacja jest wysyłana do Open-Meteo w celu pobrania prognozy. Weekdot jej nie przechowuje.","privacy.p5":"Bez kont, bez śledzenia, bez reklam i bez analityki.","privacy.p6":"Masz pytania? Skontaktuj się z nami przez stronę wsparcia.","privacy.updated":"Ostatnia aktualizacja: 24 października 2026","support.title":"Pomoc i wsparcie","s1.q":"Weekdot nie pokazuje żadnych wydarzeń","s1.a":"Zezwól na pełny dostęp do kalendarzy: Ustawienia › Prywatność i ochrona › Kalendarze › Weekdot › Pełny dostęp.","s2.q":"Jak dodać kalendarz Google lub Outlook?","s2.a":"Dodaj konto w Ustawienia › Aplikacje › Kalendarz › Konta kalendarzy (Mac: aplikacja Kalendarz › Dodaj konto). Weekdot pokaże je automatycznie.","s3.q":"Jak zmienić język?","s3.a":"Weekdot używa języka Twojego urządzenia. Na iPhonie i iPadzie możesz wybrać język tylko dla Weekdot w Ustawienia › Aplikacje › Weekdot › Język.","s4.q":"Dlaczego ikona aplikacji nie pokazuje dzisiejszej daty?","s4.a":"Tylko własna aplikacja Kalendarz Apple może sama zmieniać swoją ikonę. Dodaj widżet Weekdot „Dzisiaj” do ekranu początkowego, aby mieć aktualną datę. Na Macu ikona w Docku pokazuje dzisiejszą datę, gdy Weekdot jest otwarty.","s5.q":"Czy moje kolory i szablony się synchronizują?","s5.a":"Tak, przez iCloud. Upewnij się, że na wszystkich urządzeniach jesteś zalogowany do iCloud przy użyciu tego samego konta Apple.","footer.rights":"Wszelkie prawa zastrzeżone.","lang.label":"Język","mock.Meeting":"Spotkanie","mock.Lunch":"Lunch","mock.Gym":"Siłownia","mock.Dentist":"Dentysta","mock.Birthday":"Urodziny","mock.Flight":"Lot","mock.Holiday":"Urlop","mock.Day":"Dzień","mock.Week":"Tydzień","mock.Month":"Miesiąc","mock.Year":"Rok","mock.List":"Lista","mock.Today":"Dzisiaj","mock.Calendars":"Kalendarze","mock.Color":"Kolor","mock.Birthdays":"Urodziny","mock.Doctor":"Lekarz"},"pt-BR":{"nav.features":"Recursos","nav.devices":"Dispositivos","nav.faq":"Perguntas","nav.support":"Suporte","nav.privacy":"Privacidade","meta.description":"O Weekdot é um calendário rápido e bonito para iPhone, iPad, Apple Watch e Mac, com visualizações de dia, semana, mês e ano.","hero.title":"Sua semana num relance.","hero.sub":"O Weekdot é um calendário rápido e bonito para iPhone, iPad, Apple Watch e Mac. Visualizações de dia, semana, mês e ano, com cores, emojis e modelos — sobre os calendários que você já usa.","hero.cta":"Em breve na App Store","hero.note":"Funciona com iCloud, Google, Outlook, Exchange e todos os calendários do app Calendário.","features.title":"Tudo o que você planeja, em uma só tela","f1.t":"Visualização de semana com 7 dias","f1.d":"Veja a semana inteira de uma vez. Escolha de 1 a 7 dias, comece a semana em qualquer dia e faça o gesto de pinça para ampliar as horas.","f2.t":"Dia, mês e ano","f2.d":"Afaste para ver um mês com os nomes dos eventos ou um ano com seus dias ocupados, e toque para entrar direto.","f3.t":"Arrastar, copiar e colar","f3.d":"Mova eventos arrastando, altere a duração, copie-os para outro dia ou duplique-os com um toque.","f4.t":"Cores e emojis","f4.d":"Dê a cada evento sua própria cor e emoji, ou deixe que regras façam isso automaticamente com base no título.","f5.t":"Modelos","f5.d":"Salve eventos que você planeja com frequência e adicione-os com um toque. O Weekdot também sugere detalhes de eventos anteriores.","f6.t":"Todos os seus calendários","f6.d":"Mostre, oculte e agrupe calendários em conjuntos, crie novos, assine feriados ou qualquer link .ics.","f7.t":"Sincronizado com o iCloud","f7.d":"Seus ajustes, modelos, conjuntos, regras, cores e emojis são os mesmos em todos os dispositivos.","f8.t":"Widgets e Apple Watch","f8.d":"Widgets Hoje, A Seguir e Semana, além de um app para o relógio com seu dia e sua semana num relance.","f9.t":"No seu idioma","f9.d":"O Weekdot fala mais de 30 idiomas e segue o idioma do seu dispositivo.","f10.t":"Clima","f10.d":"Se quiser, veja a previsão do tempo acima dos seus dias.","devices.title":"Em todos os seus dispositivos Apple","devices.sub":"Um app para iPhone, iPad, Mac e Apple Watch.","faq.title":"Perguntas","q1":"O Weekdot substitui minhas contas de calendário?","a1":"Não. O Weekdot mostra e edita os calendários do app Calendário, então tudo continua sincronizando pelo iCloud, Google, Outlook ou Exchange.","q2":"Onde meus dados são armazenados?","a2":"Seus eventos ficam nas suas próprias contas de calendário. Os ajustes do Weekdot são sincronizados pelo seu iCloud privado. O Weekdot não tem servidores que armazenam seus dados.","q3":"Quais idiomas são compatíveis?","a3":"Mais de 30, incluindo inglês, holandês, alemão, francês, espanhol, italiano, português, chinês, japonês, coreano e árabe.","q4":"Posso adicionar feriados?","a4":"Sim. Assine os feriados de vários países com um toque ou cole qualquer link .ics.","privacy.title":"Privacidade","privacy.p1":"O Weekdot foi criado para que seus dados continuem sendo seus.","privacy.p2":"Dados de calendário: o Weekdot lê e grava eventos apenas nas contas de calendário do seu dispositivo (o app Calendário). Seus eventos nunca são enviados para nós.","privacy.p3":"iCloud: os ajustes, modelos, conjuntos de calendários, regras, cores e emojis do Weekdot são armazenados no seu iCloud privado para sincronizar entre seus dispositivos. Nós não temos acesso a eles.","privacy.p4":"Clima (opcional): quando você ativa o clima, sua localização aproximada é enviada ao Open-Meteo para obter a previsão. O Weekdot não a armazena.","privacy.p5":"Sem contas, sem rastreamento, sem anúncios e sem análises.","privacy.p6":"Dúvidas? Entre em contato pela página de suporte.","privacy.updated":"Última atualização: 24 de outubro de 2026","support.title":"Ajuda e Suporte","s1.q":"O Weekdot não mostra nenhum evento","s1.a":"Permita o acesso total aos calendários: Ajustes › Privacidade e Segurança › Calendários › Weekdot › Acesso Total.","s2.q":"Como adiciono um calendário do Google ou Outlook?","s2.a":"Adicione a conta em Ajustes › Apps › Calendário › Contas de Calendário (Mac: app Calendário › Adicionar Conta). O Weekdot a mostra automaticamente.","s3.q":"Como altero o idioma?","s3.a":"O Weekdot segue o idioma do seu dispositivo. No iPhone e iPad, você pode escolher um idioma só para o Weekdot em Ajustes › Apps › Weekdot › Idioma.","s4.q":"Por que o ícone do app não mostra a data de hoje?","s4.a":"Somente o app Calendário da própria Apple pode alterar o seu ícone sozinho. Adicione o widget ‘Hoje’ do Weekdot à Tela de Início para ver a data ao vivo. No Mac, o ícone no Dock mostra a data de hoje enquanto o Weekdot está aberto.","s5.q":"Minhas cores e modelos são sincronizados?","s5.a":"Sim, pelo iCloud. Verifique se você iniciou sessão no iCloud com a mesma Conta Apple em todos os seus dispositivos.","footer.rights":"Todos os direitos reservados.","lang.label":"Idioma","mock.Meeting":"Reunião","mock.Lunch":"Almoço","mock.Gym":"Academia","mock.Dentist":"Dentista","mock.Birthday":"Aniversário","mock.Flight":"Voo","mock.Holiday":"Férias","mock.Day":"Dia","mock.Week":"Semana","mock.Month":"Mês","mock.Year":"Ano","mock.List":"Lista","mock.Today":"Hoje","mock.Calendars":"Calendários","mock.Color":"Cor","mock.Birthdays":"Aniversários","mock.Doctor":"Médico"},"pt-PT":{"nav.features":"Funcionalidades","nav.devices":"Dispositivos","nav.faq":"FAQ","nav.support":"Suporte","nav.privacy":"Privacidade","meta.description":"O Weekdot é um calendário rápido e bonito para iPhone, iPad, Apple Watch e Mac, com vistas de dia, semana, mês e ano.","hero.title":"A sua semana num relance.","hero.sub":"O Weekdot é um calendário rápido e bonito para iPhone, iPad, Apple Watch e Mac. Vistas de dia, semana, mês e ano, com cores, emoji e modelos — por cima dos calendários que já usa.","hero.cta":"Brevemente na App Store","hero.note":"Funciona com iCloud, Google, Outlook, Exchange e qualquer calendário da app Calendário.","features.title":"Tudo o que planeia, numa só vista","f1.t":"Vista Semana com 7 dias","f1.d":"Veja a semana inteira de uma vez. Escolha de 1 a 7 dias, comece a semana em qualquer dia e junte os dedos para ampliar as horas.","f2.t":"Dia, mês e ano","f2.d":"Afaste para um mês com os nomes dos eventos ou um ano com os seus dias ocupados, e toque para ir diretamente.","f3.t":"Arrastar, copiar e colar","f3.d":"Mova eventos arrastando-os, altere a sua duração, copie-os para outro dia ou duplique-os com um toque.","f4.t":"Cores e emoji","f4.d":"Dê aos eventos a sua própria cor e emoji, ou deixe as regras fazê-lo automaticamente com base no título.","f5.t":"Modelos","f5.d":"Guarde os eventos que planeia com frequência e adicione-os com um toque. O Weekdot também sugere detalhes a partir de eventos anteriores.","f6.t":"Todos os seus calendários","f6.d":"Mostre, oculte e agrupe calendários em conjuntos, crie novos e subscreva feriados ou qualquer ligação .ics.","f7.t":"Sincronizado com a iCloud","f7.d":"As suas definições, modelos, conjuntos, regras, cores e emoji são iguais em todos os dispositivos.","f8.t":"Widgets e Apple Watch","f8.d":"Widgets Hoje, A seguir e Semana, além de uma app para o relógio com o seu dia e a sua semana num relance.","f9.t":"No seu idioma","f9.d":"O Weekdot fala mais de 30 idiomas e segue o idioma do seu dispositivo.","f10.t":"Meteorologia","f10.d":"Opcionalmente, veja a previsão por cima dos seus dias.","devices.title":"Em todos os seus dispositivos Apple","devices.sub":"Uma só app para iPhone, iPad, Mac e Apple Watch.","faq.title":"Perguntas","q1":"O Weekdot substitui as minhas contas de calendário?","a1":"Não. O Weekdot mostra e edita os calendários da app Calendário, por isso tudo continua a sincronizar através da iCloud, Google, Outlook ou Exchange.","q2":"Onde são guardados os meus dados?","a2":"Os seus eventos ficam nas suas próprias contas de calendário. As definições próprias do Weekdot sincronizam através da sua iCloud privada. O Weekdot não tem servidores que guardem os seus dados.","q3":"Que idiomas são suportados?","a3":"Mais de 30, incluindo inglês, neerlandês, alemão, francês, espanhol, italiano, português, chinês, japonês, coreano e árabe.","q4":"Posso adicionar feriados?","a4":"Sim. Subscreva os feriados de muitos países com um toque, ou cole qualquer ligação .ics.","privacy.title":"Privacidade","privacy.p1":"O Weekdot foi criado para que os seus dados continuem a ser seus.","privacy.p2":"Dados do calendário: o Weekdot lê e escreve eventos apenas nas contas de calendário do seu dispositivo (a app Calendário). Os seus eventos nunca nos são enviados.","privacy.p3":"iCloud: as definições, modelos, conjuntos de calendários, regras, cores e emoji próprios do Weekdot são guardados na sua iCloud privada para sincronizarem entre os seus dispositivos. Não temos acesso a eles.","privacy.p4":"Meteorologia (opcional): quando ativa a meteorologia, a sua localização aproximada é enviada para a Open-Meteo para obter uma previsão. O Weekdot não a guarda.","privacy.p5":"Sem contas, sem rastreio, sem anúncios e sem análises.","privacy.p6":"Dúvidas? Contacte-nos através da página de suporte.","privacy.updated":"Última atualização: 24 de outubro de 2026","support.title":"Ajuda e suporte","s1.q":"O Weekdot não mostra eventos","s1.a":"Permita o acesso total ao calendário: Definições › Privacidade e segurança › Calendários › Weekdot › Acesso total.","s2.q":"Como adiciono um calendário Google ou Outlook?","s2.a":"Adicione a conta em Definições › Apps › Calendário › Contas de calendário (Mac: app Calendário › Adicionar conta). O Weekdot mostra-a automaticamente.","s3.q":"Como altero o idioma?","s3.a":"O Weekdot segue o idioma do seu dispositivo. No iPhone e iPad pode escolher um idioma apenas para o Weekdot em Definições › Apps › Weekdot › Idioma.","s4.q":"Porque é que o ícone da app não mostra a data de hoje?","s4.a":"Só a app Calendário da Apple consegue alterar o próprio ícone. Adicione o widget “Hoje” do Weekdot ao ecrã principal para ver a data atual. No Mac, o ícone na Dock mostra a data de hoje enquanto o Weekdot está aberto.","s5.q":"As minhas cores e modelos sincronizam?","s5.a":"Sim, através da iCloud. Certifique-se de que tem sessão iniciada na iCloud com a mesma Conta Apple em todos os seus dispositivos.","footer.rights":"Todos os direitos reservados.","lang.label":"Idioma","mock.Meeting":"Reunião","mock.Lunch":"Almoço","mock.Gym":"Ginásio","mock.Dentist":"Dentista","mock.Birthday":"Aniversário","mock.Flight":"Voo","mock.Holiday":"Férias","mock.Day":"Dia","mock.Week":"Semana","mock.Month":"Mês","mock.Year":"Ano","mock.List":"Lista","mock.Today":"Hoje","mock.Calendars":"Calendários","mock.Color":"Cor","mock.Birthdays":"Aniversários","mock.Doctor":"Médico"},"ro":{"nav.features":"Funcționalități","nav.devices":"Dispozitive","nav.faq":"Întrebări frecvente","nav.support":"Asistență","nav.privacy":"Confidențialitate","meta.description":"Weekdot este un calendar rapid și frumos pentru iPhone, iPad, Apple Watch și Mac, cu vizualizări zi, săptămână, lună și an.","hero.title":"Săptămâna dvs. dintr-o privire.","hero.sub":"Weekdot este un calendar rapid și frumos pentru iPhone, iPad, Apple Watch și Mac. Vizualizări zi, săptămână, lună și an, cu culori, emoji și șabloane – peste calendarele pe care le folosiți deja.","hero.cta":"În curând în App Store","hero.note":"Funcționează cu iCloud, Google, Outlook, Exchange și orice calendar din aplicația Calendar.","features.title":"Tot ce planificați, într-o singură vizualizare","f1.t":"Vizualizare săptămână cu 7 zile","f1.d":"Vedeți toată săptămâna dintr-odată. Alegeți între 1 și 7 zile, începeți săptămâna în orice zi și ciupiți pentru a mări orele.","f2.t":"Zi, lună și an","f2.d":"Micșorați la o lună cu numele evenimentelor sau la un an cu zilele aglomerate și apăsați pentru a intra direct.","f3.t":"Tragere, copiere și lipire","f3.d":"Mutați evenimentele prin tragere, schimbați-le durata, copiați-le în altă zi sau duplicați-le cu o singură apăsare.","f4.t":"Culori și emoji","f4.d":"Dați evenimentelor propria culoare și propriul emoji sau lăsați regulile să o facă automat pe baza titlului.","f5.t":"Șabloane","f5.d":"Salvați evenimentele pe care le planificați des și adăugați-le cu o singură apăsare. Weekdot sugerează și detalii din evenimente anterioare.","f6.t":"Toate calendarele dvs.","f6.d":"Afișați, ascundeți și grupați calendarele în seturi, creați altele noi, abonați-vă la sărbători sau la orice link .ics.","f7.t":"Sincronizat cu iCloud","f7.d":"Configurările, șabloanele, seturile, regulile, culorile și emoji-urile dvs. sunt aceleași pe fiecare dispozitiv.","f8.t":"Widgeturi și Apple Watch","f8.d":"Widgeturile Azi, Urmează și Săptămână, plus o aplicație pentru ceas cu ziua și săptămâna dintr-o privire.","f9.t":"În limba dvs.","f9.d":"Weekdot vorbește peste 30 de limbi și folosește limba dispozitivului dvs.","f10.t":"Vreme","f10.d":"Opțional, vedeți prognoza deasupra zilelor dvs.","devices.title":"Pe toate dispozitivele Apple","devices.sub":"O singură aplicație pentru iPhone, iPad, Mac și Apple Watch.","faq.title":"Întrebări","q1":"Înlocuiește Weekdot conturile mele de calendar?","a1":"Nu. Weekdot afișează și editează calendarele din aplicația Calendar, astfel încât totul continuă să se sincronizeze prin iCloud, Google, Outlook sau Exchange.","q2":"Unde sunt stocate datele mele?","a2":"Evenimentele dvs. rămân în propriile conturi de calendar. Configurările proprii Weekdot se sincronizează prin iCloud-ul dvs. privat. Weekdot nu are servere care să vă stocheze datele.","q3":"Ce limbi sunt acceptate?","a3":"Peste 30, inclusiv engleză, neerlandeză, germană, franceză, spaniolă, italiană, portugheză, chineză, japoneză, coreeană și arabă.","q4":"Pot adăuga sărbători?","a4":"Da. Abonați-vă cu o singură apăsare la sărbătorile legale din multe țări sau lipiți orice link .ics.","privacy.title":"Confidențialitate","privacy.p1":"Weekdot este creat astfel încât datele dvs. să rămână ale dvs.","privacy.p2":"Date de calendar: Weekdot citește și scrie evenimente doar în conturile de calendar de pe dispozitivul dvs. (aplicația Calendar). Evenimentele dvs. nu ne sunt trimise niciodată.","privacy.p3":"iCloud: configurările, șabloanele, seturile de calendare, regulile, culorile și emoji-urile proprii Weekdot sunt stocate în iCloud-ul dvs. privat, pentru a se sincroniza între dispozitive. Noi nu le putem accesa.","privacy.p4":"Vreme (opțional): când activați vremea, localizarea dvs. aproximativă este trimisă la Open-Meteo pentru a obține o prognoză. Weekdot nu o stochează.","privacy.p5":"Fără conturi, fără urmărire, fără reclame și fără analiză.","privacy.p6":"Întrebări? Contactați-ne prin pagina de asistență.","privacy.updated":"Ultima actualizare: 24 octombrie 2026","support.title":"Ajutor și asistență","s1.q":"Weekdot nu afișează niciun eveniment","s1.a":"Permiteți accesul complet la calendar: Configurări › Confidențialitate și securitate › Calendare › Weekdot › Acces complet.","s2.q":"Cum adaug un calendar Google sau Outlook?","s2.a":"Adăugați contul în Configurări › Aplicații › Calendar › Conturi Calendar (Mac: aplicația Calendar › Adaugă cont). Weekdot îl afișează automat.","s3.q":"Cum schimb limba?","s3.a":"Weekdot folosește limba dispozitivului dvs. Pe iPhone și iPad puteți alege o limbă doar pentru Weekdot în Configurări › Aplicații › Weekdot › Limbă.","s4.q":"De ce pictograma aplicației nu arată data de azi?","s4.a":"Doar aplicația Calendar a Apple își poate schimba singură pictograma. Adăugați widgetul Weekdot „Azi” pe ecranul principal pentru data actuală. Pe Mac, pictograma din Dock arată data de azi cât timp Weekdot este deschis.","s5.q":"Se sincronizează culorile și șabloanele mele?","s5.a":"Da, prin iCloud. Asigurați-vă că sunteți autentificat în iCloud cu același cont Apple pe toate dispozitivele.","footer.rights":"Toate drepturile rezervate.","lang.label":"Limbă","mock.Meeting":"Ședință","mock.Lunch":"Prânz","mock.Gym":"Sală","mock.Dentist":"Dentist","mock.Birthday":"Aniversare","mock.Flight":"Zbor","mock.Holiday":"Vacanță","mock.Day":"Zi","mock.Week":"Săptămână","mock.Month":"Lună","mock.Year":"An","mock.List":"Listă","mock.Today":"Azi","mock.Calendars":"Calendare","mock.Color":"Culoare","mock.Birthdays":"Zile de naștere","mock.Doctor":"Doctor"},"ru":{"nav.features":"Функции","nav.devices":"Устройства","nav.faq":"Вопросы","nav.support":"Поддержка","nav.privacy":"Конфиденциальность","meta.description":"Weekdot — быстрый и красивый календарь для iPhone, iPad, Apple Watch и Mac с режимами дня, недели, месяца и года.","hero.title":"Ваша неделя с первого взгляда.","hero.sub":"Weekdot — быстрый и красивый календарь для iPhone, iPad, Apple Watch и Mac. Режимы дня, недели, месяца и года, с цветами, эмодзи и шаблонами — поверх календарей, которыми вы уже пользуетесь.","hero.cta":"Скоро в App Store","hero.note":"Работает с iCloud, Google, Outlook, Exchange и любым календарем в приложении «Календарь».","features.title":"Все ваши планы в одном виде","f1.t":"Неделя из 7 дней","f1.d":"Вся неделя сразу. Выберите от 1 до 7 дней, начинайте неделю с любого дня и масштабируйте часы жестом.","f2.t":"День, месяц и год","f2.d":"Уменьшите масштаб до месяца с названиями событий или до года с загруженными днями и коснитесь, чтобы сразу перейти.","f3.t":"Перетаскивание, копирование и вставка","f3.d":"Перемещайте события перетаскиванием, меняйте их длительность, копируйте на другой день или дублируйте одним касанием.","f4.t":"Цвета и эмодзи","f4.d":"Задайте событиям свой цвет и эмодзи или позвольте правилам делать это автоматически по названию.","f5.t":"Шаблоны","f5.d":"Сохраняйте частые события и добавляйте их одним касанием. Weekdot также предлагает детали из прошлых событий.","f6.t":"Все ваши календари","f6.d":"Показывайте, скрывайте и объединяйте календари в наборы, создавайте новые, подписывайтесь на праздники или любую ссылку .ics.","f7.t":"Синхронизация с iCloud","f7.d":"Ваши настройки, шаблоны, наборы, правила, цвета и эмодзи одинаковы на всех устройствах.","f8.t":"Виджеты и Apple Watch","f8.d":"Виджеты «Сегодня», «Далее» и «Неделя», а также приложение для часов, чтобы видеть день и неделю с первого взгляда.","f9.t":"На вашем языке","f9.d":"Weekdot говорит более чем на 30 языках и использует язык вашего устройства.","f10.t":"Погода","f10.d":"При желании показывайте прогноз над днями.","devices.title":"На всех ваших устройствах Apple","devices.sub":"Одно приложение для iPhone, iPad, Mac и Apple Watch.","faq.title":"Вопросы","q1":"Заменяет ли Weekdot мои учетные записи календарей?","a1":"Нет. Weekdot показывает и изменяет календари из приложения «Календарь», поэтому все продолжает синхронизироваться через iCloud, Google, Outlook или Exchange.","q2":"Где хранятся мои данные?","a2":"Ваши события остаются в ваших собственных учетных записях календарей. Собственные настройки Weekdot синхронизируются через ваш личный iCloud. У Weekdot нет серверов, на которых хранятся ваши данные.","q3":"Какие языки поддерживаются?","a3":"Более 30, включая английский, нидерландский, немецкий, французский, испанский, итальянский, португальский, китайский, японский, корейский и арабский.","q4":"Можно ли добавить праздники?","a4":"Да. Подпишитесь на государственные праздники многих стран одним касанием или вставьте любую ссылку .ics.","privacy.title":"Конфиденциальность","privacy.p1":"Weekdot создан, чтобы ваши данные оставались вашими.","privacy.p2":"Данные календаря: Weekdot читает и записывает события только в учетных записях календарей на вашем устройстве (приложение «Календарь»). Ваши события никогда не отправляются нам.","privacy.p3":"iCloud: собственные настройки Weekdot, шаблоны, наборы календарей, правила, цвета и эмодзи хранятся в вашем личном iCloud для синхронизации между устройствами. У нас нет к ним доступа.","privacy.p4":"Погода (по желанию): если вы включите погоду, ваша приблизительная геопозиция отправляется в Open-Meteo для получения прогноза. Weekdot ее не хранит.","privacy.p5":"Без учетных записей, отслеживания, рекламы и аналитики.","privacy.p6":"Есть вопросы? Свяжитесь с нами через страницу поддержки.","privacy.updated":"Последнее обновление: 24 октября 2026 г.","support.title":"Помощь и поддержка","s1.q":"Weekdot не показывает события","s1.a":"Разрешите полный доступ к календарям: Настройки › Конфиденциальность и безопасность › Календари › Weekdot › Полный доступ.","s2.q":"Как добавить календарь Google или Outlook?","s2.a":"Добавьте учетную запись в разделе Настройки › Приложения › Календарь › Учетные записи календаря (Mac: приложение «Календарь» › Добавить учетную запись). Weekdot покажет ее автоматически.","s3.q":"Как изменить язык?","s3.a":"Weekdot использует язык вашего устройства. На iPhone и iPad можно выбрать язык только для Weekdot в разделе Настройки › Приложения › Weekdot › Язык.","s4.q":"Почему значок приложения не показывает сегодняшнюю дату?","s4.a":"Только собственное приложение Apple «Календарь» может само менять свой значок. Добавьте виджет Weekdot «Сегодня» на экран «Домой», чтобы видеть актуальную дату. На Mac значок в Dock показывает сегодняшнюю дату, пока Weekdot открыт.","s5.q":"Синхронизируются ли мои цвета и шаблоны?","s5.a":"Да, через iCloud. Убедитесь, что на всех устройствах вы вошли в iCloud с одним и тем же Аккаунтом Apple.","footer.rights":"Все права защищены.","lang.label":"Язык","mock.Meeting":"Встреча","mock.Lunch":"Обед","mock.Gym":"Спортзал","mock.Dentist":"Стоматолог","mock.Birthday":"День рождения","mock.Flight":"Перелет","mock.Holiday":"Отпуск","mock.Day":"День","mock.Week":"Неделя","mock.Month":"Месяц","mock.Year":"Год","mock.List":"Список","mock.Today":"Сегодня","mock.Calendars":"Календари","mock.Color":"Цвет","mock.Birthdays":"Дни рождения","mock.Doctor":"Врач"},"sk":{"nav.features":"Funkcie","nav.devices":"Zariadenia","nav.faq":"Časté otázky","nav.support":"Podpora","nav.privacy":"Súkromie","meta.description":"Weekdot je rýchly a krásny kalendár pre iPhone, iPad, Apple Watch a Mac so zobrazením dňa, týždňa, mesiaca a roka.","hero.title":"Váš týždeň na prvý pohľad.","hero.sub":"Weekdot je rýchly a krásny kalendár pre iPhone, iPad, Apple Watch a Mac. Zobrazenie dňa, týždňa, mesiaca a roka s farbami, emoji a šablónami – nad kalendármi, ktoré už používate.","hero.cta":"Čoskoro v App Store","hero.note":"Funguje s iCloudom, Googlom, Outlookom, Exchange a všetkými kalendármi v aplikácii Kalendár.","features.title":"Všetko, čo plánujete, v jednom zobrazení","f1.t":"Zobrazenie týždňa so 7 dňami","f1.d":"Uvidíte celý týždeň naraz. Zvoľte 1 až 7 dní, začnite týždeň ľubovoľným dňom a roztiahnutím prstov zväčšite hodiny.","f2.t":"Deň, mesiac a rok","f2.d":"Oddiaľte sa na mesiac s názvami udalostí alebo na rok s rušnými dňami a klepnutím do nich hneď skočte.","f3.t":"Presúvanie, kopírovanie a vkladanie","f3.d":"Presúvajte udalosti potiahnutím, meňte ich dĺžku, kopírujte ich na iný deň alebo ich jedným klepnutím duplikujte.","f4.t":"Farby a emoji","f4.d":"Dajte udalostiam vlastnú farbu a emoji, alebo to nechajte automaticky urobiť pravidlá podľa názvu.","f5.t":"Šablóny","f5.d":"Uložte si udalosti, ktoré plánujete často, a pridávajte ich jedným klepnutím. Weekdot tiež navrhuje údaje zo skorších udalostí.","f6.t":"Všetky vaše kalendáre","f6.d":"Zobrazujte, skrývajte a zoskupujte kalendáre do sád, vytvárajte nové, odoberajte sviatky alebo akýkoľvek odkaz .ics.","f7.t":"Synchronizované cez iCloud","f7.d":"Vaše nastavenia, šablóny, sady, pravidlá, farby a emoji sú rovnaké na každom zariadení.","f8.t":"Widgety a Apple Watch","f8.d":"Widgety Dnes, Nasleduje a Týždeň a k tomu aplikácia pre hodinky s prehľadom dňa a týždňa.","f9.t":"Vo vašom jazyku","f9.d":"Weekdot hovorí viac ako 30 jazykmi a používa jazyk vášho zariadenia.","f10.t":"Počasie","f10.d":"Voliteľne uvidíte predpoveď nad svojimi dňami.","devices.title":"Na všetkých vašich zariadeniach Apple","devices.sub":"Jedna aplikácia pre iPhone, iPad, Mac a Apple Watch.","faq.title":"Otázky","q1":"Nahrádza Weekdot moje kalendárové účty?","a1":"Nie. Weekdot zobrazuje a upravuje kalendáre z aplikácie Kalendár, takže sa všetko ďalej synchronizuje cez iCloud, Google, Outlook alebo Exchange.","q2":"Kde sú uložené moje údaje?","a2":"Vaše udalosti zostávajú vo vašich vlastných kalendárových účtoch. Vlastné nastavenia Weekdot sa synchronizujú cez váš súkromný iCloud. Weekdot nemá žiadne servery, ktoré by ukladali vaše údaje.","q3":"Ktoré jazyky sú podporované?","a3":"Viac ako 30, okrem iného angličtina, holandčina, nemčina, francúzština, španielčina, taliančina, portugalčina, čínština, japončina, kórejčina a arabčina.","q4":"Môžem pridať sviatky?","a4":"Áno. Jedným klepnutím odoberajte štátne sviatky mnohých krajín, alebo vložte akýkoľvek odkaz .ics.","privacy.title":"Súkromie","privacy.p1":"Weekdot je navrhnutý tak, aby vaše údaje zostali vaše.","privacy.p2":"Údaje kalendára: Weekdot číta a zapisuje udalosti len v kalendárových účtoch vo vašom zariadení (aplikácia Kalendár). Vaše udalosti nám nikdy nie sú odosielané.","privacy.p3":"iCloud: Vlastné nastavenia, šablóny, sady kalendárov, pravidlá, farby a emoji aplikácie Weekdot sa ukladajú vo vašom súkromnom iCloude, aby sa synchronizovali medzi vašimi zariadeniami. Nemáme k nim prístup.","privacy.p4":"Počasie (voliteľné): keď zapnete počasie, vaša približná poloha sa odošle do Open-Meteo kvôli predpovedi. Weekdot ju neukladá.","privacy.p5":"Žiadne účty, žiadne sledovanie, žiadne reklamy a žiadna analytika.","privacy.p6":"Máte otázky? Kontaktujte nás cez stránku podpory.","privacy.updated":"Posledná aktualizácia: 24. októbra 2026","support.title":"Pomoc a podpora","s1.q":"Weekdot nezobrazuje žiadne udalosti","s1.a":"Povoľte úplný prístup ku kalendárom: Nastavenia › Súkromie a bezpečnosť › Kalendáre › Weekdot › Úplný prístup.","s2.q":"Ako pridám kalendár Google alebo Outlook?","s2.a":"Pridajte účet v Nastaveniach › Aplikácie › Kalendár › Účty kalendára (Mac: aplikácia Kalendár › Pridať účet). Weekdot ho zobrazí automaticky.","s3.q":"Ako zmením jazyk?","s3.a":"Weekdot používa jazyk vášho zariadenia. Na iPhone a iPade môžete zvoliť jazyk len pre Weekdot v Nastaveniach › Aplikácie › Weekdot › Jazyk.","s4.q":"Prečo ikona aplikácie neukazuje dnešný dátum?","s4.a":"Svoju ikonu dokáže sama meniť len vlastná aplikácia Kalendár od Apple. Pridajte si na plochu widget Weekdot ‚Dnes‘ s aktuálnym dátumom. Na Macu ukazuje ikona v Docku dnešný dátum, keď je Weekdot otvorený.","s5.q":"Synchronizujú sa moje farby a šablóny?","s5.a":"Áno, cez iCloud. Uistite sa, že ste na všetkých zariadeniach prihlásení do iCloudu rovnakým Apple účtom.","footer.rights":"Všetky práva vyhradené.","lang.label":"Jazyk","mock.Meeting":"Stretnutie","mock.Lunch":"Obed","mock.Gym":"Posilňovňa","mock.Dentist":"Zubár","mock.Birthday":"Narodeniny","mock.Flight":"Let","mock.Holiday":"Dovolenka","mock.Day":"Deň","mock.Week":"Týždeň","mock.Month":"Mesiac","mock.Year":"Rok","mock.List":"Zoznam","mock.Today":"Dnes","mock.Calendars":"Kalendáre","mock.Color":"Farba","mock.Birthdays":"Narodeniny","mock.Doctor":"Lekár"},"sv":{"nav.features":"Funktioner","nav.devices":"Enheter","nav.faq":"Vanliga frågor","nav.support":"Support","nav.privacy":"Integritet","meta.description":"Weekdot är en snabb och snygg kalender för iPhone, iPad, Apple Watch och Mac med dag-, vecko-, månads- och årsvy.","hero.title":"Din vecka i en överblick.","hero.sub":"Weekdot är en snabb och snygg kalender för iPhone, iPad, Apple Watch och Mac. Dag-, vecko-, månads- och årsvy med färger, emoji och mallar – ovanpå kalendrarna du redan använder.","hero.cta":"Kommer snart till App Store","hero.note":"Fungerar med iCloud, Google, Outlook, Exchange och alla kalendrar i appen Kalender.","features.title":"Allt du planerar, i en vy","f1.t":"Veckovy med 7 dagar","f1.d":"Se hela veckan på en gång. Välj 1 till 7 dagar, börja veckan på valfri dag och nyp för att zooma timmarna.","f2.t":"Dag, månad och år","f2.d":"Zooma ut till en månad med händelsernas namn eller ett år med dina upptagna dagar, och tryck för att hoppa direkt in.","f3.t":"Dra, kopiera och klistra in","f3.d":"Flytta händelser genom att dra, ändra deras längd, kopiera dem till en annan dag eller duplicera dem med ett tryck.","f4.t":"Färger och emoji","f4.d":"Ge händelser en egen färg och emoji, eller låt regler göra det automatiskt utifrån titeln.","f5.t":"Mallar","f5.d":"Spara händelser du ofta planerar och lägg till dem med ett tryck. Weekdot föreslår även detaljer från tidigare händelser.","f6.t":"Alla dina kalendrar","f6.d":"Visa, göm och gruppera kalendrar i uppsättningar, skapa nya, prenumerera på helgdagar eller valfri .ics-länk.","f7.t":"Synkroniserad med iCloud","f7.d":"Dina inställningar, mallar, uppsättningar, regler, färger och emoji är desamma på alla enheter.","f8.t":"Widgetar och Apple Watch","f8.d":"Widgetarna Idag, Härnäst och Vecka, plus en klockapp för din dag och vecka i en överblick.","f9.t":"På ditt språk","f9.d":"Weekdot talar mer än 30 språk och följer språket på din enhet.","f10.t":"Väder","f10.d":"Se om du vill väderprognosen ovanför dina dagar.","devices.title":"På alla dina Apple-enheter","devices.sub":"En app för iPhone, iPad, Mac och Apple Watch.","faq.title":"Frågor","q1":"Ersätter Weekdot mina kalenderkonton?","a1":"Nej. Weekdot visar och redigerar kalendrarna från appen Kalender, så allt fortsätter att synkroniseras via iCloud, Google, Outlook eller Exchange.","q2":"Var lagras min data?","a2":"Dina händelser stannar i dina egna kalenderkonton. Weekdots egna inställningar synkroniseras via din privata iCloud. Weekdot har inga servrar som lagrar din data.","q3":"Vilka språk stöds?","a3":"Mer än 30, bland annat engelska, nederländska, tyska, franska, spanska, italienska, portugisiska, kinesiska, japanska, koreanska och arabiska.","q4":"Kan jag lägga till helgdagar?","a4":"Ja. Prenumerera på helgdagar för många länder med ett tryck, eller klistra in valfri .ics-länk.","privacy.title":"Integritet","privacy.p1":"Weekdot är byggd för att din data ska förbli din.","privacy.p2":"Kalenderdata: Weekdot läser och skriver händelser endast i kalenderkontona på din enhet (appen Kalender). Dina händelser skickas aldrig till oss.","privacy.p3":"iCloud: Weekdots egna inställningar, mallar, kalenderuppsättningar, regler, färger och emoji lagras i din privata iCloud så att de synkroniseras mellan dina enheter. Vi har ingen åtkomst till dem.","privacy.p4":"Väder (valfritt): När du slår på väder skickas din ungefärliga plats till Open-Meteo för att hämta en prognos. Weekdot sparar den inte.","privacy.p5":"Inga konton, ingen spårning, inga annonser och ingen analys.","privacy.p6":"Frågor? Kontakta oss via supportsidan.","privacy.updated":"Senast uppdaterad: 24 oktober 2026","support.title":"Hjälp och support","s1.q":"Weekdot visar inga händelser","s1.a":"Tillåt full kalenderåtkomst: Inställningar › Integritet och säkerhet › Kalendrar › Weekdot › Full åtkomst.","s2.q":"Hur lägger jag till en Google- eller Outlook-kalender?","s2.a":"Lägg till kontot i Inställningar › Appar › Kalender › Kalenderkonton (Mac: appen Kalender › Lägg till konto). Weekdot visar det automatiskt.","s3.q":"Hur ändrar jag språket?","s3.a":"Weekdot följer språket på din enhet. På iPhone och iPad kan du välja ett språk enbart för Weekdot i Inställningar › Appar › Weekdot › Språk.","s4.q":"Varför visar inte appsymbolen dagens datum?","s4.a":"Endast Apples egen Kalender-app kan ändra sin symbol själv. Lägg till Weekdots widget ’Idag’ på hemskärmen för ett aktuellt datum. På Mac visar symbolen i Dock dagens datum medan Weekdot är öppen.","s5.q":"Synkroniseras mina färger och mallar?","s5.a":"Ja, via iCloud. Se till att du är inloggad på iCloud med samma Apple-konto på alla dina enheter.","footer.rights":"Alla rättigheter förbehållna.","lang.label":"Språk","mock.Meeting":"Möte","mock.Lunch":"Lunch","mock.Gym":"Gym","mock.Dentist":"Tandläkare","mock.Birthday":"Födelsedag","mock.Flight":"Flyg","mock.Holiday":"Semester","mock.Day":"Dag","mock.Week":"Vecka","mock.Month":"Månad","mock.Year":"År","mock.List":"Lista","mock.Today":"Idag","mock.Calendars":"Kalendrar","mock.Color":"Färg","mock.Birthdays":"Födelsedagar","mock.Doctor":"Läkare"},"th":{"nav.features":"คุณสมบัติ","nav.devices":"อุปกรณ์","nav.faq":"คำถามที่พบบ่อย","nav.support":"บริการช่วยเหลือ","nav.privacy":"ความเป็นส่วนตัว","meta.description":"Weekdot คือปฏิทินที่รวดเร็วและสวยงามสำหรับ iPhone, iPad, Apple Watch และ Mac พร้อมมุมมองวัน สัปดาห์ เดือน และปี","hero.title":"สัปดาห์ของคุณในพริบตา","hero.sub":"Weekdot คือปฏิทินที่รวดเร็วและสวยงามสำหรับ iPhone, iPad, Apple Watch และ Mac มุมมองวัน สัปดาห์ เดือน และปี พร้อมสี อีโมจิ และแม่แบบ ทำงานบนปฏิทินที่คุณใช้อยู่แล้ว","hero.cta":"เร็วๆ นี้ใน App Store","hero.note":"ใช้งานได้กับ iCloud, Google, Outlook, Exchange และทุกปฏิทินในแอปปฏิทิน","features.title":"ทุกสิ่งที่คุณวางแผน ในมุมมองเดียว","f1.t":"มุมมองสัปดาห์ 7 วัน","f1.d":"ดูทั้งสัปดาห์ได้ในคราวเดียว เลือก 1 ถึง 7 วัน เริ่มสัปดาห์ในวันใดก็ได้ และจีบนิ้วเพื่อซูมชั่วโมง","f2.t":"วัน เดือน และปี","f2.d":"ย่อออกเป็นเดือนที่มีชื่อเหตุการณ์ หรือปีที่แสดงวันที่ไม่ว่าง แล้วแตะเพื่อเข้าไปดูทันที","f3.t":"ลาก คัดลอก และวาง","f3.d":"ย้ายเหตุการณ์ด้วยการลาก เปลี่ยนความยาว คัดลอกไปยังวันอื่น หรือทำสำเนาด้วยการแตะครั้งเดียว","f4.t":"สีและอีโมจิ","f4.d":"กำหนดสีและอีโมจิของเหตุการณ์เอง หรือให้กฎจัดการโดยอัตโนมัติตามชื่อ","f5.t":"แม่แบบ","f5.d":"บันทึกเหตุการณ์ที่คุณวางแผนบ่อยๆ แล้วเพิ่มได้ด้วยการแตะครั้งเดียว Weekdot ยังแนะนำรายละเอียดจากเหตุการณ์ก่อนหน้าอีกด้วย","f6.t":"ปฏิทินทั้งหมดของคุณ","f6.d":"แสดง ซ่อน และจัดกลุ่มปฏิทินเป็นชุด สร้างปฏิทินใหม่ สมัครรับวันหยุดหรือลิงก์ .ics ใดก็ได้","f7.t":"ซิงค์กับ iCloud","f7.d":"การตั้งค่า แม่แบบ ชุด กฎ สี และอีโมจิของคุณเหมือนกันในทุกอุปกรณ์","f8.t":"วิดเจ็ตและ Apple Watch","f8.d":"วิดเจ็ตวันนี้ ถัดไป และสัปดาห์ พร้อมแอปนาฬิกาเพื่อดูวันและสัปดาห์ของคุณในพริบตา","f9.t":"ในภาษาของคุณ","f9.d":"Weekdot รองรับมากกว่า 30 ภาษาและใช้ภาษาตามอุปกรณ์ของคุณ","f10.t":"สภาพอากาศ","f10.d":"เลือกดูพยากรณ์อากาศเหนือวันต่างๆ ของคุณได้","devices.title":"บนอุปกรณ์ Apple ทั้งหมดของคุณ","devices.sub":"แอปเดียวสำหรับ iPhone, iPad, Mac และ Apple Watch","faq.title":"คำถาม","q1":"Weekdot ใช้แทนบัญชีปฏิทินของฉันหรือไม่","a1":"ไม่ Weekdot แสดงและแก้ไขปฏิทินจากแอปปฏิทิน ทุกอย่างจึงยังคงซิงค์ผ่าน iCloud, Google, Outlook หรือ Exchange","q2":"ข้อมูลของฉันถูกจัดเก็บที่ไหน","a2":"เหตุการณ์ของคุณอยู่ในบัญชีปฏิทินของคุณเอง การตั้งค่าของ Weekdot ซิงค์ผ่าน iCloud ส่วนตัวของคุณ Weekdot ไม่มีเซิร์ฟเวอร์ที่จัดเก็บข้อมูลของคุณ","q3":"รองรับภาษาใดบ้าง","a3":"มากกว่า 30 ภาษา รวมถึงอังกฤษ ดัตช์ เยอรมัน ฝรั่งเศส สเปน อิตาลี โปรตุเกส จีน ญี่ปุ่น เกาหลี และอาหรับ","q4":"ฉันสามารถเพิ่มวันหยุดได้หรือไม่","a4":"ได้ สมัครรับวันหยุดราชการของหลายประเทศได้ด้วยการแตะครั้งเดียว หรือวางลิงก์ .ics ใดก็ได้","privacy.title":"ความเป็นส่วนตัว","privacy.p1":"Weekdot สร้างขึ้นเพื่อให้ข้อมูลของคุณเป็นของคุณ","privacy.p2":"ข้อมูลปฏิทิน: Weekdot อ่านและเขียนเหตุการณ์เฉพาะในบัญชีปฏิทินบนอุปกรณ์ของคุณ (แอปปฏิทิน) เท่านั้น เหตุการณ์ของคุณจะไม่ถูกส่งมาให้เราเลย","privacy.p3":"iCloud: การตั้งค่า แม่แบบ ชุดปฏิทิน กฎ สี และอีโมจิของ Weekdot จะถูกจัดเก็บใน iCloud ส่วนตัวของคุณเพื่อซิงค์ระหว่างอุปกรณ์ของคุณ เราไม่สามารถเข้าถึงข้อมูลเหล่านี้ได้","privacy.p4":"สภาพอากาศ (ไม่บังคับ): เมื่อคุณเปิดใช้สภาพอากาศ ตำแหน่งที่ตั้งโดยประมาณของคุณจะถูกส่งไปยัง Open-Meteo เพื่อรับพยากรณ์ Weekdot ไม่จัดเก็บข้อมูลนี้","privacy.p5":"ไม่มีบัญชี ไม่มีการติดตาม ไม่มีโฆษณา และไม่มีการวิเคราะห์","privacy.p6":"มีคำถามหรือไม่ ติดต่อเราผ่านหน้าบริการช่วยเหลือ","privacy.updated":"อัปเดตล่าสุด: 24 ตุลาคม 2026","support.title":"วิธีใช้และบริการช่วยเหลือ","s1.q":"Weekdot ไม่แสดงเหตุการณ์","s1.a":"อนุญาตการเข้าถึงปฏิทินเต็มรูปแบบ: การตั้งค่า › ความเป็นส่วนตัวและความปลอดภัย › ปฏิทิน › Weekdot › การเข้าถึงเต็มรูปแบบ","s2.q":"ฉันจะเพิ่มปฏิทิน Google หรือ Outlook ได้อย่างไร","s2.a":"เพิ่มบัญชีในการตั้งค่า › แอป › ปฏิทิน › บัญชีปฏิทิน (Mac: แอปปฏิทิน › เพิ่มบัญชี) Weekdot จะแสดงโดยอัตโนมัติ","s3.q":"ฉันจะเปลี่ยนภาษาได้อย่างไร","s3.a":"Weekdot ใช้ภาษาตามอุปกรณ์ของคุณ บน iPhone และ iPad คุณสามารถเลือกภาษาสำหรับ Weekdot เท่านั้นได้ในการตั้งค่า › แอป › Weekdot › ภาษา","s4.q":"ทำไมไอคอนแอปไม่แสดงวันที่ของวันนี้","s4.a":"มีเพียงแอปปฏิทินของ Apple เท่านั้นที่เปลี่ยนไอคอนได้เอง เพิ่มวิดเจ็ต ‘วันนี้’ ของ Weekdot ลงในหน้าจอโฮมเพื่อดูวันที่แบบสด บน Mac ไอคอนใน Dock จะแสดงวันที่ของวันนี้ขณะที่ Weekdot เปิดอยู่","s5.q":"สีและแม่แบบของฉันซิงค์หรือไม่","s5.a":"ใช่ ผ่าน iCloud ตรวจสอบให้แน่ใจว่าคุณลงชื่อเข้า iCloud ด้วยบัญชี Apple เดียวกันบนอุปกรณ์ทั้งหมดของคุณ","footer.rights":"สงวนลิขสิทธิ์","lang.label":"ภาษา","mock.Meeting":"ประชุม","mock.Lunch":"มื้อกลางวัน","mock.Gym":"ยิม","mock.Dentist":"ทันตแพทย์","mock.Birthday":"วันเกิด","mock.Flight":"เที่ยวบิน","mock.Holiday":"วันหยุด","mock.Day":"วัน","mock.Week":"สัปดาห์","mock.Month":"เดือน","mock.Year":"ปี","mock.List":"รายการ","mock.Today":"วันนี้","mock.Calendars":"ปฏิทิน","mock.Color":"สี","mock.Birthdays":"วันเกิด","mock.Doctor":"หมอ"},"tr":{"nav.features":"Özellikler","nav.devices":"Aygıtlar","nav.faq":"SSS","nav.support":"Destek","nav.privacy":"Gizlilik","meta.description":"Weekdot; iPhone, iPad, Apple Watch ve Mac için gün, hafta, ay ve yıl görüntüleri sunan hızlı ve güzel bir takvimdir.","hero.title":"Bir bakışta haftanız.","hero.sub":"Weekdot; iPhone, iPad, Apple Watch ve Mac için hızlı ve güzel bir takvimdir. Renkler, emojiler ve şablonlarla gün, hafta, ay ve yıl görüntüleri; zaten kullandığınız takvimlerin üzerinde.","hero.cta":"Çok yakında App Store’da","hero.note":"iCloud, Google, Outlook, Exchange ve Takvim uygulamasındaki her takvimle çalışır.","features.title":"Planladığınız her şey tek görüntüde","f1.t":"7 günlük hafta görüntüsü","f1.d":"Tüm haftanızı tek seferde görün. 1 ile 7 gün arasında seçin, haftayı istediğiniz günde başlatın ve saatleri sıkıştırarak yakınlaştırın.","f2.t":"Gün, ay ve yıl","f2.d":"Etkinlik adlarıyla bir aya veya yoğun günlerinizle bir yıla uzaklaştırın ve hemen geçmek için dokunun.","f3.t":"Sürükle, kopyala ve yapıştır","f3.d":"Etkinlikleri sürükleyerek taşıyın, sürelerini değiştirin, başka bir güne kopyalayın veya tek dokunuşla çoğaltın.","f4.t":"Renkler ve emojiler","f4.d":"Etkinliklere kendi renk ve emojilerini verin ya da kuralların bunu başlığa göre otomatik yapmasına izin verin.","f5.t":"Şablonlar","f5.d":"Sık planladığınız etkinlikleri kaydedin ve tek dokunuşla ekleyin. Weekdot önceki etkinliklerden ayrıntılar da önerir.","f6.t":"Tüm takvimleriniz","f6.d":"Takvimleri gösterin, gizleyin ve setlerde gruplayın, yenilerini oluşturun, tatillere veya herhangi bir .ics bağlantısına abone olun.","f7.t":"iCloud ile eşzamanlı","f7.d":"Ayarlarınız, şablonlarınız, setleriniz, kurallarınız, renkleriniz ve emojileriniz her aygıtta aynıdır.","f8.t":"Widget’lar ve Apple Watch","f8.d":"Bugün, Sıradaki ve Hafta widget’ları ile gününüzü ve haftanızı bir bakışta gösteren bir saat uygulaması.","f9.t":"Kendi dilinizde","f9.d":"Weekdot 30’dan fazla dil konuşur ve aygıtınızın dilini kullanır.","f10.t":"Hava Durumu","f10.d":"İsterseniz günlerinizin üstünde tahmini görün.","devices.title":"Tüm Apple aygıtlarınızda","devices.sub":"iPhone, iPad, Mac ve Apple Watch için tek uygulama.","faq.title":"Sorular","q1":"Weekdot takvim hesaplarımın yerini mi alır?","a1":"Hayır. Weekdot, Takvim uygulamasındaki takvimleri gösterir ve düzenler; böylece her şey iCloud, Google, Outlook veya Exchange aracılığıyla eşzamanlanmaya devam eder.","q2":"Verilerim nerede saklanıyor?","a2":"Etkinlikleriniz kendi takvim hesaplarınızda kalır. Weekdot’in kendi ayarları özel iCloud’unuz aracılığıyla eşzamanlanır. Weekdot’in verilerinizi saklayan sunucuları yoktur.","q3":"Hangi diller destekleniyor?","a3":"İngilizce, Felemenkçe, Almanca, Fransızca, İspanyolca, İtalyanca, Portekizce, Çince, Japonca, Korece ve Arapça dahil 30’dan fazla dil.","q4":"Tatil ekleyebilir miyim?","a4":"Evet. Birçok ülkenin resmî tatillerine tek dokunuşla abone olun veya herhangi bir .ics bağlantısını yapıştırın.","privacy.title":"Gizlilik","privacy.p1":"Weekdot, verilerinizin size ait kalması için tasarlandı.","privacy.p2":"Takvim verileri: Weekdot etkinlikleri yalnızca aygıtınızdaki takvim hesaplarında (Takvim uygulaması) okur ve yazar. Etkinlikleriniz asla bize gönderilmez.","privacy.p3":"iCloud: Weekdot’in kendi ayarları, şablonları, takvim setleri, kuralları, renkleri ve emojileri aygıtlarınız arasında eşzamanlanmak üzere özel iCloud’unuzda saklanır. Bunlara erişemeyiz.","privacy.p4":"Hava durumu (isteğe bağlı): Hava durumunu açtığınızda tahmin almak için yaklaşık konumunuz Open-Meteo’ya gönderilir. Weekdot bunu saklamaz.","privacy.p5":"Hesap yok, izleme yok, reklam yok, analiz yok.","privacy.p6":"Sorularınız mı var? Destek sayfası aracılığıyla bize ulaşın.","privacy.updated":"Son güncelleme: 24 Ekim 2026","support.title":"Yardım ve Destek","s1.q":"Weekdot hiç etkinlik göstermiyor","s1.a":"Takvimlere tam erişime izin verin: Ayarlar › Gizlilik ve Güvenlik › Takvimler › Weekdot › Tam Erişim.","s2.q":"Google veya Outlook takvimini nasıl eklerim?","s2.a":"Hesabı Ayarlar › Uygulamalar › Takvim › Takvim Hesapları bölümünde ekleyin (Mac: Takvim uygulaması › Hesap Ekle). Weekdot onu otomatik olarak gösterir.","s3.q":"Dili nasıl değiştiririm?","s3.a":"Weekdot aygıtınızın dilini kullanır. iPhone ve iPad’de Ayarlar › Uygulamalar › Weekdot › Dil bölümünden yalnızca Weekdot için bir dil seçebilirsiniz.","s4.q":"Uygulama simgesi neden bugünün tarihini göstermiyor?","s4.a":"Simgesini kendiliğinden değiştirebilen tek uygulama Apple’ın kendi Takvim uygulamasıdır. Canlı tarih için Weekdot ‘Bugün’ widget’ını Ana Ekran’ınıza ekleyin. Mac’te Weekdot açıkken Dock simgesi bugünün tarihini gösterir.","s5.q":"Renklerim ve şablonlarım eşzamanlanıyor mu?","s5.a":"Evet, iCloud aracılığıyla. Tüm aygıtlarınızda aynı Apple Hesabı ile iCloud’a giriş yaptığınızdan emin olun.","footer.rights":"Tüm hakları saklıdır.","lang.label":"Dil","mock.Meeting":"Toplantı","mock.Lunch":"Öğle yemeği","mock.Gym":"Spor salonu","mock.Dentist":"Dişçi","mock.Birthday":"Doğum günü","mock.Flight":"Uçuş","mock.Holiday":"Tatil","mock.Day":"Gün","mock.Week":"Hafta","mock.Month":"Ay","mock.Year":"Yıl","mock.List":"Liste","mock.Today":"Bugün","mock.Calendars":"Takvimler","mock.Color":"Renk","mock.Birthdays":"Doğum Günleri","mock.Doctor":"Doktor"},"uk":{"nav.features":"Функції","nav.devices":"Пристрої","nav.faq":"Питання","nav.support":"Підтримка","nav.privacy":"Приватність","meta.description":"Weekdot — швидкий і гарний календар для iPhone, iPad, Apple Watch і Mac із режимами дня, тижня, місяця й року.","hero.title":"Ваш тиждень одним поглядом.","hero.sub":"Weekdot — швидкий і гарний календар для iPhone, iPad, Apple Watch і Mac. Режими дня, тижня, місяця й року з кольорами, емодзі та шаблонами — поверх календарів, якими ви вже користуєтеся.","hero.cta":"Незабаром в App Store","hero.note":"Працює з iCloud, Google, Outlook, Exchange і будь-яким календарем у програмі «Календар».","features.title":"Усі ваші плани в одному вигляді","f1.t":"Тиждень із 7 днів","f1.d":"Увесь тиждень одразу. Виберіть від 1 до 7 днів, починайте тиждень із будь-якого дня та масштабуйте години жестом.","f2.t":"День, місяць і рік","f2.d":"Зменште масштаб до місяця з назвами подій або до року із зайнятими днями й торкніться, щоб одразу перейти.","f3.t":"Перетягування, копіювання й вставлення","f3.d":"Переміщуйте події перетягуванням, змінюйте їхню тривалість, копіюйте на інший день або дублюйте одним дотиком.","f4.t":"Кольори й емодзі","f4.d":"Надайте подіям власний колір і емодзі або дозвольте правилам робити це автоматично за назвою.","f5.t":"Шаблони","f5.d":"Зберігайте часті події та додавайте їх одним дотиком. Weekdot також пропонує деталі з попередніх подій.","f6.t":"Усі ваші календарі","f6.d":"Показуйте, ховайте й об’єднуйте календарі в набори, створюйте нові, підписуйтеся на свята або будь-яке посилання .ics.","f7.t":"Синхронізація з iCloud","f7.d":"Ваші параметри, шаблони, набори, правила, кольори й емодзі однакові на кожному пристрої.","f8.t":"Віджети та Apple Watch","f8.d":"Віджети «Сьогодні», «Далі» і «Тиждень», а також програма для годинника, щоб бачити день і тиждень одним поглядом.","f9.t":"Вашою мовою","f9.d":"Weekdot розмовляє понад 30 мовами й використовує мову вашого пристрою.","f10.t":"Погода","f10.d":"За бажанням показуйте прогноз над днями.","devices.title":"На всіх ваших пристроях Apple","devices.sub":"Одна програма для iPhone, iPad, Mac і Apple Watch.","faq.title":"Питання","q1":"Чи замінює Weekdot мої облікові записи календарів?","a1":"Ні. Weekdot показує й редагує календарі з програми «Календар», тож усе продовжує синхронізуватися через iCloud, Google, Outlook або Exchange.","q2":"Де зберігаються мої дані?","a2":"Ваші події залишаються у ваших власних облікових записах календарів. Власні параметри Weekdot синхронізуються через ваш приватний iCloud. Weekdot не має серверів, які зберігають ваші дані.","q3":"Які мови підтримуються?","a3":"Понад 30, зокрема англійська, нідерландська, німецька, французька, іспанська, італійська, португальська, китайська, японська, корейська й арабська.","q4":"Чи можна додати свята?","a4":"Так. Підпишіться на державні свята багатьох країн одним дотиком або вставте будь-яке посилання .ics.","privacy.title":"Приватність","privacy.p1":"Weekdot створено, щоб ваші дані залишалися вашими.","privacy.p2":"Дані календаря: Weekdot читає й записує події лише в облікових записах календарів на вашому пристрої (програма «Календар»). Ваші події ніколи не надсилаються нам.","privacy.p3":"iCloud: власні параметри Weekdot, шаблони, набори календарів, правила, кольори й емодзі зберігаються у вашому приватному iCloud для синхронізації між пристроями. Ми не маємо до них доступу.","privacy.p4":"Погода (за бажанням): коли ви вмикаєте погоду, ваше приблизне розташування надсилається до Open-Meteo для отримання прогнозу. Weekdot його не зберігає.","privacy.p5":"Без облікових записів, стеження, реклами й аналітики.","privacy.p6":"Маєте запитання? Зв’яжіться з нами через сторінку підтримки.","privacy.updated":"Останнє оновлення: 24 жовтня 2026 р.","support.title":"Допомога й підтримка","s1.q":"Weekdot не показує подій","s1.a":"Дозвольте повний доступ до календарів: Параметри › Приватність і безпека › Календарі › Weekdot › Повний доступ.","s2.q":"Як додати календар Google або Outlook?","s2.a":"Додайте обліковий запис у меню Параметри › Програми › Календар › Облікові записи календаря (Mac: програма «Календар» › Додати обліковий запис). Weekdot покаже його автоматично.","s3.q":"Як змінити мову?","s3.a":"Weekdot використовує мову вашого пристрою. На iPhone та iPad можна вибрати мову лише для Weekdot у меню Параметри › Програми › Weekdot › Мова.","s4.q":"Чому іконка програми не показує сьогоднішню дату?","s4.a":"Лише власна програма Apple «Календар» може сама змінювати свою іконку. Додайте віджет Weekdot «Сьогодні» на початковий екран, щоб бачити актуальну дату. На Mac іконка в Dock показує сьогоднішню дату, доки Weekdot відкрито.","s5.q":"Чи синхронізуються мої кольори й шаблони?","s5.a":"Так, через iCloud. Переконайтеся, що на всіх пристроях ви ввійшли в iCloud з одним і тим самим обліковим записом Apple.","footer.rights":"Усі права захищено.","lang.label":"Мова","mock.Meeting":"Зустріч","mock.Lunch":"Обід","mock.Gym":"Спортзал","mock.Dentist":"Стоматолог","mock.Birthday":"День народження","mock.Flight":"Переліт","mock.Holiday":"Відпустка","mock.Day":"День","mock.Week":"Тиждень","mock.Month":"Місяць","mock.Year":"Рік","mock.List":"Список","mock.Today":"Сьогодні","mock.Calendars":"Календарі","mock.Color":"Колір","mock.Birthdays":"Дні народження","mock.Doctor":"Лікар"},"vi":{"nav.features":"Tính năng","nav.devices":"Thiết bị","nav.faq":"Câu hỏi thường gặp","nav.support":"Hỗ trợ","nav.privacy":"Quyền riêng tư","meta.description":"Weekdot là ứng dụng lịch nhanh, đẹp cho iPhone, iPad, Apple Watch và Mac với chế độ xem ngày, tuần, tháng và năm.","hero.title":"Tuần của bạn trong nháy mắt.","hero.sub":"Weekdot là ứng dụng lịch nhanh, đẹp cho iPhone, iPad, Apple Watch và Mac. Chế độ xem ngày, tuần, tháng và năm, với màu sắc, emoji và mẫu — trên nền các lịch bạn đang dùng.","hero.cta":"Sắp có trên App Store","hero.note":"Hoạt động với iCloud, Google, Outlook, Exchange và mọi lịch trong ứng dụng Lịch.","features.title":"Mọi kế hoạch của bạn, trong một chế độ xem","f1.t":"Chế độ xem tuần với 7 ngày","f1.d":"Xem toàn bộ tuần cùng lúc. Chọn từ 1 đến 7 ngày, bắt đầu tuần vào bất kỳ ngày nào và chụm để thu phóng giờ.","f2.t":"Ngày, tháng và năm","f2.d":"Thu nhỏ để xem tháng với tên sự kiện hoặc năm với những ngày bận rộn, rồi chạm để đi thẳng vào.","f3.t":"Kéo, sao chép & dán","f3.d":"Di chuyển sự kiện bằng cách kéo, thay đổi thời lượng, sao chép sang ngày khác hoặc nhân bản chỉ với một chạm.","f4.t":"Màu sắc & emoji","f4.d":"Đặt màu và emoji riêng cho sự kiện, hoặc để quy tắc tự động làm điều đó dựa trên tiêu đề.","f5.t":"Mẫu","f5.d":"Lưu các sự kiện bạn thường lên kế hoạch và thêm chúng chỉ với một chạm. Weekdot cũng gợi ý chi tiết từ các sự kiện trước.","f6.t":"Tất cả lịch của bạn","f6.d":"Hiển thị, ẩn và nhóm lịch thành bộ, tạo lịch mới, đăng ký ngày lễ hoặc bất kỳ liên kết .ics nào.","f7.t":"Đồng bộ với iCloud","f7.d":"Cài đặt, mẫu, bộ, quy tắc, màu sắc và emoji của bạn giống nhau trên mọi thiết bị.","f8.t":"Tiện ích & Apple Watch","f8.d":"Tiện ích Hôm nay, Tiếp theo và Tuần, cùng ứng dụng đồng hồ để xem nhanh ngày và tuần của bạn.","f9.t":"Bằng ngôn ngữ của bạn","f9.d":"Weekdot hỗ trợ hơn 30 ngôn ngữ và dùng ngôn ngữ của thiết bị.","f10.t":"Thời tiết","f10.d":"Tùy chọn xem dự báo phía trên các ngày của bạn.","devices.title":"Trên tất cả thiết bị Apple của bạn","devices.sub":"Một ứng dụng cho iPhone, iPad, Mac và Apple Watch.","faq.title":"Câu hỏi","q1":"Weekdot có thay thế các tài khoản lịch của tôi không?","a1":"Không. Weekdot hiển thị và sửa các lịch từ ứng dụng Lịch, vì vậy mọi thứ vẫn được đồng bộ hóa qua iCloud, Google, Outlook hoặc Exchange.","q2":"Dữ liệu của tôi được lưu ở đâu?","a2":"Sự kiện của bạn vẫn nằm trong tài khoản lịch của riêng bạn. Cài đặt riêng của Weekdot được đồng bộ hóa qua iCloud riêng tư của bạn. Weekdot không có máy chủ nào lưu trữ dữ liệu của bạn.","q3":"Những ngôn ngữ nào được hỗ trợ?","a3":"Hơn 30 ngôn ngữ, bao gồm tiếng Anh, Hà Lan, Đức, Pháp, Tây Ban Nha, Ý, Bồ Đào Nha, Trung, Nhật, Hàn và Ả Rập.","q4":"Tôi có thể thêm ngày lễ không?","a4":"Có. Đăng ký ngày lễ của nhiều quốc gia chỉ với một chạm, hoặc dán bất kỳ liên kết .ics nào.","privacy.title":"Quyền riêng tư","privacy.p1":"Weekdot được xây dựng để dữ liệu của bạn luôn là của bạn.","privacy.p2":"Dữ liệu lịch: Weekdot chỉ đọc và ghi sự kiện trong các tài khoản lịch trên thiết bị của bạn (ứng dụng Lịch). Sự kiện của bạn không bao giờ được gửi cho chúng tôi.","privacy.p3":"iCloud: Cài đặt, mẫu, bộ lịch, quy tắc, màu sắc và emoji riêng của Weekdot được lưu trong iCloud riêng tư của bạn để đồng bộ hóa giữa các thiết bị. Chúng tôi không thể truy cập chúng.","privacy.p4":"Thời tiết (tùy chọn): khi bạn bật thời tiết, vị trí gần đúng của bạn được gửi tới Open-Meteo để lấy dự báo. Weekdot không lưu trữ vị trí này.","privacy.p5":"Không tài khoản, không theo dõi, không quảng cáo và không phân tích.","privacy.p6":"Có câu hỏi? Liên hệ qua trang hỗ trợ.","privacy.updated":"Cập nhật lần cuối: 24 tháng 10, 2026","support.title":"Trợ giúp & Hỗ trợ","s1.q":"Weekdot không hiển thị sự kiện nào","s1.a":"Cho phép truy cập lịch toàn bộ: Cài đặt › Quyền riêng tư & Bảo mật › Lịch › Weekdot › Truy cập toàn bộ.","s2.q":"Làm cách nào để thêm lịch Google hoặc Outlook?","s2.a":"Thêm tài khoản trong Cài đặt › Ứng dụng › Lịch › Tài khoản lịch (Mac: ứng dụng Lịch › Thêm tài khoản). Weekdot sẽ tự động hiển thị.","s3.q":"Làm cách nào để đổi ngôn ngữ?","s3.a":"Weekdot dùng ngôn ngữ của thiết bị. Trên iPhone và iPad, bạn có thể chọn ngôn ngữ chỉ cho Weekdot trong Cài đặt › Ứng dụng › Weekdot › Ngôn ngữ.","s4.q":"Tại sao biểu tượng ứng dụng không hiển thị ngày hôm nay?","s4.a":"Chỉ ứng dụng Lịch của chính Apple mới có thể tự thay đổi biểu tượng. Hãy thêm tiện ích ‘Hôm nay’ của Weekdot vào Màn hình chính để xem ngày trực tiếp. Trên Mac, biểu tượng trên Dock hiển thị ngày hôm nay khi Weekdot đang mở.","s5.q":"Màu sắc và mẫu của tôi có được đồng bộ không?","s5.a":"Có, qua iCloud. Hãy đảm bảo bạn đã đăng nhập iCloud bằng cùng một Tài khoản Apple trên tất cả thiết bị.","footer.rights":"Bảo lưu mọi quyền.","lang.label":"Ngôn ngữ","mock.Meeting":"Họp","mock.Lunch":"Ăn trưa","mock.Gym":"Gym","mock.Dentist":"Nha sĩ","mock.Birthday":"Sinh nhật","mock.Flight":"Chuyến bay","mock.Holiday":"Kỳ nghỉ","mock.Day":"Ngày","mock.Week":"Tuần","mock.Month":"Tháng","mock.Year":"Năm","mock.List":"Danh sách","mock.Today":"Hôm nay","mock.Calendars":"Lịch","mock.Color":"Màu","mock.Birthdays":"Sinh nhật","mock.Doctor":"Bác sĩ"},"zh-Hans":{"nav.features":"功能","nav.devices":"设备","nav.faq":"常见问题","nav.support":"支持","nav.privacy":"隐私","meta.description":"Weekdot 是一款快速、精美的日历 App，适用于 iPhone、iPad、Apple Watch 和 Mac，提供日、周、月和年视图。","hero.title":"一周日程，一目了然。","hero.sub":"Weekdot 是一款快速、精美的日历 App，适用于 iPhone、iPad、Apple Watch 和 Mac。日、周、月和年视图，配有颜色、表情符号和模板，基于你已在使用的日历。","hero.cta":"即将登陆 App Store","hero.note":"支持 iCloud、Google、Outlook、Exchange 以及“日历”App 中的所有日历。","features.title":"你的所有计划，尽在一个视图","f1.t":"7 天周视图","f1.d":"一次查看整周。可选择 1 到 7 天，从任意一天开始一周，并通过双指开合缩放小时。","f2.t":"日、月和年","f2.d":"缩小到显示日程名称的月视图，或显示忙碌日的年视图，轻点即可直接进入。","f3.t":"拖移、拷贝和粘贴","f3.d":"拖移即可移动日程、更改时长、拷贝到另一天，或轻点一下即可复制。","f4.t":"颜色与表情符号","f4.d":"为日程设置专属颜色和表情符号，或让规则根据标题自动设置。","f5.t":"模板","f5.d":"存储常用日程，轻点一下即可添加。Weekdot 还会根据以前的日程建议详细信息。","f6.t":"你的所有日历","f6.d":"显示、隐藏日历并将其分组，新建日历，订阅节假日或任意 .ics 链接。","f7.t":"通过 iCloud 同步","f7.d":"你的设置、模板、日历组、规则、颜色和表情符号在每台设备上都保持一致。","f8.t":"小组件与 Apple Watch","f8.d":"“今天”、“即将开始”和“周”小组件，以及手表 App，让你对一天和一周一目了然。","f9.t":"使用你的语言","f9.d":"Weekdot 支持 30 多种语言，并跟随设备的语言。","f10.t":"天气","f10.d":"可选择在日期上方查看天气预报。","devices.title":"适用于你的所有 Apple 设备","devices.sub":"一个 App，适用于 iPhone、iPad、Mac 和 Apple Watch。","faq.title":"常见问题","q1":"Weekdot 会取代我的日历账户吗？","a1":"不会。Weekdot 显示和编辑“日历”App 中的日历，因此一切都会继续通过 iCloud、Google、Outlook 或 Exchange 同步。","q2":"我的数据存储在哪里？","a2":"你的日程保留在你自己的日历账户中。Weekdot 自身的设置通过你的私人 iCloud 同步。Weekdot 没有存储你数据的服务器。","q3":"支持哪些语言？","a3":"30 多种，包括英语、荷兰语、德语、法语、西班牙语、意大利语、葡萄牙语、中文、日语、韩语和阿拉伯语。","q4":"我可以添加节假日吗？","a4":"可以。轻点一下即可订阅许多国家或地区的法定节假日，或粘贴任意 .ics 链接。","privacy.title":"隐私","privacy.p1":"Weekdot 的设计初衷是让你的数据只属于你。","privacy.p2":"日历数据：Weekdot 仅在你设备上的日历账户（“日历”App）中读取和写入日程。你的日程绝不会发送给我们。","privacy.p3":"iCloud：Weekdot 自身的设置、模板、日历组、规则、颜色和表情符号存储在你的私人 iCloud 中，以便在你的设备之间同步。我们无法访问这些内容。","privacy.p4":"天气（可选）：打开天气后，你的大致位置会发送到 Open-Meteo 以获取天气预报。Weekdot 不会存储该位置。","privacy.p5":"无需账户，无跟踪，无广告，无分析。","privacy.p6":"有疑问？请通过支持页面联系我们。","privacy.updated":"最后更新：2026 年 10 月 24 日","support.title":"帮助与支持","s1.q":"Weekdot 不显示任何日程","s1.a":"允许完全访问日历：设置 › 隐私与安全性 › 日历 › Weekdot › 完全访问。","s2.q":"如何添加 Google 或 Outlook 日历？","s2.a":"在“设置” › App › 日历 › 日历账户中添加账户（Mac：“日历”App › 添加账户）。Weekdot 会自动显示。","s3.q":"如何更改语言？","s3.a":"Weekdot 跟随设备的语言。在 iPhone 和 iPad 上，你可以在“设置” › App › Weekdot › 语言中仅为 Weekdot 选择语言。","s4.q":"为什么 App 图标不显示今天的日期？","s4.a":"只有 Apple 自己的“日历”App 才能自行更改图标。将 Weekdot 的“今天”小组件添加到主屏幕即可显示实时日期。在 Mac 上，Weekdot 打开时程序坞图标会显示今天的日期。","s5.q":"我的颜色和模板会同步吗？","s5.a":"会，通过 iCloud 同步。请确保你在所有设备上使用同一 Apple 账户登录 iCloud。","footer.rights":"保留所有权利。","lang.label":"语言","mock.Meeting":"会议","mock.Lunch":"午餐","mock.Gym":"健身","mock.Dentist":"牙医","mock.Birthday":"生日","mock.Flight":"航班","mock.Holiday":"假期","mock.Day":"日","mock.Week":"周","mock.Month":"月","mock.Year":"年","mock.List":"列表","mock.Today":"今天","mock.Calendars":"日历","mock.Color":"颜色","mock.Birthdays":"生日","mock.Doctor":"医生"},"zh-Hant":{"nav.features":"功能","nav.devices":"裝置","nav.faq":"常見問題","nav.support":"支援","nav.privacy":"隱私權","meta.description":"Weekdot 是一款快速又精美的行事曆，適用於 iPhone、iPad、Apple Watch 和 Mac，提供日、週、月和年視圖。","hero.title":"一週行程，一目了然。","hero.sub":"Weekdot 是一款快速又精美的行事曆，適用於 iPhone、iPad、Apple Watch 和 Mac。提供日、週、月和年視圖，搭配顏色、表情符號和範本，建構在你已在使用的行事曆之上。","hero.cta":"即將登陸 App Store","hero.note":"支援 iCloud、Google、Outlook、Exchange 以及「行事曆」App 中的所有行事曆。","features.title":"你的所有計畫，盡在一個畫面","f1.t":"7 天週視圖","f1.d":"一次查看整週。可選擇 1 到 7 天，從任何一天開始一週，並以兩指開合縮放小時。","f2.t":"日、月和年","f2.d":"縮小成顯示行程名稱的月視圖，或顯示忙碌日的年視圖，點一下即可直接進入。","f3.t":"拖移、拷貝與貼上","f3.d":"拖移即可移動行程、更改長度、拷貝到另一天，或點一下即可複製。","f4.t":"顏色與表情符號","f4.d":"為行程設定專屬顏色和表情符號，或讓規則根據標題自動套用。","f5.t":"範本","f5.d":"儲存常用的行程，點一下即可加入。Weekdot 也會根據先前的行程建議詳細資訊。","f6.t":"你的所有行事曆","f6.d":"顯示、隱藏行事曆並將其分組，建立新的行事曆，訂閱假日或任何 .ics 連結。","f7.t":"透過 iCloud 同步","f7.d":"你的設定、範本、組合、規則、顏色和表情符號在每部裝置上都相同。","f8.t":"小工具與 Apple Watch","f8.d":"「今天」、「即將到來」和「週」小工具，以及手錶 App，讓你一眼掌握一天和一週。","f9.t":"使用你的語言","f9.d":"Weekdot 支援超過 30 種語言，並跟隨裝置的語言。","f10.t":"天氣","f10.d":"可選擇在日期上方查看天氣預報。","devices.title":"適用於你的所有 Apple 裝置","devices.sub":"一個 App，適用於 iPhone、iPad、Mac 和 Apple Watch。","faq.title":"常見問題","q1":"Weekdot 會取代我的行事曆帳號嗎？","a1":"不會。Weekdot 會顯示和編輯「行事曆」App 中的行事曆，因此一切都會繼續透過 iCloud、Google、Outlook 或 Exchange 同步。","q2":"我的資料儲存在哪裡？","a2":"你的行程會保留在你自己的行事曆帳號中。Weekdot 本身的設定會透過你的私人 iCloud 同步。Weekdot 沒有儲存你資料的伺服器。","q3":"支援哪些語言？","a3":"超過 30 種，包括英文、荷蘭文、德文、法文、西班牙文、義大利文、葡萄牙文、中文、日文、韓文和阿拉伯文。","q4":"可以加入假日嗎？","a4":"可以。點一下即可訂閱許多國家或地區的國定假日，或貼上任何 .ics 連結。","privacy.title":"隱私權","privacy.p1":"Weekdot 的設計理念是讓你的資料只屬於你。","privacy.p2":"行事曆資料：Weekdot 只會在你裝置上的行事曆帳號（「行事曆」App）中讀取和寫入行程。你的行程絕不會傳送給我們。","privacy.p3":"iCloud：Weekdot 本身的設定、範本、行事曆組合、規則、顏色和表情符號會儲存在你的私人 iCloud 中，以便在你的裝置之間同步。我們無法取用這些資料。","privacy.p4":"天氣（選用）：開啟天氣後，你的大略位置會傳送到 Open-Meteo 以取得天氣預報。Weekdot 不會儲存此位置。","privacy.p5":"無帳號、無追蹤、無廣告、無分析。","privacy.p6":"有疑問嗎？請透過支援頁面與我們聯絡。","privacy.updated":"最後更新：2026 年 10 月 24 日","support.title":"輔助說明與支援","s1.q":"Weekdot 沒有顯示任何行程","s1.a":"允許完整取用行事曆：設定 › 隱私權與安全性 › 行事曆 › Weekdot › 完整取用權限。","s2.q":"如何加入 Google 或 Outlook 行事曆？","s2.a":"在「設定」› App › 行事曆 › 行事曆帳號中加入帳號（Mac：「行事曆」App › 加入帳號）。Weekdot 會自動顯示。","s3.q":"如何更改語言？","s3.a":"Weekdot 會跟隨裝置的語言。在 iPhone 和 iPad 上，你可以在「設定」› App › Weekdot › 語言中只為 Weekdot 選擇語言。","s4.q":"為什麼 App 圖像不會顯示今天的日期？","s4.a":"只有 Apple 自己的「行事曆」App 能自行更改其圖像。將 Weekdot 的「今天」小工具加入主畫面即可顯示即時日期。在 Mac 上，Weekdot 開啟時 Dock 圖像會顯示今天的日期。","s5.q":"我的顏色和範本會同步嗎？","s5.a":"會，透過 iCloud 同步。請確認你在所有裝置上都以同一個 Apple 帳號登入 iCloud。","footer.rights":"版權所有。","lang.label":"語言","mock.Meeting":"會議","mock.Lunch":"午餐","mock.Gym":"健身","mock.Dentist":"牙醫","mock.Birthday":"生日","mock.Flight":"航班","mock.Holiday":"假期","mock.Day":"日","mock.Week":"週","mock.Month":"月","mock.Year":"年","mock.List":"列表","mock.Today":"今天","mock.Calendars":"行事曆","mock.Color":"顏色","mock.Birthdays":"生日","mock.Doctor":"醫生"}};
